/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121105-9","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"文教委員会","time":"午後１時００分～午後７時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を117件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)、子ども文化財散策ツアー（新規）の実施","agenda":"の(1)、子ども文化財散策ツアー（新規）の実施","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"すばらしい取り組みだと思います。１点だけですけれども、これは大井第一地区に限ることはないと思いますので、当然、品川区の１３地域とか、その他の地域に広げていって、子どもたちとうまく連携がとれれば、もっといいことができると思うんですが、今後のことについてのお考えをぜひ聞かせてください。","respondent":"齋藤庶務課長","answer":"お子さんたちも、高齢者の人とお話をする、地域の昔話を聞くというのは初めてだという子が多かったので、大井第一地区に限らず、来年度以降はつなげていきたい、子育て支援課と連携しながら広げていきたいというふうに考えております。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鶴委員","kind":"確認","question":"今、関連してなんですけれども、今後いろいろな地域でやりますと、これ、予算の関係で１地域ずつという話になるんですかね。このスケッチを見せていただいたりというような資料提供とかを、これも当然予算がかかると思うんですけれども、可能な範囲でそういう情報を幅広く児童・生徒に伝えていくということが大事ではないかなと思います。この二つをもう一度。","respondent":"齋藤庶務課長","answer":"予算的には、１カ所ですので、来年、荏原地区、特に平塚の碑がありますので、あそこで実施できればなというふうに今のところ考えています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"非常に興味深いおもしろい試みだと思います。どんどん広がっていけばいいなと思うんですが、２点教えてください。ボートを出すとそれなりにかかるかなと思うんですが、地域の文化財を散策するということですと、必ずしも予算的にかかるものばかりではないし、そうすると、複数校あるいは複数回やってもいい事業なのかなと思うんですが、その辺のお考えを教えてください。","respondent":"齋藤庶務課長","answer":"いろいろやりくりをするとできるんですが、なかなか地区の方にご協力いただいて、町会長にあいさつをする勝島運河倶楽部の方との調整、結構いろいろと予算の面ではなくて、時間の制約がありますので、可能な限りポイントを広げてできればいいんですけれども。","voiceIndex":14,"id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"お金というよりは、むしろ手間暇がかかるということで、スタートしたばかりですから、また慣れていけば増えていくのかなと、その辺は期待したいと思います。ふだんはすまいるスクールを使っていないがために、こういう事業にそもそも参加する権利がないというのも、何か寂しいことだなと思うんですが、いかがでしょうか。その辺は何か考えていらっしゃいますか。","respondent":"齋藤庶務課長","answer":"日程も土曜日の午後ということの実施の事業で、すまいるスクールに通ってくださっている子どもさんたちでないと、なかなか参加し難い。ただ、今後の参加の募り方については、ご提案もありましたので、どういった方法がいいかはちょっと考えします。","voiceIndex":16,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そういう点について、ちょっと考え方と、それから、初めての経験ということで、ふだん乗れないようなボートまで乗ったということでは、非常に楽しかったんだろうなというふうに推測できるんですけれども、こういう企画をしたことの返し方というんですか、どういう成果があって、どんなだったみたいな感想文を含めて、ほかの子どもにもやはり興味を持っていただけるような、そういう集約の仕方が。","respondent":"齋藤庶務課長","answer":"やはりボートに乗せるということで、事故があったときの対応、すまいるスクールに登録している子は保険に入っていますので、もちろん事故がないように十分、９人も勝島運河倶楽部の方に来ていただいて対応していますけれども、そういう意味でいうと。","voiceIndex":18,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"昨日ちょっとテレビを見ていたら、たまたまなんですけれども、埼玉県で、埼玉県というのはなかなか郷土に対する愛着というか、そういうものが育ちにくいところだという、そういう言い方をしていたんですけれども、やはり子どもに対してクイズを使って町を見て歩くという、そんな取り組みをしていて、それに何となく近いかなという気もして、今説明を伺っていたんですけれども、やはり自分が過ごす、暮らす町。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"高橋委員","kind":"確認","question":"一つだけなんですけれども、保険のお話が出たんですけれども、すまいるスクールは、学校の中で活動するのが前提というか、それで、当初に入った保険は、校内ではなくて、主に今回みたいに外に出たときも適用されるようなお話だったので、そこの確認と、もしかしたら、もし来年度またこうして外に出ていくようなこういう行事はすごくいいと思うんですけれども、やっていくとなると。","respondent":"齋藤庶務課長","answer":"登録時当初に６５０円ご負担いただいて保険に入っていただいていますが、すまいるスクールの事業活動に伴うものということで整理していますので、外に出て授業を行って何か事故が起きた場合には、保険の対象になるです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"渡部副委員長","kind":"確認","question":"一つだけ、冒頭、説明もいただいていたんですが、来年度、荏原地区のほうでというお話があって、来年度、いわゆる文化財を扱っている庶務課が事業主体になるのか、子ども未来事業部のほう、すまいるスクールを見ている子ども未来事業部のほうが事業主体になっていくのか、そこだけ一つ確認させてください。","respondent":"齋藤庶務課長","answer":"できれば、すまいるスクールのほうを対象として実施したいというふうに考えております。勉強しながら検討させていただきたいと思っています。","voiceIndex":23,"id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"中学校の移動のほうについては、７年生と、昨年度実施できなかった８年生ということなんですけれども、とりわけ７年生のほうは１４校になっているんですけれども、中学校はたしか１５校あったような気がしたんですけれども、そのあたりはどうだったのかというのが１点と、それから二つ目は、小学校の移動教室なんですが、これは日光の光林荘なんですけれども、地域的に放射能の関係では。","respondent":"和氣学務課長","answer":"７年生１４校となっていますが、東海中学校はそもそも８年生で移動教室を実施していますので、このために７年生は１４校という形になっております。従来から東海は７年生ではなくて８年生で移動教室を実施しているです。","voiceIndex":29,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"そうすると、安全だと、そういう判断をして実施をしたということでいいわけですね。一般的に保護者に対してその辺の安全性については、もちろんお知らせはしたんだろうというふうに思うんですけれども、どういう形で、どういうふうに提供されたのか、そこもちょっとあわせて教えてください。","respondent":"和氣学務課長","answer":"基本的に学校は行く際に説明会を開きますので、その中で線量等についてもご説明を差し上げて、やはり個別に私どもにもお問い合わせがありますので、その際には、私どもがきちんと測った線量についてお知らせをして、その上でご判断いただきたいということで回答しています。","voiceIndex":31,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"大丈夫だったという判断で、そういう具体的な数値も示したわけですよね。その上で心配で参加を見合わせたという方はいたのかどうか、そこだけ最後に伺って終わりにしたいと思います。","respondent":"和氣学務課長","answer":"数名程度だという話は聞いてあります。ただ、はっきりとそれが理由でというよりも、今回は欠席しますということで聞いてあります。","voiceIndex":33,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"確認","question":"磐梯高原のことについてやはり聞きたいんですけれども、先ほど、地震の影響があったということを推測はするんですけれども、ご承知のように、その場所そのものが１００キロ以上離れているわけですね、磐梯高原そのものが。そして、地域では安全宣言を出しています。やはり磐梯高原に行けない理由もわかるんだけれども、それを教育委員会としてこれからどういうふうに考えていくんですか。","respondent":"和氣学務課長","answer":"ただ、行く経路とか、それから万が一何かあったときにどう退避するのかとか、そういうところを含めまして、総合的にまだ考える点もありますけれども、基本的に学校として行きたいということであれば、私どもとしては、それは認めていくつもりですが。","voiceIndex":35,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"２年たっているわけでありますし、磐梯高原に行かないという理由は一概にはわかるんです。だけれども、さまざまな安全策を講じた上で、子どもたちが福島の支援ということも、これは私は必要だと思っていますので、今、お考えを聞きましたけれども、ぜひ検討してくださるようお願いしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"大西委員","kind":"質問","question":"これ、非常に私は外に出て宿泊を伴うことで、子どもたちにとってはよい経験になると思いますけれども、子どもたちからのこのことに対する反応というんですか、そういったものについてはどのように捉えておられますか。","respondent":"和氣学務課長","answer":"子どもたちは非常にこれを楽しみにしてございまして、宿泊行事というのは子どもにとって学校生活の中でもかなり大きな思い出に残る部分でございまして、今回につきましても、ほぼ満足していただいている、子どもたちも満足しているという声を聞いているところです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"大西委員","kind":"質問","question":"これは、あと、冬にスキーの合宿に行っておる小学校等もあるというふうに承知しているんですけれども、その場合のことは、学校によって大分差がある、参加している学校、参加していない学校、それと、また宿泊が２泊、３泊、１泊と違うような状況のものもあるように感じているんですけれども、この辺の掌握と実態はどのようになっているかちょっと教えていただけますか。","respondent":"和氣学務課長","answer":"基本はこの移動教室が中止、あとは、夏、夏期施設が中心ですが、一部の学校で冬に実施している学校があります。今年度予定しているのは５校ございまして、基本的にすべて日光光林荘に泊まって冬の体験をするです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"大西委員","kind":"質問","question":"先ほどの一つ目の質問で、子どもたちの反応を聞いたときに、夏、非常に楽しい思い出ができたということからすると、今お話したように、品川では普通どおりにスキーをするという習慣がないと思うんですけれども、私どもはこういう施設を区で所有しているということで、参加される学校というのは、およそ、ひょっとしたら一生に一回という子どもたちもいる可能性があると思うんですけれども。","respondent":"和氣学務課長","answer":"それぞれの学校で年間行事、さまざまな形で子どもたちにとっての楽しいこともあれば、子どもたちに必要なことも含めて実施しております。そういう計画の中で位置づけてありますので、私どもで必ずこういうふうにやれとか、スキーに行けという形では指導はしてございません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"大西委員","kind":"質問・要望","question":"ただ、その辺で経験したら増やしていきたい、撤退する学校よりも増やしていきたいというのが当事者側の子どもたちだったり、保護者だったりするということがあると思うので、少し要望として申し上げておきますけれども、教育委員会として、初めての経験ということを皆が受けられるというチャンスをぜひつくってあげることができればいいのではないかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"少し取り組みを何点か教えてください。中学校のほうなんですけれども、今回、菅平高原が初めてだったと思うんですけれども、私費負担が通常、例年と比べてどうであったのか、多かったか少なかったかという、どのくらいであったかということ確認させてください。","respondent":"和氣学務課長","answer":"ですから、途中で実地踏査ということで、年度初めも行っていますが、年度途中でも行きます。ですから、今年も２回なり３回行ってありますので、そのたびに測ってきているということで確認をさせていただいています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"私、先ほど、質問し切れなかったんですけれども、調査をして放射線量を測ったということなんですが、具体的にどの程度の数値だったのか、問題ないということで終わってしまったんですけれども、具体的な数値を教えていただきたいと思います。","respondent":"和氣学務課長","answer":"地点によって違いますけれども、私ども区の基準である年間０.０２３に達しない数字、すべての場所がそういう数値です。ですから、０.０１９であるとか、その程度の数値です。","voiceIndex":48,"id":"exchange-019"},{"speaker":"南委員","kind":"確認","question":"年度初め、年度途中、そして何回か測っているそのすべてが０.０２３以下だったというふうに確認していいんですか。","respondent":"和氣学務課長","answer":"ご指摘のとおりです。","voiceIndex":50,"id":"exchange-020"}]},{"id":"topic-02","title":"の平成２４年特別区人事委員会勧告の概要","agenda":"の平成２４年特別区人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"確認","question":"今、説明いただいた３ページからの人事制度のストーリー等々について、ここ以下は幼稚園の教員あるいは固有職員、今回のこの改定の対象者となる方々は、関わりがあるのではないかというふうに思っているんですけれども、読んでおいてくださいという説明で終わらせてしまったので、ちょっとその辺を改めて確認したいと思うんですけれども、私はとりわけ。","respondent":"齋藤庶務課長","answer":"これはまず申し上げておきます。健康についての取り組みですけれども、教育委員会は、健康診断については、学校に実施を徹底するように指導を行っておりまして、９９.６％、ほぼ１００％の教職員は健康診断を受けております。","voiceIndex":56,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"毎日毎日、教員の方々の仕事量の多さと、それからこういうメンタルヘルスチェックをしていても５人が出ているという、こういうこと、あるいは現実的に平成２１年度から振り返っただけでも１０名の方々が、がんは含むとはおっしゃっても、そういうことで退職を希望されておられるという、そういう状況をどういうふうに区としては、教育委員会は見ているのかというところをもう一度伺いたいと思います。","respondent":"齋藤庶務課長","answer":"それと、精神面につきましても、産業医を含めて、特に教員につきましては、三つのルートがありまして、三楽病院等の教職員のセンターですとか、かなり手厚い仕組みで守られておりますし、職場復帰に向けても手厚いプログラムがありますので、そういう意味で教職員については。","voiceIndex":58,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"私は、ないとは言い切れないと思いますよ。そうでないと、ぽっかり穴があいてしまって、その手当てをするということだって大変ではないですか。そういう状況をつくらないことがまず第一の教育委員会の仕事ではないですか、条件整備という点では。ですから、ぜひその辺は、ないというふうに言い切らないで、きちんと手当てをするべきだと思います。その辺は要望として受けとめていただきたいと思います。","respondent":"田村教育次長","answer":"一方的に多数決ではないですから、ですから、先ほど来、庶務課長が答えているように、人間ですから、やはり人間ドックへ入っていても、健康診断を受けていても、やはり加齢によるくも膜下なんかは脳ドックへ入らなければ見つからないだとか、がんだとかなんかも健診の中では。","voiceIndex":60,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"それだけのことをやっているということを私たちも初めて知りましたね。それで、しかし、現実的には、２００７、８年あたりからですか、４０代男性の先生、あるいはある学校のバスケットの顧問の先生が突然亡くなるとか、そういう状況があるわけですよね。そういうものをぜひなくしていただく努力をさらにやっていただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、いわゆる品川区の教職員の人数は、今、全体で何名いるのでしょうか。そのうちの、例えば平成２３年度が４名だったとか、平成２２年度が４名であると報告されたんですけれども、どうも数字が一人歩きするので、全体の教員数を改めて教えてください。","respondent":"齋藤庶務課長","answer":"平成２１年度からです。今現在、教員の数が１,００７人、都費も含めて、都費負担のケースワーカーが７７人、平成２４年度は合計１,０８４人です。","voiceIndex":63,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"意見","question":"内容は、突然死ということが学校関係だけではなくて、すべての部署に発生するわけであって、これも先ほどの数字を見ていると、学校現場が大変だから突然死をする可能性が高いというような質疑だったんだけれども、そういうことは私は踏襲したことではないと思うんだけれども、今の含めて、改めて教育委員会の見解をお願いいたします。","respondent":"齋藤庶務課長","answer":"委員ご指摘のとおり、繰り返しそのことをご答弁申し上げておりますが、なかなかご理解いただけないのは残念です。","voiceIndex":65,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"意見","question":"ただ、財源が必要な中で、個々のさまざまな病状があるから、これは一概には言えないんだけれども、結果として病気が出てくる、それは大変なことなんだけれども、だけど、ここで大切なことは、そういう教職員個々の健康管理の意識の向上をどう促していくかということと、それをこのシステムをつないでいくかということのほうに鋭意協力できるように、実現していきたいと思いますが。","respondent":"齋藤庶務課長","answer":"引き続き健康診断の充実、メンタルヘルス面でのチェックの仕組み、産業医につなげて、一人でも多くの方を関係医療機関につなげていく、こういった取り組みを続けてまいりたいと思います。","voiceIndex":67,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"意見","question":"これは学校現場だけではなくて、品川区の職員全体に関わるということもあります。だから、今、総体的なことをお話しするけれども、要は、品川区民のために働くこういう皆さんの生命を守っていくために、さまざまな健康整備システムを活用していただいて、学校現場もそうだけれども、すべての職員の方々が安心して働ける品川区をつくっていっていただきますようにお願いしておきます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと数字を確認させていただきたいんですけれども、最初のご説明の中で幼稚園教諭計３４人中１０人が管理職ということでよろしいですか。ちょっとこれ、人事院勧告の報告の趣旨とちょっとずれるかもしれませんけれども、保育課長がいらっしゃるので、保育園は保育士は何人ぐらいで、そのうち管理職は何人いるんですか。","respondent":"立川保育課長","answer":"保育園につきましては、今、数字はないんですけれども、現在、大体７００名、管理職はゼロ。","voiceIndex":70,"id":"exchange-029"},{"speaker":"阿部委員","kind":"確認","question":"この話はこれ以上突っ込むとちょっと話が長くなってしまいますので、それだけの確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"今回の選考から日程をずらしたかなと思うんですが、ちょっと参考までに、前回、前々回の候補者の全体数を教えてください。それから、今回の受験者数の中で、新卒と、現職の方も今回はいらしたんですが、内訳を教えていただければと思います。","respondent":"太田指導課長","answer":"昨年度は、第一次選考が８月２８日、第二次選考が１０月２日、そして最終面接が１１月１５日で、こういった日程で行われております。選考状況につきましては、今年度、最終的に内定６名のうちですけれども、経験者が３名、一般の受験が３名というような内訳です。","voiceIndex":77,"id":"exchange-031"},{"speaker":"阿部委員","kind":"質問・要望","question":"今回、申込者と受験者数ともに、かなり減少の変化になったと思うんですけれども、その辺は教育委員会としてどのように捉えていらっしゃるか。辞退者はどのような理由で辞退されたのか、わかれば教えていただきたい。","respondent":"太田指導課長","answer":"辞退理由につきましては、他の自治体の採用試験も合格しているということで、品川区と悩んだんだけれども、そちらのほうの採用に行くということでの辞退が１名出たです。","voiceIndex":81,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"私、他の教員試験の日程をちょっと頭の中に把握していないんですけれども、今後このような理由で結果がさらに減るということはないと考えていいのでしょうか。要は、２回、３回と機会があれば、いろいろ受けられると思うんですけれども、そうした時期はもう終わっていて、ほぼこの６人は確定でしょうか。","respondent":"太田指導課長","answer":"今のところはそういうふうに考えております。","voiceIndex":83,"id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのうちのどれぐらいまでを区の固有教員を確保していくのか、その計画を改めて伺わせていただきたいのと、それから、大切なことは、その先生たちをどういうふうに学校に配置をしていくか、活用していくかということのほうが、私たちとしては、より柔軟だと思うんですが、改めてそのお考えを聞かせてください。","respondent":"太田指導課長","answer":"人数ですけれども、おおむね３０名ほどは採用したいということを考えております。配置につきましては、それぞれ品川区が推進している小中一貫教育を進めるに当たって、適正に配置をしてまいりたいと。","voiceIndex":85,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろんそういう答弁で間違ってはいないんですけれども、３０名を採用する計画があって、それでも何名かは繰越しますよね。他の先生が働いていないと言っているのではなくて、より品川区のことを理解していただいて、さまざまな教育改革をすすめていただきたいと思ってされていたと思うんです。","respondent":"太田指導課長","answer":"研修につきましても、今年度より区の独自教員、固有教員だけを対象とした区長をトップとした研修を立ち上げまして、区の固有教員としての誇りとか、そういったことについても持たせるような形で研修を進めているところです。","voiceIndex":87,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問・要望","question":"改めて聞きますけれども、この方々はまさに品川区の税金だけで採用しているわけですから、ある意味、区民の皆さんの希望に的確にこたえていくことをだれも願われるはずです。そういうことを考えていくと、今のことはまさにより具体的に展開していっていただいて、品川区の教育改革を進めていくまさに原動力となっていただくような教員に育てていただきたいということをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"今の質疑について質問しなくてはいけないのかなというふうに思ったんですけれども、区費で採用した教員も都費の教員も同じ子どもを教育するいわゆる教師という役割ですよね。全然違いはないというふうに思うんですけれども、その辺についての認識をまず伺いたいと思います。","respondent":"太田指導課長","answer":"全くかわりはございませんけれども、一つ、都の教員はおおむね６年程度で区から離れるということがありますけれども、区の固有教員はそういうことがございません。","voiceIndex":90,"id":"exchange-037"},{"speaker":"南委員","kind":"確認","question":"そうすると、今でも１年生から中学３年生、いわゆる９年生までは、その学年に応じたカリキュラムに基づいて教育指導を行うということですよね。６年たったら別の場所に行く行かないは全然別として、その学校の中で教師としての仕事を行うという点では、区費であろうと、都費であろうと同じだということだというふうに思うんですけれども、その確認。","respondent":"太田指導課長","answer":"そのとおりです。","voiceIndex":92,"id":"exchange-038"},{"speaker":"南委員","kind":"意見","question":"そうすると、今、質疑の中では、区採用の教員には、区長を講師として研修をすると、そこのところを同じ仕事を行っているのに、なんで区に採用の教員だけがそういう研修で、ほかの教員はそういう研修の対象にはならないのか、その辺についての教育委員会の考え方、設定をした、何を目的にそういう研修を設定しているのか、その辺を知りたいと思います。","respondent":"太田指導課長","answer":"まさに先ほどお話があったように、区固有教員は区民の方々の血税で給料が支払われておりますので、その教員たちに区として研修するのは当然でありますし、また、都の教員は、都での研修がありますので、そういった形でやっております。","voiceIndex":94,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"そうすると、区の職員は都の行う研修には参加できないんですか。できないのであれば、そういう研修の対象が違うということはあるかもしれないけれども、私はできるのであれば、区費で採用した職員だけ取り立てた別個の研修をするということの意味がわからないんです。どういう目的でそういう研修を設定しているのか、そのあたりを知りたいんですけれども。","respondent":"太田指導課長","answer":"先ほどから申し上げているんですが、区の固有教員は区民の皆さんの税金で給料を支払われておりますし、ずっと区の子どもたちにかかわっていく教員ですので、そういった教員に対しては、やはり区としてそういった区の教員としての誇りを持たせるとか。","voiceIndex":96,"id":"exchange-040"},{"speaker":"南委員","kind":"確認","question":"全然理解できないですね。私は、さっきも確認したように、都費の教員だろうと、区費の教員だろうと、やる仕事は同じですよね。子どもに教育をするという点で、カリキュラムに応じたそういう内容で教育を提供していく、ここは同じなのに、なぜ区費の教員だけ、品川区の歴史、そういうものを教えて、都の教員にはそういうことを教える必要はないというふうに考えているんですか。","respondent":"田村教育次長","answer":"あわせていずれこの人たちが、今は主任、主幹まではいますけれども、年齢が来れば、副校長、校長という形の役回りも当然出てきますから、その辺の若手のころから横のつながりを持って中核として活躍してほしい、そういう思いから研修を実施しているものです。","voiceIndex":98,"id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"格差というか、そういうものを教育委員会がおおっぴらに職場の教育職の中に持ち出してきていることなのではないかなというふうに思うので、私はやめるべきだと、そういうふうに思います。品川区の教育を実践してもらいたいのであれば、同じようにやればいいではないですか。なぜ品川区の固有教員だけ突出してやっているのか、そこがいくら聞いてもわかりません。私はむしろやめるべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-042"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"いろいろやはり品川区に就職をいただいたわけですから、当然区のこともわかっていただかなければならない。こういう機会ですから、せっかくここまで１２名、これからまた５名の方が入られる、今年のパンフレットを見させていただいたら、先輩区費教員の方々が、いわゆる一般企業でいうリクルーターのような形で、さまざまなことを書かれて、新たに品川区に来ようとされている方に呼びかけをされていた。","respondent":"太田指導課長","answer":"そういったところに非常にメリットを感じているところです。","voiceIndex":101,"id":"exchange-043"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"先ほどもご説明ありました今年から小学校の教員免許を保有していて、なおかつ中学校の学科の免許も持っているという、またすごく幅が狭まった中で、どれだけ貴重な人材を区で確保できるかということでが、これはもう本当に地域の方々にしましても、子どもたちにしても、これはいいことですし、何か３０年に向けて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-044"},{"speaker":"阿部委員","kind":"確認","question":"１点だけ確認させてください。固有教員の方、いろいろな形で都費の教員と同じような機会を与えられていたと思うんですけれども、管理職登用についてはどうなっていたんですか。","respondent":"太田指導課長","answer":"今後、副校長、校長というようなところで道を目指せるように制度をつくっていかなければいけないというふうに考えております。","voiceIndex":104,"id":"exchange-045"},{"speaker":"阿部委員","kind":"質問","question":"今、この区費の方の一番経験の長い方といいますか、年齢の高い方はお幾つぐらいの方なんでしょうか。","respondent":"太田指導課長","answer":"４５歳です。","voiceIndex":106,"id":"exchange-046"},{"speaker":"阿部委員","kind":"意見","question":"４５歳となると、そろそろやはり上を目指してもおかしくない年齢だと思いますので、今後つくっていきたいということのままで行ってしまうと、やはりこの方々の道がつながらないという、それは非常に閉塞感があることだと思いますので、もし検討について、何かもう少し踏み込んで説明していただければありがたい。","respondent":"田村教育次長","answer":"正確に申し上げますと、平成２４年、今年に主任教諭に昇任したのがお一人、それと、平成２４年、今年に主幹教諭になった、あまり個別の年齢を言ってしまうとあれですが、教員の方は４５歳の方が今年主幹になったということなので、若干おっしゃるとおり。","voiceIndex":108,"id":"exchange-047"},{"speaker":"高橋委員","kind":"意見","question":"あえていろいろな理由があるのかもしれませんが、導入をしていない理由と、今後、模擬授業の、ほんの数分でも教育委員会の方がご覧になればおわかりになると思うんですけれども、わずかな時間でもそういった模擬授業を面接の中に、今後その点についてどう検討されているか。","respondent":"太田指導課長","answer":"二次選考では、個人面接と集団面接ということで申し上げたんですけれども、教科の模擬授業はないんですけれども、集団面接では、模擬で学年会というような教員の中の会議をロールプレーしていただいて、それぞれの立場でどのように教育のことについて考えているかとか。","voiceIndex":110,"id":"exchange-048"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後、例えば入られたこういうふうな方々は、例えば、算数や数学の教え方は非常に上手だよと、それはこうした面接の中でも十分そういった方を採用していっている等があればそれはそれでいいんですけれども、今後やはり１００％授業を見て受かるか受からないかではなくて、教員の資質の一つとして授業の能力というのもやはり考慮していただいたほうが、当然すぐ４月から授業をやるわけですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"}]},{"id":"topic-03","title":"のいじめ等の調査状況","agenda":"のいじめ等の調査状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"委員長、その前に、これだけの分厚い資料が今配られたんですけれども、でき上がったのはいつだったんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"私は、できるだけ早く手元にいただきたかったと、こういうふうに思います。それで、今度は教育委員会に伺いたいんですけれども、これができ上がったのは、何月何日の何時ごろだったのか、少なくとも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"最初に聞きたいです。そこも答弁していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"そこもお願いしたいということをお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点かお伺いさせていただきたいのですが、まず、ご遺族の意向について、当然触れていないんですけれども、だけれども、ご遺族の意向を品川区としてどういうふうに考えていらっしゃるのか。それから、とても大切なお子様の死に、このことに対して、さまざまな想いがあると思われますが、まずやはり確認したいのが、ご遺族は今後のこと等についてどういうようなお考えをお持ちなんでしょうか。","respondent":"太田指導課長","answer":"ご遺族の意向、今後のことですけれども、ご遺族におかれましては、今回のこのいじめに対して、事実はどういうことなのか、そういったことを明らかにしてほしいというようなことがまずございまして、いろいろそういったことに我々も対応してきたところです。","voiceIndex":126,"id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"理解するところはあるんですけれど、私たちがやはり限界をという想いがするのですけれども、こういう状況の中で、何を最優先しなければいけないかということを考えたときに、やはり一番悲しんでいらっしゃるご遺族のことだと思うんです。だから、確認したいのは、ご遺族がこれからどういうことを望んでおられるかということをぜひお伺いしたいんです。","respondent":"田村教育次長","answer":"それで、先ほど、説明の中に、特にページの中から細かく出ている保護者のほうからの申し出という内容が、やはり何らか自殺につながるきっかけがあったのではないかということで、事後、いろいろなヒアリングだとか、事実関係を聞いたということも、先ほど。","voiceIndex":128,"id":"exchange-055"},{"speaker":"伊藤委員","kind":"確認","question":"そういう当事者の気持ちを最大限に尊重していかないといけないと思いますので、それを改めて指摘しておきます。とすると、もしかすると教育委員会の中でそういう情報を当該委員会にかかる前に出してしまった可能性が推測としてあるんですけれども、私はないと思っているんですが、ただ、記事に書かれていることもそれとしてありますので、そのことについての事実確認をお願いしたいと思います。","respondent":"太田指導課長","answer":"この一連のマスコミに対する対応につきましては、私、指導課長が窓口一本ということで対応してまいりました。その際、ここに書かれているような内容、委員会の審議内容、審議日程等も含めてですが、私の口から申し上げたことはございません。","voiceIndex":130,"id":"exchange-056"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、確かに指導課長の答弁はそのとおりなんだけれども、だけど、記事に出ていることもまた事実でありますから、やはりそのことについての情報管理といったらいいんですか、特にこれは非常に重要な話ですから、憶測や推測で物事が外に出て、取り返しのつかないことになると思いますから、もう一回だけ危機管理についての態度を改めてお聞かせいただきたい。情報の管理について。","respondent":"太田指導課長","answer":"委員のおっしゃるとおりでございまして、特にこういったような内容につきまして、情報管理については、電子、それから文書等も含めまして、これからも徹底してまいりたいというふうに思っております。","voiceIndex":132,"id":"exchange-057"},{"speaker":"伊藤委員","kind":"確認","question":"だから、私たちは本当に今日わかった、ご説明いただいたんだけれども、したがって、真実ということ自体が、これがやはり問題だということは指摘をせざるを得ませんので、これ以上やってもあれでしょうけれども、この点だけ確認をお願いします。","respondent":"田村教育次長","answer":"教育委員会については、既にこの案件については３回非公開で実施しておりますが、同様に、マスコミ等が来ても、決して審議内容が漏れたり、聞かれるような状況は一切ない形で審議を進めてまいったです。","voiceIndex":134,"id":"exchange-058"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひ、情報管理についてあわせてお願いしておきます。それから、この中身ですけれども、非常に現実的な学校現場の対応が起きてしまったということが書かれているわけです。やはりこのことについても現場の教員の対応、当該学校の対応が不適切であったということは、この報告書から読み取れます。だけど、確認したいのが、そういう認識でいたんですか。やはりこのことは確認しておかなければならないでしょう。","respondent":"太田指導課長","answer":"今回、調査をいたしまして、当該校の担任及びその他の教員も含めまして、そういったような指摘されているような状況であるということは自覚しておりませんでした。今回ここで初めて指摘されて突きつけられているという状況です。","voiceIndex":136,"id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問","question":"だから、そういうことを踏まえた上で、では、これからどうするかということについてやはり考えていくと、子どもたちのちょっとした変化であるとか、それから、今まで大人が見てきたいじめの態様の経緯であるとか、そういうところを学校現場では想定しているかということを真剣に取組んでいかないと、この問題はまた再発する可能性があると思うから、改めてＡ君事件の反省。","respondent":"太田指導課長","answer":"課題もご提言いただいておりますので、そこを真摯に受けとめて、要は、やれと言ったから、やったからもういいんだではなくて、それがどのように学校で行われているのか、どういうことがまだ足りないのかということを教育委員会でもしっかり今後の対応で把握して。","voiceIndex":138,"id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"少し話を前に戻して、家庭訪問はされていたんですか。つまり、Ａ君のことも含めて、さまざまな関係する子どもたちがいるわけではないですか。そういう子どもたちの家庭状況を把握した上で指導を一体的にしていくことを、されていたんですか。していなかったとするならば、これからどう行っていくのかということを改めてお聞かせください。","respondent":"太田指導課長","answer":"今後、おっしゃるとおり、家庭の状況を把握するというのはとても大事なことですので、今までも学校等いろいろ、三者面談であるとか、そういったことにもいろいろ状況に応じて対応してきているところですけれども。","voiceIndex":140,"id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"報告書に書かれているように、学校現場の中の対応では限界があると書かれているわけです。当然、家庭の状況を把握していなければいけないだろうし、地域の方々の協力も取り入れた上で、一体的にいじめを解決していくシステムをつくっていく。ですから、改めてこういう一体的な指導の中の一環として、家庭訪問についてお聞かせください。","respondent":"太田指導課長、田村教育次長","answer":"位置付けとしてというお話ですけれども、確かに委員先ほどおっしゃっていただいたように、それぞれの家庭の事情とか、そういったこともありますけれども、家庭の状況を、子どもがどういう家庭で生活しているか。今回の事案、先ほど、るるご説明しておりますけれども、一番の原因というのは、決して責任をだれかに転嫁するということではなく、やはり子どもがそういうサインを発信しているときに。","voiceIndex":142,"id":"exchange-062"},{"speaker":"伊藤委員","kind":"質問","question":"それはまた教育の側面からすると、それもまた別の指導が必要だと私たちは思います。非常に難しいと思いますけれども、そういう加害児童・生徒に対するフォローと言ったらいいでしょうか、そういう事実を認めてもらうと同時に、逆にそのことによって、またいじめが起こったら取り返しのつかないことになるわけであって、それは非常に慎重にやっていかないと、今度はまた別な形でいじめが発生する可能性がある。","respondent":"太田指導課長","answer":"ただ、今回、どういうふうにそれをということもありますので、例えば、スクールカウンセラーを増員して少しでもそういった子たちに目が届くようにするとか、そういった具体的な策を練りながら、そういった子どもたちにも対応していきたいと考えています。","voiceIndex":145,"id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これも非常に重要なことです。もちろんそれは全部やっていただきたいし、やってほしいのだけれども、要は、心の中を見ると言ったらいいんでしょうか、本当に悩んで苦しんでさまざまなサインを出している児童・生徒の心をどういうふうに把握していくかという、突き詰めてそこに行くと私は思うんです。学校全体で対処していくしくみ作りについてどういうふうにしていくことができるかをお聞かせください。","respondent":"太田指導課長","answer":"システムだけでもだめですし、意識だけでもだめなので、その両方をしっかり学校の中につくっていくことが大切かというふうに考えています。","voiceIndex":147,"id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"繰り返しますけれども、再発防止のためにさまざまな機関をつくって検討するということは、もちろんいいです、やっていただきたいし、やらなければいけないことです。やはりそのことはもう思いは伝わっていると思いますので、常に対処していっていただきたいとお願いしておきます。それから、今度は、いじめ防止に関する手引書の扱いは、これからどうされていくんですかということの確認だけお願いいたします。","respondent":"太田指導課長","answer":"いじめ防止に関する手引書については、手引書を使ってさらに、あの活用をどうするのかというところ、例えば、担任のチェックリストがありましたけれども、ただ単にあれがありますよではなくて、どういうふうに使うのか、どういうふうに使われているのかということも確認しつつ。","voiceIndex":149,"id":"exchange-065"},{"speaker":"伊藤委員","kind":"意見","question":"だから、せっかく手引書を、８月２０日に文教委員会でご報告いただいていましたから、今後は十分に活用していっていただきますように徹底をお願いします。議会がどんなに頑張っても、これ以上のものをつくることはできないと思いますので、これは議会の権限を大きく逸脱すると思いますから、このいじめ等の調査・対策報告書に沿った対応をしていくことが適切だということを意見として述べさせいただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"１週間に１回か２回程度の配置では不十分過ぎるのではないかという。はなはだそういう意味で残念だというふうに思います。そういう家庭の協力があるのに、しかし、自殺は防げなかった。二つ目です。そこのところの反省がなくて、学校全体でみるだとか、こういう報告をしろだとか、ＣＡＰをやれだとか、そういうことでは私は決して根本的な解決にならないと思いますけれども、その辺の見解はいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"なぜ３％にとどまっているのか、マンネリ化しているというふうには書いてありますけれども、それだけではないと思うんです。同じ学年で連絡もとりあえず、そういう状況に、組織としてはあるけれども、そこにつながっていかない、そういう現実があるのではないですか。その辺についての分析は教育委員会としてどのように見ているのでしょうか。ぜひまとめて伺いたいと思います。","respondent":"太田指導課長","answer":"ですから、この中身については、ますは調査対策委員会でご検討いただいたその内容ですので、そこを押さえていただければなと考えています。","voiceIndex":154,"id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"この調査対策委員会がまとめられた報告書は、１０月２９日にできているわけですよね。〔「今日の朝でしょう」と呼ぶ者あり〕 それで、何日かあるわけですよ。教育委員会がこれを受けて、しかも事務局を教育委員会が担っていたわけですから、その間の検討の推移というのは当然把握しているわけでしょう。そこがされていなかったのか、していたのか、ちょっとそこだけでいいですから答弁してください。","respondent":"太田指導課長、田村教育次長","answer":"一つは、この内容を真摯に受けとめたです。それで、この内容について、委員おっしゃるように、短期間で全部がこちらのほうとして対応を具体的にやれるような、そういった内容ではなく、本当に非常に深い内容ですので、そこら辺は……。それで、南委員、先ほど来からおっしゃっていますが、私たちは、先ほど、指導課長が説明したんですけれども、今回は事務局で何かをつくって議論させるというやり方はとっていませんので。","voiceIndex":156,"id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"全然この間も議会でそういうふうにやっているというのは聞いておりますし、事務局として教育委員会がそういう事務を受けているということで、１日かけてご議論いただいた、調査をされたその内容についてまとめをされた。質問しているんです。それはここに書いてあるではないですか。組織的に生かされていなかったのではないか。そこについてはどうなんですかというふうに聞いているんです。正確に聞いて。","respondent":"太田指導課長","answer":"内容につきましては、本当にその内容のとおりだと考えていますし、それを真摯に受けとめております。","voiceIndex":159,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"具体的にどういうふうに教育委員会として、その議論の最中に、その発言があったときにどういうふうに受けとめて、真摯に受けとめたんだったら、その次の委員会までにこういうふうにしていかなければいけないのではないか、あるいはまとめ上がる時間までにこういうふうにしなければいけないのではないかと、教育委員会の事務局の中で検討したことはあったんですか。私はきちんとそれはするべきだと思うんです。","respondent":"太田指導課長","answer":"報告書の２６ページにもありますけれども、要するに、いろいろな調査等、それから学校の指示等出して、教育委員会として出していったにもかかわらず、当該校におけるいろいろな不備、事実。","voiceIndex":161,"id":"exchange-071"},{"speaker":"南委員","kind":"意見","question":"そうであるならば、どういうふうにこれからしていかなければいけないと考えているのか、まだ検討がされていないのだったら、いつの時点でそういう検討をしていきたいと思っているのか、そこについてもお知らせしてください。","respondent":"田村教育次長","answer":"例えば、この経過の中で１４ページの下段のほうに、既にスクールカウンセラーの配置もやったり、都のアドバイザー、１４ページの右から二つ目の都のアドバイザーを２名派遣したり、あと、参与ということで既に学校経営。","voiceIndex":163,"id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"ここの報告にも出ていますけれども、７月にとったアンケートの当該の男子生徒が、いじめは解消したに○をしてあって、その脇にクエスチョンマークがついていた。しかし、そのクエスチョンマークは見落とされていたとなっていますよね。たとえマルバツであったにしても。それが気にしなかった、見落としてしまった、そこは何というふうに教育委員会は見ているんですか。","respondent":"太田指導課長","answer":"そこについては、報告書の言葉をかりれば、教員のいじめに対する認識の低さ、そういったところになるのではないかなと思っています。これに対しては見落としたわけではない。このアンケートに関して、？印を見落としたわけではございません。","voiceIndex":165,"id":"exchange-073"},{"speaker":"南委員","kind":"質問","question":"見落としていないというふうにおっしゃるけれども、何をもって、どこにどういうふうに書いてあるんですか。もう１回さっきのさらっとした説明では私はちょっとわからないので教えてください。","respondent":"太田指導課長","answer":"先ほども私、経過の中でもお話しさせていただきましたけれども、そのアンケート後に、８ページに書いてありますけれども、本人に声をかけ、大丈夫という回答を得る、大丈夫であるという本人回答と、その後、物が壊されるという訴えがないために。","voiceIndex":167,"id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"やはり先生がそのクエスチョンマークを気にするということは、やはり直後に一定程度の働きかけがあってしかるべきですし、やはりそういうことがないということは、ここのところで後でこれだけしたというふうになっているけれども、しかし、それはクエスチョンマークだけではなくて、日常的な事前に先生に相談をしていたとか、そういうことがあっての声かけであるということも否めないわけではないですか。","respondent":"太田指導課長","answer":"ですから、時間とかではなくて、そういったことを見るのが教員として当たり前の本来業務。多いとか何とかではなくて、それは教員としてやるべきことなんです。ですから、そうご理解いただきたいと思います。","voiceIndex":169,"id":"exchange-075"},{"speaker":"南委員","kind":"質問","question":"私もそう思います。本来であれば、いろいろな学校の現場の先生に私も何人か聞いてみました。９月のときのアンケートもそうですけれども、やはりいきなりドッカーンとおろされてきて、いきなり保護者会をやりなさい、アンケートをとりなさい、そして一人一人個別に面談をして、子どもの状況を掴みなさいと、そういうことが突然おろされてくる。そういう実態をご存じなんですか、教育委員会としては。","respondent":"太田指導課長","answer":"それは必要だから我々のほうとしても判断していますし、すべての文書をそんなような状況で出しているわけではもちろんありませんので、逆に言うと、今回それだけ事の重要性を我々も感じていたというふうに、そういうふうにご理解いただければと思います。","voiceIndex":171,"id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"そうしたら、７月のときのアンケートは、自宅に帰り、家族と一緒に書きなさいというふうにおろしたということですけれども、何日かけて報告を出しなさいというふうになったんですか。","respondent":"太田指導課長","answer":"学校によって回収の日時は違うと思いますけれども、家に持って帰るというのは、保護者の方にも一緒に見てもらったり、状況をわかってもらうために、それからあとは、学校ではなかなか、特にいじめられている子が、いじめている子がいるところでそういったことは書きづらい。","voiceIndex":173,"id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"そのことのように、家庭に持ち帰らせた時間はあったものの、しかし、その後、教育委員会に報告として上げているのが、やはり非常にタイトな時間なわけですよね。そういう認識はないですか。","respondent":"田村教育次長","answer":"ただし、先ほど来繰り返すように、やはりこういうケース、命にかかわる問題は、最優先で対応するのが教育委員会としての責務だと、そのように考えておりますので、ぜひご理解いただきたいと思います。","voiceIndex":179,"id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"そのことの改善なくしてどんなに学校の組織をよくする、研修をやる、いろいろな職員を配置する、こんなことをしても基本的な仕事量が解消されていかない限り、そこに携われる時間がとれなくなるわけではないですか。ですから、根本的なところをやはりぜひ解決するべきだというふうに思うし、そこをぜひ協力して教育委員会は対応していただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"そうすると、今日この委員会の中でこれをもとに質疑をしているわけですけれども、この１回でこの話が終わってしまっていいんでしょうか。それについて、ぜひ、正副委員長にお考えいただきたいなと思うのがまず１点です。やはり一つ一つの行動を振り返って、その状況が私は知りたい、これについて教育委員会としてお考えを伺いたいと思います。学校はいじめさえなければいいという場所ではないですから……。","respondent":"金野委員長、太田指導課長","answer":"これは報告書も今日いただいたので、副委員長と、今後どうするかというのは検討させていただきたいと思いますので、一旦これは預からせていただきたいと思います。よろしいでしょうか。３点目については、自殺の防止の対応についてどうかということですけれども、確かに今、市民科等で行っている命を大切にするというような指導についても、死というものに対するそういった認識とか。","voiceIndex":184,"id":"exchange-080"},{"speaker":"阿部委員","kind":"質問・要望","question":"だから、私が悪うございましたというのでは、次の再発防止にならないので、そうではなくて、では、どう具体的に改善したらいいのかということもそれぞれ一つ一つのときが大切だったという、一つ一つを振り返っていただいて、小学校のときはどうだった、中学校へ入っていろいろ壊されたときにはどういう指導をすべきだったのか、ここで言葉だけの指導だったのか、そうではなくて。","respondent":"太田指導課長","answer":"特に第５のいじめの対応の課題とか、それに対する対応も第６に出ておりますので、非常に分析的にいろいろと出ておりますので、そこのところをまずは注目して取り組んでいく必要があるかと思っています。","voiceIndex":187,"id":"exchange-081"},{"speaker":"阿部委員","kind":"質問・要望","question":"もうこれは要望ですね。学年間の連携ができていない、何かができていないのはやはり理由があるわけで、なんでこの学校の中で学年間の情報が伝わらない状態になっていたのか、反省しますということではなくて、何が阻害要因になっていてできていなかったのか、できていないものをこれからつくっていくにはどうしたらいいのかということをきちんと具体的に検討していただきたいと思います。","respondent":"太田指導課長","answer":"今委員おっしゃったような学年間のというふうなことについても、この報告書に具体的に書かれています。それで、例えば、学年間の中学年団で５・６年と７年がなかなかフロアで、教師コーナーがあっても連絡がとれない。","voiceIndex":189,"id":"exchange-082"},{"speaker":"阿部委員","kind":"質問・要望","question":"そこをぜひ考えてほしいんです。それをもっと深く突いてほしい。今のは要望にしておきます。それから、次の質問です。８月の文教委員会で、例のいじめ防止に関する手引書のご報告があったときに、私、長々といろいろなことを言ったと思うんですけれども、その中で、国立教育政策研究所のいじめに関する手引き、あれ、ぜひ見直してほしいというようなことを言ったと思います。あれ、読んでいただけましたか。","respondent":"太田指導課長","answer":"改めて読みました。","voiceIndex":191,"id":"exchange-083"},{"speaker":"阿部委員","kind":"質問・要望","question":"子どもを見る目というのをきちんと常に教育委員会としては責任をもって育ててほしいと考えています。もう一つかな、二つかな。だから、一方では、教員に対していろいろと、もう１回振り返ってほしいことはあるんですけれども、物理的に非常に長い時間を拘束するようなものというのは、ぜひ真剣に精査して取り組んでいただきたいなと考えています。教員に対する心のケアというのは。","respondent":"太田指導課長、齋藤庶務課長","answer":"特に教員ということではないですけれども、スクールカウンセラーを増員し、配置しておりますので、そこで教員のそういった、これは教員にも当たるということ。それから、事案発生後については、例えば……。産業医の先生もいらっしゃいますので、精神的な問題で、多忙感のある先生については、こういうふうにケアをしていきたいというふうに考えています。","voiceIndex":193,"id":"exchange-084"},{"speaker":"阿部委員","kind":"質問・要望","question":"一応受けているということなんですけれども、多忙感とかということではなくて、やはり責任感とか喪失感とか、その部分は非常に大きいと思うんです。多分責任の問題とは別に、やはり今回のことで、ひょっとすると、当然、ストレスが出てくるのでしょうし、抑鬱状態等々についてもぜひ気をつけていただきたいと思います。そこは一方でよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-085"},{"speaker":"鶴委員","kind":"質問・要望","question":"ちょっと今、各委員からいろいろ何度も同じような確認とかがあったかもしれませんけれども、いま一度、このアンケート結果を受けて、教育委員会として懸念していたことがきちっと報告の中に挙げていただいたという観点と、それから、まさかそんなことがあったのかという、両方のご意思があったと思うんですが、その辺を率直に、どういうふうに受け止めたのか、もう一度だけ教えていただきたいと思います。","respondent":"太田指導課長","answer":"そのアンケート結果については、学校ごとから挙がってくるものについて、我々としてもその状況がどうであるかというのは、例えば校長に直接電話をして指導主事がヒアリングをしたりということを７月３１日の通知でも行っているところなんですけれども、ただ。","voiceIndex":197,"id":"exchange-086"},{"speaker":"鶴委員","kind":"質問","question":"あわせて、今、アンケートをとって、もう一つがこの調査報告書、こういうことを書いていただいているということです。そこについてはどうでしょうか。","respondent":"田村教育次長","answer":"当然いじめはどこでもある。それと、お子さん自身も、これはすごく今回のケースで難しいのは、成長の過程で絡み合ったり、けんかしたり何とかというのは、成長の過程で十分あり得ることですから、ほんとうにサインを見逃さないというのが、やはり学校とすれば一番大事と。","voiceIndex":199,"id":"exchange-087"},{"speaker":"鶴委員","kind":"質問","question":"これからのことというのは、本当にこれでもかというぐらいたくさんの対応策というのはあると思います。手を尽くしていって、それで終わり、それでいいということはないと思うので、それは今、ご答弁いただいたことに尽きると思うんですが。ただ、本当に残念ながらというか、やはりこれ、資料編についても含めていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-088"},{"speaker":"鶴委員","kind":"質問・要望","question":"これで２段落目の２行目あたり、ここに「いじめはあったのです。ですから、人権感覚の向上に関する研修を今後やっていくよ、今やっているよというふうになりますけれども、ここをとにかく外さずやっていただきたいということを、一つ具体的なお話としては、この間の遺族の方の先ほどの思いとして四つ、教育次長のほうからご答弁いただいて、該当校以外でも決して同じことを起こさないという話がありました。","respondent":"太田指導課長","answer":"その当事者をどう活かすかということですけれども、指導の段階といいますか、それによって、例えば今の状況が少し学校も落ち着いて、子どもがそれを受け入れられるような状況になれば。","voiceIndex":203,"id":"exchange-089"},{"speaker":"鶴委員","kind":"質問・要望","question":"だからこそ学校の６年間ないし９年間という、本当に一番基礎を築ける、教科書の勉強だけではなくて、ある意味、人格形成していくその部分の教育ということがいかに大事かということを痛いほど私は経験しているので、特にそこについてどうか、改めてですけれども、本当に徹底してその部分の教育、競争教育ももちろん大事な部分はあるかもしれませんけれども、やはり人間の土台の部分の教育。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-090"},{"speaker":"大西委員","kind":"確認","question":"一つ確認をしておきたいんですけれども、私は平成１２年２月くらいか、予算特別委員会の総括質疑のときに、当時、今はもうおられない、もう退職されていますけれども、教育次長に家庭訪問についての質問をし、当時は強制的には教育委員会はこのことに立ち入っていないということで、学校任せにしておるということについての答弁があったので、それはちょっと考え直すべきではないかと。","respondent":"太田指導課長","answer":"学校任せというよりは、学校ごとのいろいろな家庭等の状況によって、家庭訪問を実施している学校もありますし、何か問題があれば、各学校は必ずそういった児童・生徒の家には家庭訪問をして対応するということはありますけれども、例えば。","voiceIndex":206,"id":"exchange-091"},{"speaker":"大西委員","kind":"質問・要望","question":"要望等も入れておきます。それともう１点、この定義３の報告書の中で、右側の当該校が定例報告で４月から６月の区教育委員会の報告、当該校から「該当なし」の報告もなしとなっていますけれども、これはサボタージュであるのか、それとも故意に報告をしていないのか、これに対して教育委員会はどのような対応をしたのかということについてお尋ねしたいんですが、いかがでしょうか。","respondent":"太田指導課長","answer":"３ページの４月から６月のですけれども、当該校においては、あえてということではございません。該当がないために提出しなかったです。それで、教育委員会のほうも、それについては該当がなかったという理解をしたです。","voiceIndex":208,"id":"exchange-092"},{"speaker":"大西委員","kind":"質問・要望","question":"各断層にわたる。私は、娘が高校生、今、１年生の娘を持っていますけれども、大変怖い学校だなと、これは子どものことを考えると、この亡くなったお子さんは、およそ恐怖と絶望だったと思うんです。教員に相談した、解決がなされない、そして学校に行くと、４人や５人の子どもに殴る蹴るの暴行を加えられている。しかし、１００起こり得ることを１０に抑えることはできるのではないか。答弁をお願いします。","respondent":"太田指導課長","answer":"教育委員会としても、今後この報告を受けまして、調査のあり方について、チェックの仕方についても、しっかり対応して、いじめの把握、学校だけに任せるのではなくて、我々もそういったところで前向きに取り組んでいきたいというように思っています。","voiceIndex":210,"id":"exchange-093"},{"speaker":"大西委員","kind":"質問・要望","question":"学校の校長に、学年主任というのではない、担任に言うのではない、その前の段階のところで摘むための努力を心半分砕いていただきたいというふうに思うんです。中学校３年間、女子の中学校に通っていましたけれども、いじめはあったか。なかった。だから、その前に、それが二人とも知らないと言ったら、これは事件は顕在化しない、芽を摘むということに大いなる努力をお願いして私の質問と要望を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"ほかの委員がもういろいろお話しされたので幾つか。それから二つ目は、ちょうどお話が出たんですが、小学校でちょっと気づいていないというところがちょっと危惧して、厳しいかなと思いましたが、これは調査委員会のほうが聞き取りをして、この先どうなっているかちょっとわからないんですが、小学校時代のことについて、ある程度また聞き取りをしたりするのでしょうか。そのあたりも教えてください。","respondent":"太田指導課長","answer":"１点目、教育委員会、当該校、他校の対応ですけれども、まずこの報告書が出て対策等も細かく指摘されていますので、まずこれをどういうふうな形で実施していくかというのは、教育委員会に課せられたことだと考えています。","voiceIndex":213,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"最後なんですが、非常にショックだったのは、調査のほうで、ちょっと言葉があれかもしれないですけれども、教科書的ないじめ、別な言い方では典型的ないじめ、それが大きくなって、２９ページでしょうか、校内は落ち着いていたりとか、そういうところで、いわゆる落ち着いているということで、そういったところ、典型的ないじめのパターンなのに、そういった校内が落ち着いたり。","respondent":"太田指導課長","answer":"まさに典型的な、ここには教科書的ないじめということですけれども、そういった典型的ないじめすら見落としてしまったという、そういった先ほどからお話し申し上げているようないじめに対する認識の低さみたいな部分が出ておりますので、それについてはやはり。","voiceIndex":215,"id":"exchange-096"},{"speaker":"阿部委員","kind":"確認","question":"確認させてください。１０月２９日に調査対策委員会が開かれた内容の中で、本調査対策委員会はこれで解散ということになるんですか。","respondent":"田村教育次長","answer":"ただ、先ほど来繰り返しているように、アンケートで３回、教職員のヒアリング１回ということで、かなりの短期間で集中的にヒアリング等を実施したので、当然新たな事実というのは、あんまり可能性としては出てこないのかなというふうに考えています。","voiceIndex":217,"id":"exchange-097"},{"speaker":"阿部委員","kind":"意見","question":"今、最初に検証する仕組み等もありましたけれども、検証する仕組みというのはどういうものを考えていらっしゃるのか、具体のところに実行部隊が活動していくであるとか、検証する仕組みというイメージだと思うんですけれども、そこに関してはどのような形で望まれるのか。","respondent":"田村教育次長","answer":"もう一つは、検証委員会と直接ではないですけれども、４４ページの上段のいじめ問題対策チームが専門家で、これも来年度の予算なんですが、もしこういうものが可能だとすれば、学校とはまた違う専門組織を設けて、専門家を集めて、アンケートなども月１でということで。","voiceIndex":219,"id":"exchange-098"},{"speaker":"阿部委員","kind":"質問・要望","question":"今おっしゃったのは、今後の委員会からの提言ということで、また教育委員会としても精査しながら可能な形でということになると思います。これからの検討になるとは思いますけれども、学校単位というか、教育委員会全体としてそれぞれ必要な仕事とその検証をするようやっていただきたいと思います。それについては、また今後もお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけ。資料編の１２２ページに、暴力行為の加害者６名への指導等について、こういう項目になっているんですけれども、これもとても重要なことですよね。この指導はすごく難しい感じがするんだけれども、やはり教育委員会の考え方をぜひお伺いしたいんですが、いかがでしょうか。","respondent":"太田指導課長","answer":"今、７年生ですので、８年生、９年生と義務教育の中でそういった力が培われるように、周りの大人で指導して見守っていくという体制が必要かと考えています。","voiceIndex":222,"id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問","question":"同時に、この６人の子どもたちの、まだ十二、三歳でしょうから、これからの人生は長いわけであって、だから、これからのことももちろん教育的に配慮していくことがある。だから、そのなんていうか、的確に、また厳格に、厳しく指導して導いていく、それもまた教育委員会の責務だと思うのですが、いかがですか。","respondent":"太田指導課長","answer":"やはり我々がそういった状況を把握して、学校と連携して、この子たちに対して見守っていくということはとても重要なことと考えておりますので、我々も教育委員会としても学校からの報告を待つだけではなくて、そういった形で関わっていけるような。","voiceIndex":224,"id":"exchange-101"},{"speaker":"南委員","kind":"質問・要望","question":"こういう状況をしっかり据えて、教育委員会が認識して対応していくことが必要なのではないかなというふうに思っているんですけれども、この学校の中と子どものところ、とりわけこの二つについて、このまとめとして出ているものだけに、どうかというふうに教育委員会が認識しているのか、まずそれを伺いたいと思います。","respondent":"太田指導課長","answer":"最初に、この報告書をまとめたのは、教育委員会ではなくて……。","voiceIndex":226,"id":"exchange-102"},{"speaker":"南委員","kind":"意見","question":"そんなこと知っています。教育委員会の見解はないかと聞いているんです。","respondent":"太田指導課長","answer":"いや、委員がそうやっておっしゃったので、今、そこだけは押さえておきたいと思います。","voiceIndex":228,"id":"exchange-103"},{"speaker":"南委員","kind":"質問・要望","question":"私はそういう答弁を求めたわけではないです。教育委員会として学校の中がこういうふうにばらばらになっている。報告を報告として上げていかない、学年共有の情報共有されていない、こういうばらばらな状況を教育委員会としてはどう見て、どういうふうにそれを改善しようとしているのかということを聞いているんです。","respondent":"太田指導課長","answer":"ですから、学校の中がばらばらだというのは、どういう状況なのかと、要するに、学年の組織がばらばらなのか、教員個々がばらばらなのか、そのときのそういう状況を見極めて、適切な対応を求めていくということが教育委員会としては必要かと考えています。","voiceIndex":232,"id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"したがって、そこについての教育委員会としての認識はどうなのかと、こういう状況を放置していては、私は同じことが、過ちが繰り返されると思っているので、心配するので、これについての見解を伺いたいというような質問をしているんです。","respondent":"太田指導課長","answer":"そういう状況があるので、それは非常によくない、それは改善をしていくというスタンスです。","voiceIndex":234,"id":"exchange-105"},{"speaker":"南委員","kind":"質問","question":"教育委員会の思いが。私のさっきの質問で、いろいろな体制をとりたいというように出ているし、そういうことを教育委員会として考えているかもしれないけれども、どんな対策をとっても、どんな退職校長を相談役に当てても、教育委員会自身の認識がそこになければ、うまく機能なんかしないではないですか。教育委員会自身の認識を聞いているんです。","respondent":"田村教育次長","answer":"４２ページのアで一番上に書いてあります、これ、７年生なので生徒会と書いてありますけれども、児童会も生徒会も一緒で、自分たちが見てみぬふりをする、傍観者になるということは、逆に返して自分がいじめられる可能性もあったときに、やはりどこかにそれを訴える。","voiceIndex":236,"id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"私は、今、教育次長が答弁されましたけれども、子どものそういう状況がどこから来ているのか、そういう検証もぜひ教育委員会としては深めていただきたいと思うんです。同時に、やはり品川の教育の方針、そこに照らして深めていただきたいと思うんです。したがって、ぜひ深めていただく視点に品川区の教育方針、ここに基づいて深めていただきたいということを強くお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-107"},{"speaker":"鶴委員","kind":"質問・要望","question":"すごく繰り返しで、これは要望的なところなんですが、先ほども申し上げましたけれど、この報告書、ご遺族の方が入られてということで、ここに書かれてある、特に資料編なんかは特にそうだと思うんですけれども、本人が訴えたかったこと、伝えたかったことをご遺族の方が本当に必死にさまざまなことを乗り越えられて、ここに１冊としてまとめられているのかなと思うんです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-108"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"すごく１１ページと１２ページの間に線が引いてあって、１１ページまで時系列でＡ君のことが書かれている。いじめでも何でもそうなんだけれども、まずは命の大切さを品川の子どもたちに教えてあげてほしいと思います。この報告書が今日以降どういう扱いになるのかわからないんですが、例えば僕もやはりこれを見ていてすごいものが来た、品川区にとっては、これ、教科書ではないですかね。要望だけ入れします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-109"},{"speaker":"阿部委員","kind":"質問・要望","question":"言いたいことはたくさんあるんですけれども、１個だけ要望させてください。先ほど、傍観者というのがありました。傍観者という認識であるならば、教師もそうだと、教師も傍観者になっていたと思うんです。でも、低くても、少なくともいじられキャラに見えた子というのは、何か中にあると自動的に思ってほしい。そのぐらい各校に徹底してほしいと思います。私の要望はそれだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-110"},{"speaker":"阿部委員","kind":"質問","question":"この施設ですけれども、これは４月１日ということは、既存の園と同様のタイミングで募集するのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"募集につきましては、１２月１日の広報で皆様にご案内いたします。既に保育園のお申し込みをいただいている方には、個別の通知もあわせていたします。","voiceIndex":246,"id":"exchange-111"},{"speaker":"南委員","kind":"質問・要望","question":"そういう規定になっているというふうに思うんですけれども、ここの第１項では、保育そのもの全体をしっかりやっていかなければいけないと言いながら、第２項のところでは、認定こども園、家庭的の直接契約と、あと、自治体のところの努力義務というふうになって、やはり齟齬があるのではないかなと思っているんですけれども、そのあたりの認識というのはどういうふうに思っておられるのかと、あと。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、こちら、正確に条文を読みますと、第１項で、まず保育を必要とする場合において、次項に定めるところによるほか、当該児童を保育所において保育しなければならないと書いてありますので。","voiceIndex":252,"id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"そうすると、地方自治体が、どんな場合でも、どんな子どもでも保育は責任を持ちますよ、きちんと受け入れて保育をします、保証しますよというふうに理解していいんですか。","respondent":"伊崎待機児童対策担当課長","answer":"こちらの法律の趣旨は、すべての子どもが主催して、先ほど申し上げましたように、子どもの教育、保育、子育て支援を総合的に決める新しい法律をつくっていくということになっておりますが、細かい政令とか、国の指針については。","voiceIndex":254,"id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"その点について、保育の実施義務を自治体の義務の関係では、やはり保育園をしっかりつくっていただくという、そういうことが大事なんだというふうに思うんですけれども、この辺の父母の要求というのはどういうふうに信頼を持って品川区に申請をし、認定をしてもらったらいいのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"必要性の認定の基準はこれから出てまいりますので、今何ともお話しできないんですけれども、その一人一人の認定に合わせて、基本的にはニーズに合った施設を選んでいただくということなんですが、お申し込みが定員以上になった場合は、市町村は変更を行うというのは。","voiceIndex":256,"id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"それも含めて。それともう一つは、財源が消費税だというふうに言われていますね。消費税、これ、もっと保育園をつくってほしいというふうになれば、消費税がどんどん上がっていく、こういう仕組みになるわけですから、こういうところに財源を求めるということも間違っていると思います。そのことだけ言って終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-115"},{"speaker":"阿部委員","kind":"質問","question":"この資料自体は、いろいろなところでこれまで見ているものですけれども、国としての方針ということなんですが、お伺いしたいのは、都のほうで今後どのように認証保育所などをどのように扱って、何か現段階で情報があれば教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"これを今のタイミングでご説明しましたのは、１０月に市町村に対する説明会が内閣府主催で行われまして、その結果を受けてのご説明です。東京都からは、認証保育園につきましては、まだ一切判断も情報も下りてきてございません。要望をしているということだけは聞いております。","voiceIndex":259,"id":"exchange-116"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今日はこんな時間ですから。ぜひそういう角度で子どもの生活する環境を整えるというところは、本当に重要視していただきたい、そういうふうに思います。それが大きくなったら、それはそれで一つの問題が出てくるという、そういうことは絶対に起こしてはならないわけですから、きちんと環境は守っていただきたいということを改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":264,"id":"exchange-117"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4774#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":110621,"voices":272}},{"id":"h24-20121105-5","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"総務委員会","time":"午後０時５９分～午後２時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)の「（株）南東京ケーブルテレビへの東急電鉄（株）の運営参画」","agenda":"はじめに(1)の「（株）南東京ケーブルテレビへの東急電鉄（株）の運営参画」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"南東京ケーブルテレビ自体の会社の概要というか、株もパーセンテージはここに出ているんですが、どのくらい、資産とかその辺も大雑把に教えていただきたいのと、具体的に参画をするということは、この株式の所有状況がどういうふうに変わっていくのか、その辺を教えてください。","respondent":"柏原行財政改革担当課長","answer":"こちらのほうですが、会社設立は、先ほどお話し申しましたように昭和６０年３月に会社を設立しています。所在地としましては、品川区戸越一丁目にあります。資本の額ですが、現在２５億円です。株式の状況ですけれども、発行済み株式の総数といたしましては５万株です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"会社概要のところで２５億円ということなんですが、社員、従業員の数がどのくらいなのかというのを１点、あわせてお伺いしたいのと、５万株ということで、株式のところはこれから協議だということなんですが、品川区に相談があったというか声がかかったというところでは、この品川区の持ち株の中からという理解でいいんでしょうか。","respondent":"柏原行財政改革担当課長","answer":"南東京ケーブルテレビの従業員の数です。社員としましては４１名の社員が勤めてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"これからというところで、あまりよく見えないんですが、東急電鉄との関係というか、東急電鉄の影響が、沿線が多いという意味では品川区に対しての影響が強まるという捉え方でいいんでしょうか。","respondent":"日下部企画部長","answer":"東急電鉄の影響が強まるのかというご質問ですけれども、先ほど来申し上げておりますように、１つは、今、東急沿線で提供されている情報を品川区でも放映する。ということで申しますと、もう少し具体的に申し上げます。","voiceIndex":9,"id":"exchange-003"},{"speaker":"阿久津委員","kind":"質問・要望","question":"２点、お伺いしたいと思います。きれいに３等分されていますので、そこら辺をちょっとお聞きしたいと思いまして、お尋ねしました。","respondent":"柏原行財政改革担当課長","answer":"こういった形での運営参画というのは、私もあるかどうかというのはちょっと承知はしていないので、例えば株を取得したりとかいう場合もあるでしょうし、連携、協力してという、こことここがそうしているというのは、ちょっと具体的な事例としては、申しわけないんですが、今。","voiceIndex":11,"id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問","question":"そういうほかの自治体の情報が得られるというのは、非常にメリットだと私は考えております。今、どこまで東急電鉄がそういう情報を出しているのかも、運営参画といって通常どこまで出しているのかというのはわからないんですが、もしまた後ほどわかれば、教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"南東京ケーブルテレビの資本の移動の関係で、設立時と、たしか増資していますよね。その辺の状況と、品川区の当初の持ち分と、今のはわかりますけれども、増資の状況をまず教えてください。","respondent":"柏原行財政改革担当課長","answer":"さらに平成１７年５月ですけれども、こちらの持ち株、その３,５００株からさらに１万３,５００株と増資をいたしまして、そのときに持ち株の比率としては２７％になったといった状況です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは当然上場していないから、評価は１株５万円になると思いますけれども、今後の展開の中で、こういう株式を品川区が一部売却するようなことになったときには、この評価というのはやはりその元の金額で評価することになるんですか。","respondent":"柏原行財政改革担当課長","answer":"当初の５万円というのは多分基本にはなってくるかと思うんですけれども、こちらを売却する際に、改めて評価が入ってくるところでございまして、そのままの金額ということではなかろうかと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"評価につきましてはわかりましたので、マイナスにならなければいいのだけれども、決してマイナスになることはないでしょうけれども、その辺の評価を確認したかったんです。要望としては、最初の繰り返しになりますけれども、今の運営をそのまま、ぜひ品川の区民にとってメリットが残るような形でしていただきたいということを、検討の中でつけ加えておいてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"お金のほうも南東京ケーブルテレビが少し潤沢になるということで、経営は安定していくと思うんですが、品川区の持ち株の割合が減ってくるということになると、やはり何を言っても、今、品川区は２７％、日本電気が３３％ということでいるんですが、だんだん割合が変わってきてしまうと、やはり何だかんだ言っても株式会社でしょうから、品川区の影響というのはやはり下がってくる。","respondent":"日下部企画部長","answer":"これはもうどのような形になろうと、やはり一番大事なところだと認識しております。","voiceIndex":19,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと聞き忘れたのがあって。２番の株式の所有のところなんですが、筆頭株主の日本電気の、ここのところの南東京ケーブルテレビとの関係というか、役割というか、制作担当をしているんですか。ちょっとそこの中身を教えてください。","respondent":"日下部企画部長","answer":"そうですね。日本電気は、先ほど柏原行財政改革担当課長のほうから鈴木（真）委員のご質問にお答えさせていただきました。","voiceIndex":22,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうすると、今後のことがいろいろとあると思うので、ぜひ注視していきますので、変化があったときなど、ご報告をいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"の「『品川区史』編さんについて」","agenda":"の「『品川区史』編さんについて」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"１点だけ、この品川区史編さん委員会と、品川区史編さん検討委員会の２つの委員会があって、メンバーが異なるんですが、裏面の平成２５年度は、レイアウト作成して最終的な確認を１年でやるのかなと。","respondent":"武内総務課長","answer":"そのご意見で、目次だとか概要をある程度形式的にもう決定しましたら、品川区史編さん検討委員会というのは内部の会議ですので、それぞれ総務担当課長、あるいは広報課長だとか、文化スポーツ課長、商業観光課長、ものづくり・経営支援課長だとか。","voiceIndex":30,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"平成２３年度から４年をかけて、かなり時間をかけ、４０８ページというかなりすごくボリュームもある内容なんですけれども、予算の総額は幾らぐらいかかるのか。平成２４年度の予算書は見たんですけれども、最終的にどのくらいを予定しているのかというのが１点、教えてください。","respondent":"武内総務課長","answer":"それと同時に、こういう委員会を開催しますので、若干報償費等がかかりますので、そのような金額で予定しております。","voiceIndex":32,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"発行部数が１,５００部ということと、ＤＶＤも添付だから一緒ですね。実際にこれがどう活用されるのか、手に入れたい場合、価格がどうなるのかあたり、どういうところに行けば見られるのかも教えてください。","respondent":"武内総務課長","answer":"こういう資料につきましては、当然歴史館等、また図書館等、学校、そういう必要なところに無償配布するということを前提に、それが１,５００部という数の中で一般の区民に頒布ということも当然行うんですけれども、その金額につきましては。","voiceIndex":34,"id":"exchange-014"}]},{"id":"topic-03","title":"の「大井競馬場における中央競馬の発売計画について」","agenda":"の「大井競馬場における中央競馬の発売計画について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ご説明いただいたんですが、これはいつから行われるのでしょうか。来場者もかなり増えるし、車両も増えるということで、近隣に与える影響があるかと思うんですが、この説明会というのはいつごろ行われるのかも教えてください。","respondent":"武内総務課長","answer":"ちなみに、特別区競馬組合の議会というのがあるんですけれども、それは１２月中旬が開催予定になっていますので、そこで正式にこの案件が出てくるというふうには聞いております。","voiceIndex":41,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"このことが周知される、これは品川区から来て委員会に出ていますけれども、特別区競馬組合から当然マスコミに出したり、地域にも出てくるでしょう。ことにあの近辺の方にすると、人数が増えるということで気にする方もいらっしゃるでしょうから、流れをきちんとしておかないとおかしくなると思うので、その辺だけ、お願いしたいと思いますが。","respondent":"武内総務課長","answer":"１１月に入りましたら、早急に町会連合会あるいは自治会を通じて、地域周辺の方に周知していきたいという話を聞いております。","voiceIndex":43,"id":"exchange-016"}]},{"id":"topic-04","title":"の「平成２４年特別区人事委員会勧告の概要について」","agenda":"の「平成２４年特別区人事委員会勧告の概要について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"数字の見方と言おうか、１ページ目の１の職員と民間従業員との給与の比較のところの最初の表で、この実態調査の内容、この職員数というのは５万９,４５１人、あと民間のという、この数字というのは何を示して、どう読んだらいいのか、比較した職員数のここの数字をどう見たらいいのか、教えてください。これはどういうことなのかなとちょっとわからないので。","respondent":"堀越人事課長","answer":"そちらの１ページの表ですけれども、職員数につきましては、さまざまな職種がありますけれども、その職種、再任用職員等を除きました形でのすべての合計が５万９,４５１人という形で調査をしたです。","voiceIndex":50,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、いつもそういう比較の仕方をしている、事務と技術系ということで、特別区のところは全員ということで、違いはどういうところにあるのか教えてください。","respondent":"堀越人事課長","answer":"全体の５万９,４５１人、各給料表、行政職給料表（一）、それから技能系、医療系・給料表すべてをならした形での平均給与の月額となりますと、４０万３８４円というのが平均給与月額という形で出ているという結果を、特別区人事委員会では持っております。","voiceIndex":54,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、伺ったのは、民間のほうに入っていなくて、特別区の職員に入っている職種、その辺の違いをひとつ教えてほしかったのが１点です。こういったところで、この民間従業員の公民較差のところにある民間の従業員というのは、これは特別区内の上の表の部分としてとらえていいんでしょうか。","respondent":"堀越人事課長","answer":"調査対象規模といたしましては、さまざまな規模といたしまして、統計調査の手法として規模による層化の無作為抽出によって実施調査を行っておりまして、実際８０１の事業所が調査を完了しておりますが、５０人以上１００人未満の事業所でいうと１１３事業所。","voiceIndex":56,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"年間１万３,０００円の減ということで、この間、新聞を読んだら１４年間に公務員８９万２,０００円の給与が減っているという状況も読んだわけですけれども、本当に厳しい状況にあると思ったところにおいては、やはり民間との給与較差というのは本当に厳密な比較がしてある人事委員会制度の勧告の中身にはなるんですが、やはり比較するところもきちんとした比較をしてほしいと思うところがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３ページの「人事制度、勤務環境の整備等に関する報告（意見）」という欄があるんですけれども、これは当然向こうの人事委員会での検討事項だと思うんです。ことに組織の管理職選考とかいう問題が出てくると思うんです。その辺を中心に教えてもらえればありがたいです。","respondent":"堀越人事課長","answer":"採用に当たってのさまざまな受験資格の部分ですとか、幅広く人材を採りたいという観点から、前回の人事委員会のほうにも意見を申す形で、受験年齢の拡大ですとか、そういった部分を検討できないかというようなお話は、事務レベルでさせていただいているところです。","voiceIndex":59,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えば最後の４ページの、今、お話しいただいた、組織の足腰強化に向けた制度の構築、よくほかの区の中でも、今は係長に対する試験を受ける方が減っている、あまり受けたがらないという傾向があるということもお聞きしているので、その辺も品川区の職員の方、これから一生懸命にやっていただくためにも、その辺の提示としても、制度的にも頑張っていただきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"阿久津委員","kind":"質問・要望","question":"区民のご意見があったので、一応お伝えさせていただきたい、確認をさせていただきたいんですけれども、ちょっと前に埼玉県とさいたま市で、給与そのものではないんですけれども、残業手当が非常についていたということで、本来の給与の２倍ぐらいの、７００万円だったら１,４００万円ぐらいの年収になっていたということで、その金額はともかくとして、労務管理のあり方が問題になっているんですけれども。","respondent":"堀越人事課長","answer":"やはり、心身の健康を保ちつつ、持っている能力をしっかり使ってパフォーマンスを上げて仕事をしてもらうという必要がありますので、その部分については、区としても引き続き進めていきたいと考えております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"阿久津委員","kind":"質問・要望","question":"もし、今、資料があれば教えていただきたいんです。","respondent":"堀越人事課長","answer":"多少の超過勤務というのはやむを得ない部分もありますけれども、要はしっかりと仕事をするための必要な部分ですので、そういう形でできるようにしていきたいと考えています。","voiceIndex":64,"id":"exchange-024"},{"speaker":"阿久津委員","kind":"質問","question":"１名いるようなご答弁いただきましたけれども、ただ、いろいろな理由があって多分そういうことだと思いますので、一概にこれは何とも悪いとは一言では言えないところもあると思いますので、人事のほうのお仕事もしっかりとお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"実際、今回２３区の職員の平均給与が６６０万円という金額になると相当の差がある。国のほうではもう所得税という数字が出ていて、実態調査がより明確に出ている。さらに、この６６０万円ということは、我々の調べている状況においても大企業並み、大手企業並みの数字だと思うんですが、その辺について、これだけ離れている、この数字ということに関してどのようにお考えなのか、お聞かせください。","respondent":"堀越人事課長","answer":"競争試験による能力実証を経て採用されて、私ども品川区の職員として公務に従事するという、それは民間企業も同様ですので、そういった形で正確な比較がされているものと認識しています。","voiceIndex":67,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"ならば、ここの資料というのは公表されているのか、どこか見れば一般の区民の方が見ることができるのか、その辺はどうなんでしょうか。それだけちょっとお聞かせください。我々も説明するに当たって、なかなかこうだああだと言っても片一方は数字が出ているわけで、なかなかちょっと説明しにくいところがあるので、その辺どうなんでしょうか。","respondent":"堀越人事課長","answer":"調査のところですが、平均という形でありますけれども、先ほど調査の方法といたしまして、年齢ですとか学歴ですとか、それから役職等、きちんと個人単位で対応させる形での比較をとっておりますので、繰り返しで恐縮ですが。","voiceIndex":69,"id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"確認だけですけれども、今のことで、議長のほうに報告されているという話ですが、それは例えば企業名なんかは列挙されているんですか。それだけ。","respondent":"堀越人事課長","answer":"全体の民間企業、いろいろな職種等があります。事務・技術系職種、学歴等で全体を比較して、概要として統計的な処理を加えて、報告させていただいているです。","voiceIndex":71,"id":"exchange-028"}]},{"id":"topic-05","title":"の「（仮称）鮫洲入江埋立公園整備工事請負契約」","agenda":"の「（仮称）鮫洲入江埋立公園整備工事請負契約」","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"確認です。これは品川区の財源でしたか。自分ではっきり、もう何年前だかで記憶が定かじゃないですけれども、ここの公園整備のときに、東京都が大分入って説明会か何かをやっていたんじゃないかという記憶があるんですけれども、これはほとんど品川区の計画となって、東京都は絡んでいないんでしたか。","respondent":"本城企画財政課長","answer":"この工事につきましては、もっぱら品川区の一般財源で賄った工事です。下のポンプ場のほうは東京都の関係の工事ですが、今回の公園整備につきましては品川区の財源ということで、ご理解いただければと思います。","voiceIndex":78,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その下はといって、そのときに、たしかあのころここに区民集会場をつくってくれとかいう話が大分あったような気がするんです。それからあと河川の部分の境界、そんな問題も絡んで、公園をつくるときに東京都がもっと入っていたので、実は東京都が次にやる公園だと自分が勘違いしていたので、全部これは品川区がやって、今後も品川区が管理していくということでいいわけですか。そこの確認だけ。","respondent":"本城企画財政課長","answer":"お話のとおり、この公園についてはもっぱら区立公園という位置づけで、整備について区の財源で賄って、ここも区の公園として管理していくという立場です。","voiceIndex":80,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この契約の相手方の東光園緑化株式会社品川営業所ということなんですけれども、本社はどこなのか。資本金とか、品川区での営業の実績もあったら教えていただきたいのと、あと今回の落札価格が予定価格よりもかなり開きがあるというか、３,０００万円も安くなっているというあたりでは、予定価格とこの開きをどう考えたらいいのか、教えてください。","respondent":"平澤経理課長","answer":"契約金額につきましては、８２％ということで落札したということなんですけれども、開きというか、こちらの範囲ではないかなと感じているところです。","voiceIndex":82,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"本社が渋谷区ということで比較的近いということ、あと品川区で既に何カ所もやっていて実績があるという受けとめ方でよろしいんでしょうか。","respondent":"平澤経理課長","answer":"今までの実績ということで、これは先ほども申し上げまして、繰り返しで恐縮ですが、品川区におきまして平成２３年度５回の工事をしているということで、信頼のおける業者と考えています。","voiceIndex":84,"id":"exchange-032"}]},{"id":"topic-06","title":"の「第３回定例会第７１号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約に関する議案の撤回について」","agenda":"の「第３回定例会第７１号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約に関する議案の撤回について」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"１点だけ確認したいんですが、事業者の処分、これは品川区の基準で３カ月の指名停止ということですが、これは大旺新洋株式会社の本社も、現在何らかの措置はとられているわけですよね。罰則があると思うんですけれども、その法というのは、本社と支店との関係においてどのような考え方があるのかというのが一点どうしても引っかかるんですが、その点をちょっと教えていただければと思います。","respondent":"平澤経理課長","answer":"支店に対して指名停止処分ということになります。ただ、ちょっと考えにくいんですけれども、本社が仮に単独で入札したとしても、それはお受けできませんということになります。","voiceIndex":91,"id":"exchange-033"},{"speaker":"阿久津委員","kind":"質問","question":"前にももしかしたらご説明があったかもしれないんですけれども、これを第４回定例会で上程されて、仮の話で申しわけないんですが、これがまた新たな入札ということになった場合、どれくらい工期がおくれるのかということ、とりあえず先にそれをお聞きします。","respondent":"平澤経理課長","answer":"入札のスケジュールで申しますと、議会の日程ですが、議決が１２月上旬になるということになってありますので、２カ月のおくれということになります。完成予定もその旨、おくれるということになるわけです。","voiceIndex":93,"id":"exchange-034"},{"speaker":"阿久津委員","kind":"質問","question":"地域の方、その近隣の方から話があって、現段階で、今、撤去作業をしているということで、これから本格的な基礎の撤去とかプールの解体に入るというように聞いているんですけれども、それに対しては影響が今後出てくるのかどうか。解体作業、撤去作業についてのスケジュールというのは、現段階ではスケジュールどおり進んでいるのかどうかをお聞きしたいです。","respondent":"小林施設整備課長","answer":"現在、解体工事のスケジュールについては、予定どおり行っております。それと、今、この工事の関係で影響があるかというのは、それについては解体とは影響はございません。","voiceIndex":95,"id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問・要望","question":"確認したかったのは、じゃあ解体が終わって、その後２カ月のおくれということは、２カ月間、工事がその間あくと、近隣の方がそれだけ確認をしてほしいということがあったものですから、それを確認させていただきたいと思います。そもそもそれをちょっとお聞きしたい。","respondent":"平澤経理課長","answer":"工事につきましては予定どおり行われているですので、それほど期間があくということは予定していないです。","voiceIndex":97,"id":"exchange-036"},{"speaker":"阿久津委員","kind":"意見","question":"うまく調整をしていただいて、間があくのがいいのか、そのままスムーズにいくのがいいのか、そこは工期が短いほうが、近隣の方への粉じんとか振動とか、そういった点で影響があると思いますので、そういうところは近隣の方のご意見を聞いていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。第４回定例会で議決があるわけですけれども、具体的にこのでき上がりのおくれというのはどのくらいと考えたらよろしいですか。","respondent":"平澤経理課長","answer":"公園課のほうで、この日程で行った場合ということで試算をしていますが、８月の終わりまでには何とかということで、今、調整しています。","voiceIndex":100,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"ということでは若干のおくれがあるというところで、事業者の処分のところに指名停止３カ月とありますけれども、その辺の今回の影響が、地域の方にどの程度あるかというのはあまりわからないんですけれども、この辺の影響に対する被害に対しては、この３カ月の指名停止処分だけで終わるということなんでしょうか。","respondent":"平澤経理課長","answer":"対等の被害ということになりますと、なかなか難しいということになるわけですが、ただ、大旺新洋株式会社につきましては、本委員会でもご報告させていただきまして、社会的な制裁を十分に受けるですので、そういったところで、今後当然あってはならないですので。","voiceIndex":102,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":30983,"voices":109}},{"id":"h24-20121106-14","meetingId":"h24-cm11","date":"2012年11月6日","dateIso":"2012-11-06","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"旧第一日野小学校校舎等の解体","agenda":"旧第一日野小学校校舎等の解体","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"校舎解体工事の説明会に先立って、学校と校舎へのお別れ会を込められた見学会が開催されたと思いますが、そこの参加人数や、参加者からどのような要望が上がり、区がどういうふうに対応するのか、そこをご説明いただきたいと思います。この解体工事の作業時間について、工事車両は何時から現場を往来するのか伺いたいと思います。つまり、解体工事の契約の発注は誰なのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"工事のおくれというお話が若干ございましたけれども、現段階では、説明会は若干、当初、最初に考えていたよりは１週間程度おくれているというのがありますけれども、これは周知を丁寧にやっていただきたいということでこちらも申し入れをした部分がありますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"お別れ会を通じたさまざまな要望や、また解体工事にかかわる登下校の問題、騒音の問題、近隣の方へのさまざまな要望には丁寧に対応していただきたいと思います。このおおむね８年間とはどこの文書に明記されているのか、改めて伺いたいと思います。学校跡地利用も当初は立体駐車場。それが２年間のコインパーキング。なので、おおむね８年間とはどこに明記されているのか、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういったところで、協定書とか、契約書の担保もありますので、その辺については問題ない感じと考えています。それから、今後の説明会関係ですけれども、説明会という形では、区の指導要綱等々に基づきまして、今度、仮設店舗を建てるときに説明会は行う予定です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業用定期借地権設定合意書の第１５条「土地の返還」、第１６条「損害賠償等」をＴＯＣに求めるのか、ここを伺いたいと思います。それと、学校跡地の仮店舗ですけれども、現在ＴＯＣで営業されている方全てに仮店舗への入居希望等の有無を確認するのかどうか伺いたいと思います。そもそも学校跡地の仮店舗の規模を見るならば、全員分のスペースはとてもありません。伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"まして、先ほどもご説明しましたように、ＴＯＣにとっても延びることについてはメリットがございませんので、また、その後の工事についても、都市計画の手法等でお時間を若干取る部分もありますが、そういったところを含めて全体の工事の８年間という計画を組んですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど聞いたのが、要するにおおむね８年だと言いながら、ここに書いていないのがなぜ担保になるんだと。つまり、おおむね８年を越えたらこれをＴＯＣに請求するのかと、そこについて答弁がなかったので、しっかりとお答えいただきたいと思います。最後に、現時点でＴＯＣビルはどんなビルに建て替わるのか、いつ始まるのか、何も決まっていないじゃないですか。現時点で何か変更があるならご説明ください。","respondent":"柏原行財政改革担当課長","answer":"新しい建物については現時点で変更云々ということよりは、ＴＯＣ側で検討していますので、現段階で何か言えるという部分ではないといったところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。結局、違反があれば求めるんだと。ということは、結局１０年間でもよいと今、言っているわけですよね。それがなぜおおむね８年なんだと、全く説明が食い違っていると思います。私は何もＴＯＣに公有地貸し付けではなくて、住民要望の強い特養ホームや防災広場など、住民要望に沿った活用こそ強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"確認だけします。参加者数が３２名ということなんですが、この内訳はわかりますか。地域の方との関係、ざっとでいいんですけれども。それは今後どういうふうにされるのかということ、この点をお聞きします。","respondent":"柏原行財政改革担当課長","answer":"質問に対する回答等につきましては、先ほど省略させていただいたんですけれども、説明会の中で例えば、先ほどもちょっと議論がありましたけれども作業時間の関係であるとか、登下校の時間については例えば大きな車の出入りはなるべく避けたいだとか。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"意見、要望については対応をちゃんとされているよという理解でよろしいでしょうか。質問を受けただけだと納得いかないと思うので、回答をちゃんと出していただいて、丁寧にやっていただきたいなと思いますので、今後ともよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"確認","question":"伺いたいことがあります。わからないことと、１点は確認したいことがあります。絶対振動は出るんだから。特に基礎とか、土とか、そこら辺は法定基準内だとしても振動は来るんだから、そこら辺のところをどのように話をしているのか、どういうふうにこれは対応したのかだけを教えてほしい。","respondent":"柏原行財政改革担当課長","answer":"つながるような形ですので、騒音、振動についても法定基準内ということで、何デシベルというお話もその場で出ていたんですけれども、騒音が８５デシベルであるとか、振動が７５デシベルというような説明がされたのですが、それが具体的に言うとどういうものなんだということで。","voiceIndex":18,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"支柱梁とか、そういうものを壊すときに多分、振動が出るんであって、これ、どういう杭が入っているか知らないけれども、そこら辺のところというのはやはり絶対私は音より振動だと思う。だから、そこらはやはりよく事業者にも言っていただいて、そこら辺の対応は、何かあったら区も指導ぐらいはしっかりするべきだと思いますので、それはお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"この場じゃなくても、事前にそういった辺があったのかな。これを教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"時間につきましはして、先ほども委員から出ましたが午前８時から午後６時ということで、作業時間がその時間帯ということですので、当然それよりも事前には作業員が入ってくるです。","voiceIndex":21,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"この近辺のどこでやっているか、ちょっとごめんなさい、私、そらで記憶してなかったんですけれども、当然朝礼とかを含めれば７時半ちょっと前ぐらいからだんだん作業員の方々、徒歩も含めて、交通手段は何かわかりませんけれども、車とかも含めていろいろうわっと、大きい作業になればそれなりの人数の人、車両も含めて来るんだろうなと思うので、配慮をということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"}]},{"id":"topic-02","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"説明ありがとうございました。少し、幾つかお伺いしたいんですけれども、まず、私の近所である方が物納をしたという、土地を物納したということで、今現在どうも財務省の管理になって、大した広さではないんですけれども、品川にちょっとした土地があったりするんですけれども、そういうのはこの表でいうと２ページ目の普通財産の住宅敷地に入るんですか。その辺のことはわかりますか。","respondent":"柏原行財政改革担当課長","answer":"細かい内容までは把握はできていないんですけれども、物納という形で入ってということで、おそらくですけれども、国のほうが判断してどういう使い方もできないと判断するのであれば、未利用国有地ということで最終的にはなってくるんだと思うんですね。","voiceIndex":29,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、最終的にはというお話。今現在は空き家みたいになってしまっているんですね、そこは。そうすると、それはやはり除去して更地にしてからみたいなことが手続上、手続上というか、財産管理上、前提条件となってくるんでしょうか。","respondent":"柏原行財政改革担当課長","answer":"申しわけございません、細かい手続きまでは承知していないので、申しわけございません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。一層の調査というような形でお願いできればなと思います。もう一つですけれども、Ａ３の資料で、一番右の「西大井６丁目第３区営住宅」というのは建替時都営住宅区移管事業というのを使って、これは家賃対策補助とか、建設補助が出るということで、これを使ってやられた。一方で「大井林町高齢者住宅」のほうはそういう形になっていないのはどうしてかということをお伺いしたいんですけれども。","respondent":"柏原行財政改革担当課長","answer":"そういったことで耐震もＮＧでしたし、建て替え等々をしなくてはいけない物件であったということで、ただ、その場で、その当時の戸数が７２戸だったんですけれども、建築の関係上７２戸の戸数をつくるのは難しいということもあったようです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"塚本委員","kind":"確認","question":"確認なんですけれども、この制度を使うには、同じ規模で建て替えないといけないという前提があるということですか。","respondent":"柏原行財政改革担当課長","answer":"それで建てなくてはいけないということではないんですが、結果的に「公営住宅法」の縛りがありますので、公営住宅として使うときにはどうしてもそこに引っかかってしまう。公営住宅として建てるときにはその規模をというラインがありますので、そこに引っかかってくる。","voiceIndex":35,"id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"ここは何で明確になっているのか。バンプールはここだけではなかったと思うんですけれども、あと、ヤード、バースというんですか、そこにもいろいろなものが建築されたり、事務所が建っていたりするんですが、これだと埋立地だけでイメージが沸いてこないんですけれども、それは品川区としては把握されていないということでよろしいですか。","respondent":"柏原行財政改革担当課長","answer":"未利用国有地についてです。こちらにつきましては、先ほども申しましたように国が調査というんですか、監査の中で境界を確定していないとか、すぐの処分は難しいという判断をしていると聞いてあります。","voiceIndex":37,"id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"埋立地に関しては、バンプールも含めておそらく大井埠頭とか、品川埠頭とか、これはＪＲ貨物のほうは入っているかどうか僕はわからないですけれども、だと思うんですけれども、品川区で結構ここの臨海部というのは面積のうちの６分の１なのか、８分の１なのか、結構占めているので、品川区としてもどこに何があるかという、いくら港湾局の管轄だといっても。","respondent":"柏原行財政改革担当課長","answer":"国のほうが処分困難財産ということで位置づけをしていまして、先ほど１つ例として詳細が未確定というようなお話もしたんですが、一部境界が未確定、それから建築の制限がかかるであるとか、例えば、ここではないかと思うんですが、区画整理中で直ちに処分が困難、いろいろ。","voiceIndex":39,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"国と東京都が保有する財産の一覧ですけれども、国と東京都が保有する財産を売り払うときに、必ず品川区に連絡が来るという、その辺の仕組みを伺いたいと思ったんです。単純に「公有地の拡大の推進に関する法律」と言われるものだけなのか、そこをご説明いただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"東京都についても地元の区に、決まりかどうかというのはあれですけれども、地元の区にお話しいただいているケースが多いです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当は国も、東京都も、土地の大小にかかわらず必ず１度は地元に意向を伺うという仕組みになっているということなのか、そこだけもう一度確認させていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"あと、事業終了しているものですけれども、事業が終了したかどうかというのは判断がなかなか難しいところがございまして、先ほども、冒頭ご紹介しました国有財産の一番最初の参議院の五反田分室というところがあるんですけれども。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この仕組みがいまいちよくわからなかったので、今後でも構いませんけれども、どういうルールづくりがあるのか、そこはまた説明していただきたいなと、これは要望しておきます。西大井６丁目の第３区営住宅、この件ですけれども、今後、都営住宅の区移管というのは計画があるのかということと、そういう対象となるものがそもそもあるのかということと、その辺の考えを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらにつきましては、西大井６丁目で事例として１回やってありますけれども、今後につきましては、先ほど言いましたように都営住宅が１００戸よりも小さい住宅ですね、これについては移管の対象とはうたっているんですけれども、土地は確かにいただけるんですが。","voiceIndex":45,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"幾つか教えてください。もう諦めちゃって、しようがないやと思っているのか。そうすると、ここら辺は区として思いを訴えるぐらいのことがあっていいんじゃないのかなと思うんだけれども、そこら辺の考え方を教えてほしいのと、これだけ埋立地があると、今、部長が地図を持っていたけれども、意図的に、こちらが意識をして、ここにこれだけの敷地があると。国外へ避難してきた人、船か何かで、引き揚げの。","respondent":"日下部企画部長","answer":"ただ、先ほどもちょっとご質問がありましたけれども、品川区のエリアにある土地、しかも国とか東京都が所有している土地ですから、その現状がどうなっているのか、そしてそれを区として何か活用できる可能性があるのかどうかということぐらいは。","voiceIndex":47,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、今の話だと、逆にあそこをどういうふうにと言ったら、向こうは何かやりますと言えばそれまでで終わりなんだけれども、そうじゃなくてうちはこういう形で使いたいので、何とか売却してくれみたいな話をこちらから持っていくということだって可能だと思うので、そういう情報があるじゃないですか、ベニヤ板で塞がれちゃってだなんて、多分、区にも上がると思うので。じゃ、どうなるのと。","respondent":"日下部企画部長","answer":"これは当然、国なり何なりのそれに対して協力的な姿勢を示すべきだと思うんですが、これが丸々いただきますというような、国のほうが財政危機の問題もありまして、大分方針も変わってきておりますので、そういうことも含めて、非常に私どもとしても苦慮しておりますが。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鶴委員","kind":"確認","question":"そうすると、本来、行政で使っていた、東京都としては今までは行政財産だけれども普通財産にして品川区に払い下げたら、東京都としてはそれは普通財産という台帳上の扱いで、品川区にしてみれば行政財産で上物、土地は借りているよとか、上物はこうだよというやり方にするのか、ごめんなさい、その辺の整理の仕方というんですかね、どういう扱いになるのか教えてもらいたいんですけれども。","respondent":"平澤経理課長","answer":"委員のご指摘の普通財産、行政財産の扱いの問題ですが、こちらは私のほうではわからない部分ではありますが、委員ご指摘のとおり、2)の例えば１０ページの財務局が持っている「品川警察署品川橋交通待機所」の場所ですが、通常こちらは行政財産という扱いになるわけなんですが。","voiceIndex":51,"id":"exchange-023"},{"speaker":"鶴委員","kind":"質問・要望","question":"そのすみ分け、わかりました。品川警察署だと例えば７ページに行政財産でずっと出ていますよね。なので、その辺のすみ分けがどうなのかなと、今後の参考のために教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"ここ、どうもごみがたくさんあるよとかいうのが仮に区民の皆さんから来たときに、じゃ、それをどういうふうな扱いで区がやっていくのか、国有財産になってくると国がやってくれるのか、という管理の問題が一つと、それから、２ページの「無償貸付財産」があるんですけれども、これというのは無償で、期限はあるんですか。急に必要になったから返せとか言ってきちゃう場合もあると思うんですよね。","respondent":"平澤経理課長","answer":"国につきましてはほかも全て５年間の更新でやっております。","voiceIndex":54,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"そうなると、それは結局、管理がちゃんとできないんだから品川区にくれみたいなね、そういうことも言えるかなと思うんですけれども、そういうちゃんと管理ができるんだったらちゃんと管理をしてもらいたいし、できないんだったら区有財産として移管しろということも強く言える部分なのかなと思ったので、その現状をどうなのかなということと、それから、無償貸付財産のところですけれども。","respondent":"平澤経理課長","answer":"確かに委員ご指摘のとおり、区ですと常日ごろから例えば土木の職員等が回っているというのがありますので、直ちに対応できるですが、そういった事例があったような場合には直ちに国・東京都に私どもから連絡させていただきまして。","voiceIndex":56,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"管理の件はそういう形でお願いしたい部分もありますし、それを含めて考えていきたいなと思っています。あそこも国有財産だったのかな、ちょっと私もよくわからないんですが、そこも道路の整備があるので返してほしいということで返して、野球場を整備したという経緯があると思うんです。あったりしますので、そこら辺はいかがですか。そういうケースはないとは思っていないんですけれども。","respondent":"平澤経理課長","answer":"マイガーデン東五反田は東五反田２丁目１８番のところではないかと思うんですけれども、これは三井不動産販売株式会社が貸主、所有者でございまして、再開発に伴う合意解除ということで、私どもが合意して解除したという土地です。","voiceIndex":58,"id":"exchange-027"},{"speaker":"西本委員","kind":"意見","question":"私の記憶違いだったのかもしれないんですが、ただ、貸し付けをして、借りていろいろ事業展開をしているというのがあるならば、やはり将来的にそこをどうしていくのかというのが、先々を見たときに区有財産に持ってこれるというような考え方も必要かなと思いますので、それも含め今後、私も考えてみたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"一体何なんだろうという話になるんですよね。そういったところどう把握されているのかというのと、もし今わかれば、西大井６丁目の都営住宅の伊藤町アパート、あそこはもう区に来たんですかね。ちょっとご説明いただけますか。","respondent":"日下部企画部長","answer":"西大井６丁目の伊藤町アパートは確かに時間がかかったんですね。ただ、今年度予算にも計上しておりまして、区として用地を取得いたしました。防災広場として整備をするということで、たしか今もう既に準備を進めております。","voiceIndex":61,"id":"exchange-029"},{"speaker":"山内副委員長","kind":"質問","question":"先ほど、払い下げの件で減額の話がありましたけれども、これは国有財産の公有地等払い下げの場合は減額制度が、いわゆるインセンティブがない。これが東京都の財産を今度、自治体に払い下げをしますといったときの減額制度があるのかということと、何か、インセンティブがどんな形であるのかということを伺いたいんですけれども。","respondent":"日下部企画部長","answer":"例えば先ほどの資料でも３件ほど紹介していますけれども、大井林町の高齢者住宅、これは３分の１の減額ということです。時価に対して３分の１を東京都が減額して区に対して払い下げをしたということで、東京都についてはそういう減額の措置も残っております。","voiceIndex":63,"id":"exchange-030"},{"speaker":"山内副委員長","kind":"質問","question":"そうなると、これからの行政サービスといったときには、払い下げで購入していこうということが今後、困難になってくるのかなという感じがするんですけれども、その辺は既に庁内で、そういった話が出ていると思うんですけれども、今後のそういった考え方、払い下げに対しての品川区の対応をどのように考えているのかということを伺いたいですね。","respondent":"日下部企画部長","answer":"公共施設の有効活用プランのときにもご説明させていただきましたけれども、これから施設の老朽工事がかなり出てくる、そういう時期に入っていきますので、その更新をするときに、ただ今までの施設をそのまま漫然と同じような形で更新していくということではなくて。","voiceIndex":65,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":34763,"voices":72}},{"id":"h24-20121107-17","meetingId":"h24-cm11","date":"2012年11月7日","dateIso":"2012-11-07","committee":"震災対策特別委員会","time":"午後１時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"２点伺いたいと思います。ところが、配布された直後は、当然、見た中でも、１年、２年、ずっとそのまま保存されるかというと、これはそれぞれの事情も十分想定されるわけで、改訂の頻度は極力、ある程度、目安をつけて、１年のスパン、あるいは２年スパンとか、この必要性があると思うんですが、その辺のお考えを１つ伺いたいことがあります。","respondent":"鈴木防災課長","answer":"理由は、まず今年度改訂いたします地域防災計画ですが、ご存じのようにバインダー形式をとりまして、新しい情報なり、新しい考え方なりが出るたびに、地域防災計画も差し替えをすることで常に新しい状態に保てるようにしたいという考え方がありますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ありがとうございました。初めに改訂のところですが、３年から５年、これは人の感じ方があるかと思いますが、意見として言わせていただくと、しながわガイドでしたか、品川の広報の改訂なんかも頻繁に感じるんです。何年かは定かじゃないんですが、５年というとかなり長く感じますので、３年未満を想定されながら発行すべきものと思うので、これは要望として。","respondent":"鈴木防災課長","answer":"ご指摘がありましたように、具体的なレイアウト構成、もしくはページ構成はこれからですので、いただいたご意見を参考に、地区割りが、例えば荏原を東、西に分けるということを以前やったこともありますので、具体的に地図を実際のサイズでつくってみまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、それと同じような発想で、地図も全部の品川区全域になると、また小さくなってしまうので、また配布するのも難しいかもしれないんですけれども、荏原地域にお住まいの方は荏原地域の部分だけでも、例えばセパレートして入れておくとか、もしくは全部に地図のところは切り込みが入って、自分の住んでいるところは切って張っておくこともできるみたいな。","respondent":"鈴木防災課長","answer":"確かにご指摘、ご意見がありましたように、多分、配った当初は何回かご覧いただいても、大事にしまわれたり、日々目にするというケースは減ると思いますので、その辺は、切り離して必要な情報をいつも張っておいたり、目につくようにできるような形で工夫をしたいと考えます。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"スケジュールのところに書かれている受託事業者と契約が済んでいるということなので、この受託事業者はどこなのかということと、あと、その受託事業者がどこかの自治体のこういったハンドブック、防災関連を経験されているのかどうかという情報をお願いします。","respondent":"鈴木防災課長","answer":"１回打ち合わせをしまして、２３区内で３区ほど過去に実績があるというところまでは聞いております。申しわけありません。今、お答えできるのはその部分になってしまいます。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"前にも私たちはこれで学習会をしたときに、区が何をしていますということが、まさしくこの防災アドバイザー研修修了式みたいな写真が真ん中にどんと置いてあるということに象徴的にあらわれているなと思うんですけれども、区がどういうことをしているんだというよりも、これ自身がわが家の防災のハンドブックなんだということで。","respondent":"鈴木防災課長","answer":"今いただきましたご意見の中で、まず、区民の方がどう行動するかですが、目次としては、項目名に出てまいりませんが、それぞれ「地震が発生したら」、「津波が発生したら」という章が小さな数字のところで目次をご覧いただくとありますように、その中で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"書かれていることは全部網羅しているんですけれども、ですから、そういうふうに行政として何か、それこそ縦割りにやるのではなくて、流れ的に私たちが、区民がどう動いたらいいのかというふうにしていただいたほうが、多分、皆さんも読み物としてきちんと継続して読んでもらえる、いつもいつも繰り返し目にしていただけるというものになるというふうなイメージです。","respondent":"鈴木防災課長","answer":"私の説明で至らなかったようですが、確かにおっしゃるとおり、地震だけ単発、津波だけ単発ということはございませんので、そういう意味では、多分、地震のところに、それに関連して火災が発生したら、津波が発生したらという流れが出てくると思いますので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、そういうところの表記もぜひ工夫をしていただきたいのと、あと、ここに帰宅困難者になった場合というのは、いつもうちにいるわけじゃないので、自分が外にいたときにどういう行動をとれるかということも、ふだんこういうもので身近に読んでいると、自分は出かけ先ではこういうふうにうちに戻ってこられる対策があるんだとか、事象別に、うちにいるとき、外出しているときとか。","respondent":"鈴木防災課長","answer":"内容の文章の表記ですが、確かにご指摘がありましたように、現在のものは、タイトルがあって、簡単な短いセンテンスの文章で読みやすくという重点ですが、読みやすくわかりやすいというところは継続しながら。","voiceIndex":17,"id":"exchange-007"},{"speaker":"吉田委員","kind":"提案","question":"手元に置いていただいて熟読していただくという意味で提案なんですけれども、例えば、対象年齢を考えますと、絵も入っているので、難しい漢字に仮名を振っていただいて、お子さんなんかも見られるような提案をしたいと思うんですけれども、そういうことも、また、あとここに例えば穴を１個あけて、ひもを各自つけていただいて、玄関につるすなり、寝るところにつるすなりとか、そういうような。","respondent":"鈴木防災課長","answer":"ご指摘いただきました、読みやすい、また対象年齢等にかかわらず理解ができるという部分、それから日々、目について、何か活用いただけるというところは、確かにご指摘がありましたように、意識をしていただくだけではなくて、それは自然の行動のときに。","voiceIndex":19,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"お子さんにも見やすく、高齢者の方にも見やすく、先ほど字が小さいという話がありましたけれども、そして、また、例えば外国の方でも仮名が振ってあると、英語でというわけにはなかなかいかないのかもしれないんですけれども、その辺もちょっと考えていっていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"木村委員","kind":"質問・要望","question":"それと、こういう本だと、どうしても今言ったようにどこかにしまっておく、そして文字が大変多くなっているということで、絶えず読むことは難しいと思います。だから、１枚の紙、折り畳みにして、それをぱっと広げて壁に張っておけるようなもの、もっと簡素化して、何かがあれば、いつでも目につくようなところに置いておく、張っておくということも１つの案ではないかなと思います。ちょっとお答えください。","respondent":"鈴木防災課長","answer":"１点目の穴をあけてつるすようにする場合には、しっかりとしたビニール製のリボンというんですか、細いビニールのもの、そういうものをつけて、すぐそうやってかけていただけるような状態にするとか、それから。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"委託先は光村印刷ということですが、委託費がどれぐらいなのかということを１つ教えていただきたいのと、スケジュールのところで、ここでは１１月に内容、構成等検討ということでなっているんですが、今日は大まかなこういうふうな方向でやりたいということはご説明いただいているんですけれども、実際にでき上がった案を、できればこの次の１１月２９日の委員会に示していただいて。","respondent":"鈴木防災課長","answer":"先ほど申し上げましたように、第１回目の業者打ち合わせを先週済ませたばかりでございまして、１１月２９日までにこのような具体的な形にしてお見せできるレイアウトとか、構成を用意することは難しいかと思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、一番初めのところなので、資料編に出されるという、例えば地域別の危険度（総合、火災、倒壊）、それから今回、地盤高も出されていると思うんですけれども、そういうものですとか、津波の情報ですとか、そういう形での、自分のところがどうなるのかということをイメージ、認識できるような被害想定を初めのところで出していただいたほうが。","respondent":"鈴木防災課長","answer":"完成前にイメージなり、いただいた意見を反映させている部分のご報告ですが、これについては計画の改訂の中から影響を受ける部分もあわせてやるということで、具体的に実際に色のついた絵柄を含めてお示しできるか、それとも。","voiceIndex":26,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところです。そういう点では、これをどう生かして、この機会に防災意識をより高めて地震に備えるかということが求められていると思うんですけれども、この間、荏原消防署に伺ったときに、荏原消防署では町会ごとに、消防署が町会に入って座談会をされたということをお聞きしたんです。","respondent":"鈴木防災課長","answer":"ただ、先ほど申し上げましたように、ＤＩＧを使いまして家庭内でこれを使って話し合っていただくとか、そういうことも想定しておりますので、区として行う啓発活動の中で、これを活用する場面も少しできないかというようなことを検討してみたいと考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、その後には耐震の補助制度とかなんかは出ていますし、地域別のところにはそういう倒れやすいとか、そういうふうなものが出てはくるんですけれども、予防というふうなところを力を入れた、そういうハンドブックにしていただきたい、そして、そこの中には耐震、住宅の耐震化ということをちょっと強調するような形で取り上げていただきたいと思うんですけれども、そこの点を１点。","respondent":"鈴木防災課長","answer":"つまり、初期消火なり、耐震なり、津波の備えなり、トータルで災害に備えていただくという観点で区としては啓発していますので、耐震についても不足な部分の記載については充実させまして、情報はきちんと調えますが、特に耐震の部分を独立させたりとか。","voiceIndex":30,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことからいえば、建物の耐震化ということは予防の中で一番力を入れてやらなくてはいけないということがあると思うんですけれども、そこら辺のところの区の認識はいかがでしょうか。","respondent":"鈴木防災課長","answer":"ただ、先ほど申し上げましたように、倒壊をして火災が起きるのが危ないということであれば、倒壊しないことも大事ですが、倒壊しなくても火災は起こりますので、やはり火災も大事ということで、区は、ご存じのように、初期消火体制。","voiceIndex":32,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一撃で命を落とす方がこれだけたくさんいるわけですから、倒れてしまったら、そこから逃げられないために火災に巻き込まれて亡くなるという方もかなりたくさんいらっしゃったというのが阪神・淡路大震災の教訓だと思いますので、そういうところでは、私は耐震というふうなところに区民がどれだけ意識をしっかりとそこに向けて進めていくかということが大事なことだと思うんです。","respondent":"鈴木防災課長","answer":"耐震化が必要だということがまずあるという、それぐらい重要だということは区も認識しておりますが、先ほど申し上げましたように、「地震に備える」という中で必要な項目をそれぞれ挙げていきます。","voiceIndex":34,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり私は巨大地震から命と財産を守る、そのためにどういうふうなことが大事かというところで区民が認識できるような形にしていただく、私はそのためには耐震というのは特に強調するということが本当に大事だということを改めて要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問・要望","question":"その辺のところのご意見をお聞かせいただきたいのと、それからページ数に関しては、今回、いろいろ改訂で、こういった形での同じような大きさの同じような量なのかということをお聞かせください。それから、あと全世帯配布ということで、来年の３月ということですけれども、どういうふうな形で全世帯に配布をされるのかということをお聞かせください。","respondent":"鈴木防災課長","answer":"３点目の全戸配布ですが、基本的には、新聞折り込み等だと、新聞をとらない家庭も増えておりますので、現時点では、一応、シルバー人材センター等にお願いしまして、きめ細やかに、１戸ずつ各世帯に配れるような形で配布したいと考えております。","voiceIndex":37,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"全戸配布ということの中で、これは「わが家の防災ハンドブック」という名前ですけれども、区内には企業が中小零細企業もたくさんありますけれども、これの内容は、企業にいるとき、会社で働いているときにも震災とか災害が起きるということで、会社にも１冊、こういうものが区内の会社にもあったら、やはり必要な部分もあるんじゃないかと思うので。","respondent":"鈴木防災課長","answer":"申しわけありません。現時点では、この名前のとおり「わが家の防災ハンドブック」ということで、区民の個別世帯を想定して考えておりましたので、企業の方へのこういう重要情報の提供につきましては今後の検討課題ということで検討させていただきたいと思います。","voiceIndex":39,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"帰宅困難に関することでも、区民の個別世帯の、これはやはり問題だと思うんですけれども、今後、これは、見た限りでは、このところには帰宅困難についての文言は全然出ていないんですけれども、そこのところをどういうふうに捉えて、どういうふうにこれは反映されていくのかをお伺いしたい。","respondent":"鈴木防災課長","answer":"帰宅困難者についての記載のお尋ねですが、ご指摘のとおり、現在のハンドブックでは帰宅困難者という項目は特に立てておりません。先ほど説明した目次にも、実は出てまいりません。","voiceIndex":41,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"外から来る方は今回除外して、あくまでも品川区民の方で、この防災ハンドブックに目を通して学んでいただく方という中で話をさせていただいているわけですけれども、帰宅困難、これが初動体制として非常に皆さん一番困る部分があると思うんですけれども、そこの中で緊急連絡先、ここのところ、前回のを踏まえると、警察、消防、ガス、ＮＴＴと書いてあるんですけれども、ここのところ、今。","respondent":"鈴木防災課長","answer":"これを区民の方にお知らせするには、まず先方の許可を得ないといけませんが、先方も区民の方個別にお問い合わせをいただいても対応し切れないので、多分、公開していいということにならないと考えられますので、区でしっかりとそういうところと連携をとりながら情報をとりまして。","voiceIndex":43,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"課長も計画を立てている当事者なのでおわかりになる。このところを区民の方は、どっちへどういうふうにしたらいいかということはわからないので、そこの部分ははっきりさせておく必要があるんじゃないかと思っているんですけれども、いかがですか。","respondent":"鈴木防災課長","answer":"ただ個別に区民の方が区なり、もしくは駅なりに問い合わせするのではなくて、区のサイドで必要な情報を提供する中でやっていただく、もしくはＮＴＴの災害時の伝言ダイヤルであるような、ご家族との連絡方法とか、そういうものは個別にやっていただくような形になりますので。","voiceIndex":45,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"今、私がお伺いしたところで、区のほうで対処したいような部分ということがありましたけれども、ここのハンドブックの最初のレジュメをいただいて、目的がありまして、主な変更点が書いてあります。私は方針なり指針というものをここのところにちょっと書いていただきたかったと思うんですけれども、そこのところ、まとまったというか、一応、方針なり指針がありましたら、今、お伺いしたいです。","respondent":"鈴木防災課長","answer":"全体的な方向性、もしくは方針というものにつきましては、２番の主な変更点の一番最初に書いてあります「全編で章立て、レイアウト、イラスト等を変えてイメージを一新」というところが大もとの編集の上で常に立ち返る方向性だと認識しております。","voiceIndex":47,"id":"exchange-023"},{"speaker":"大沢委員","kind":"意見","question":"課長が認識をされていて、僕は今、説明を聞いてわからない。であれば、変更点ではなくて、ここはまさにイメージを一新、各論に入る前の総論であるから、これは別立てで示しておく必要があったんじゃないかと思うんですけれども、どのようにお考えになりますか。","respondent":"鈴木防災課長","answer":"ご指摘のとおり、確かにそういう意味では、主な変更点ではなくて、まず前段として目的があって、こういうふうに一新することで区民の方により活用いただけるということを独立させたほうがいいというご指摘はそのとおりですので、すみません。","voiceIndex":49,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"改めてお伺いしたいと思いますので、せっかく委員会資料ですので、確かに議論を深めるための資料であるべきだと思いますので、そこのところはお願いをさせていただきたいと思って質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-025"},{"speaker":"阿久津委員","kind":"質問・要望","question":"それで、１つお伺いしたいのが、備えるということで標準的なデータというか、対処の仕方が載っているかと思うんですけれども、３・１１を我々は経験して、あのとき釜石の奇跡ということがありましたけれども、いわゆる想定外に備える、想定を信じるなという、これは想定だと思うんですけれども、想定を信じるなという１つ、あのとき、はやったというか。","respondent":"鈴木防災課長","answer":"例えば現在のハンドブックの６ページをご覧いただきますと、下のほうに囲み記事のような形で防災に関する情報提供みたいなものがあるんですが、ここは高層住宅についての情報提供ですけれども、これを単なる本編にあるような情報のコラムではなくて。","voiceIndex":52,"id":"exchange-026"},{"speaker":"阿久津委員","kind":"質問・要望","question":"津波ワークショップに出ていて、いろいろなご意見が出て、答えられる部分、でも、行政でも対応できない部分、わからない部分もいっぱいありますということで、率直にお答えいただいて、それはそのとおりだなとも思いますし、その中で、最後、釜石の奇跡の記事を読まれるという、あそこでワークショップ自体に魂が入っているのかなというところを感じましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-027"},{"speaker":"高橋委員","kind":"質問","question":"３つで、１つ目は３９ページに危険度のマップがあるんですけれども、これは、今度新しくなるのは想定が随分変わってしまうのかもしれませんけれども、１５ページから地区別に課題が出ているんですが、そこに地図を使っていますよね。それから、あと、これも私が聞き漏らしたのかもしれませんが、３７ページのハザードマップは平成１５年の東京都の調査なんでしょうか。","respondent":"鈴木防災課長","answer":"それから３点目、区長の挨拶の写真ですが、これは職員向けに今年の３月発行いたしました災害初動対応マニュアル等でも、区長はしっかりと防災服を着た写真を使っておりますので。","voiceIndex":55,"id":"exchange-028"},{"speaker":"向委員","kind":"質問・要望","question":"１点だけ、地図のことなんですが、３３ページとか、３５ページ、３６ページとか、このあたり、３１ページからです。私だと、反対に救護所だけ赤い線で囲むとかすれば、ぱっと見たときにわかりやすいかなとか、なので、すべての情報を区民が知っていればいいのかどうかだけは私は検討していただきたいと思ったので、それをよろしくお願いしたいんですが、お考えをお願いします。","respondent":"鈴木防災課長","answer":"ただいまいただきました、区民の方が本当に優先的に知るべき必要な情報かどうか、もしくは関連情報なのか、それから色やイメージでの伝わりやすさ、それから、当然、見た目の文字の大きさも含めたわかりやすさ、この辺はご意見いただきました観点でもう一度必要な情報を精査して。","voiceIndex":57,"id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"それで、それはこれと直接違うんですけれども、これの位置づけとして、そういう防災地図をこれに合わせて例えばもう一回発行するのか、それともこれはもう防災地図は発行しないで、これをそれにかえるということなのか、目的はちょっと違うのかもしれないですけれども、これは持ち歩きはあまり想定していないんでしょうけれども、今までお配りしていた防災地図は、例えば会社に行くにも。","respondent":"鈴木防災課長","answer":"ただ、現時点、まずは各家庭にお配りするハンドブックを先にやらせていただきまして、その内容も踏まえまして、防災地図も次のステップでまた更新をして配布するというようなことで考えたいと考えています。","voiceIndex":59,"id":"exchange-030"},{"speaker":"武内委員","kind":"意見","question":"私が思っていた防災地図というのはもう１つ古いタイプの、本当に手で持てるぐらいのものが前、あったじゃない。幾つも折ってあって。こういうものは全部かばんとかに入れないと持てないんだけれども、あれぐらいの大きさだと、ポケットに入れたりとかってできたんだけれども、あれは、一切ああいうことはもう考えないということなのか。","respondent":"鈴木防災課長","answer":"ご指摘がありましたように、そういう便利な使い方ができる、別の使用方法を想定したものについては検討させていただいて、帰宅困難者の対策等も講じる中で、いろいろな地図等も出てくると思いますので、そういうものとあわせまして。","voiceIndex":61,"id":"exchange-031"},{"speaker":"木村委員","kind":"意見","question":"この想定外ということは、東京都が発表したことに関しては、想定外というか、あまりに大きな被害、そこまでの、今回は３・１１の場合は津波ということだったんですけれども、もし大きな首都直下型の地震が来た場合、この品川区でも、もちろん東京都全部でしょうけれども、想定外ということとすれば、何が一体想定外だと思いますか。","respondent":"松代防災まちづくり事業部長","answer":"東京都が出した被害想定でいいますと、地震が起きて、津波が発生した場合はその津波高さが幾つですよというものが出ました。それに対して今の防潮堤の高さはＴ.Ｐ.で３.５ありますというような話でご説明をしました。","voiceIndex":63,"id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"大変難しい質問でした。想定外ということを東京都は、一応、津波が来ても２.６ｍですか、ということを言っておりましたけれども、そういうことも、また、それが満潮時とか、いろいろなものが、台風だとか、そういうものが一緒になれば、もっともっと高いものが来るであろうということで、多分、津波のことが心配だなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"よく私たちがパソコンを買ったときに、取扱説明書みたいに、地震に備えるとすれば、地震の前にあなたができることとか、やるべきこととか、そういう目次を見て、そこにすぐぽんと私たちが飛べるような、そういう発想も必要じゃないかなと、地震が発生したらというときに、まずすることとか、次がどうとか、そういう取扱説明書の書き方というのもちょっと工夫できるんじゃないかと思いましたので。","respondent":"鈴木防災課長","answer":"資料ではこういうふうにお示ししたんですが、これは変更させていただきたいと思います。","voiceIndex":66,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"火災対策と津波対策の順番は火災対策を先にしていただきたいということだったので結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-035"},{"speaker":"本多副委員長","kind":"質問・要望","question":"１点だけ質問します。例えば４ページに災害用伝言ダイヤルで１７１プラス幾つというものが出ているんですが、それ以外、例えば水上で何かがあったときにも３桁でつながったりするところがあるじゃないですか。関係機関、そのほかにも何種類かあると思うんですが、そういう緊急を要するものはぜひここに入れていただけないか。その点だけお願いします。","respondent":"鈴木防災課長","answer":"緊急先リストの電話番号の件ですが、確かにご意見にありましたように、３桁で、本当の緊急性があるゆえに多分、３桁で設定している番号だと思いますので、それはぜひ取り入れさせていただきたいと考えております。","voiceIndex":69,"id":"exchange-036"},{"speaker":"阿久津委員","kind":"質問","question":"まとめていただいてありがとうあります。前回、９月２７日の主な意見（案）の中で、災害時の動物愛護ということでここに掲載していただきまして、ただ、今回の中からこれは削除されているんですが、そこについての削除された理由についてお伺いしたいと思います。","respondent":"南委員長","answer":"改めて皆さんのご意見、各会派から出していただいたご意見等々も含めて整理し直したときに、もちろん動物愛護については当然のことだと思うんですけれども、しかし、今回は大きな地域防災計画の見直しの１回目に当たって、人命を最優先にしていきたいと考えたんです。","voiceIndex":75,"id":"exchange-037"},{"speaker":"阿久津委員","kind":"質問・要望","question":"多分、そこのところがちょっとこの表現だと、災害時の動物愛護という表現ですと、うまく伝わらなかったのかなということがありまして、地域防災計画の中にも動物愛護、避難所における動物飼育対策ということで、先ほど委員長から時期を見てということがあったんですが、まさに、今言わずしていつ言うのかという点があったものですから、私としてはこれが削除されたのは非常に残念に思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-038"},{"speaker":"南委員長","kind":"質問・要望","question":"ぜひ皆さんからこの項目、この項目ってないからわかりにくいですか。もしなければ、これをそちらに。このことについて、先ほども申し上げたように、正副委員長としては、今回は人命のことを中心に考えていきたいということで削除しようという判断をしたんですけれども、今、阿久津委員のご意見を伺った中で、皆さんは改めてどうかということで、ぜひ忌憚なくご意見を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"進め方なんですけれども、今日、阿久津委員から話が出たのはわかるんですけれども、前回、まとめについて正副委員長に一任したんじゃないんですか。だから、それで一任して、前回、承諾をこちらの委員のほうもしているわけですから、こういうときに議論云々というのは的がずれている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-040"},{"speaker":"井上委員","kind":"提案","question":"もう続けていいと思うんですけれども、一任云々というところは、委員会として出すので、そういう提案があれば、議論をして決着をつければいいと思いますので、進め方と言われても、すべてを一任ということは間違っていると思いますので、よろしいのではないかなと、それが委員会運営だと思いますので、よろしいんじゃないでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"この委員会自体の取り決めは重いわけでして、それは一任ということを今、簡単に翻って、議論が出たから話をしようって、何のための一任なんですか。委員会の取り決め事項の重さ、軽さにもかかわることなので、そこのところは委員長、強く私はお話をして、ご理解賜りたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"阿久津委員のところまでは理解をしました。しかしながら、次の井上委員から、まさにいいんじゃないみたいなこと、では委員会の取り決めって何だったんですかという、まさにその疑念を生じざるを得ないようなご発言があったので、私は発言させていただいた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-043"},{"speaker":"渡辺委員","kind":"質問・要望","question":"自分の理解も含めて確認させてください。今の委員長の説明でよくわかりました。もともとあった掲載文だし、記載内容だったので、ここは審議していいと思います。は改めて、いろいろ意見を求める時期ではないと思います。冒頭の委員長の説明のように、今日という中での後のチェック、最終チェック、文言整理だという認識でよろしいんでしょうか。その確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-044"},{"speaker":"武内委員","kind":"意見","question":"一応、文言のところで、今のはご意見をいただくとして、「高潮・津波対策」のところで、ごめんなさい。先ほどのハンドブックのほうも津波だけなんですね。今回、両方入れていただいていいんですけれども、(4)の1)、2)、3)の内容を見ると、全部、津波しか言葉として入っていないんです。どうせもんでもらうなら、一緒にやったほうがいいかなと思ったんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-045"},{"speaker":"渡辺委員","kind":"確認","question":"確認の上、発言します。先ほどの委員長の説明、あるいは阿久津委員の背景、趣旨が、人命にかかわる点からとか、その関係にかかわる点が聞いてみてわかりましたので、復活といいますか、先ほどの文章、戻ってもいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問・要望","question":"すいません、今、文面を確認したところ、全文復活だと、ちょっと先ほどのやりとりと違ってしまう部分、誤解を招く表現があるので、先ほどのやりとりの趣旨に沿って、人命にかかわる部分に集約してまとめていただきたい。そこは本当にそれこそ正副委員長一任でやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-047"}]},{"id":"topic-02","title":"品川区地域防災計画素案概要説明","agenda":"品川区地域防災計画素案概要説明","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今、体系の要点ということで説明をいただいたんですけれども、前回の本編のほうの地域防災計画の目次と大きく、これを風水害編とそちらのほうは別、４部、５部というところは別ということなんですけれども、震災編というふうに書かれているんですが、１部、総則は変わらず、２部の災害予防計画というところと３部の災害応急対策計画というのを、２部、３部を一緒にして１３編に変えるということなのか。","respondent":"高山防災計画担当課長","answer":"前回と目次が異なってというところなんですが、基本的にこれまで積み重ねてまいりました防災対策にかかわる、これまでの計画をその深く該当する箇所に練り込むような形で、それに加えて新たな検討事項、そして東京都の内容なども踏まえながら、この１３編に。","voiceIndex":103,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"ちょっとよくわからないんですけれども、そもそも震災編というのはなかったところに、この現在ある災害予防計画というようなところに、このこれから新しく入れるところ、変更も含めて、入れ込んでいって、ここにあるほとんどが残るという意味ですか。","respondent":"高山防災計画担当課長","answer":"ただ、目次立てをより上位計画との整合をとりやすい形で、それぞれの該当する項目に引き続き内容を横引くような形で、必要な部分について平成２４年度版にも反映していく、そのような意味です。","voiceIndex":105,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"災害予防計画の平成１９年度１編は、災害に強い都市づくりというところが防災機関の業務大綱とか、そういう形で変えていくというふうなことで説明をされているということでしょうか。","respondent":"高山防災計画担当課長","answer":"平成１９年度目次で記載されていることの、この形、ここに記載されていることの多くを新しい目次の体系に割りつけるということで、必要な事項について、引き続き平成２４年度版に踏襲されているというような意味合いでございまして、順番こそ違えど。","voiceIndex":107,"id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"地域防災計画というのは、区民に向けてではなく、行政内部の大きな計画として、これからこの計画に沿って施策とか、発展をしていくというふうなことだと理解しているので、これを区民が見てわかるかわからないかというものでは多分、ないんだろうなと思うんですけれども、でも、これだけいろいろ議論をする中で、もう少し区民が見ても、こういう上位計画があって動いているんだなというふうなことは。","respondent":"高山防災計画担当課長","answer":"かなり、そういう意味では防災関係機関を中心として、区の総合的な防災対策に関する計画としてまとめるものなので、ある程度の専門性ということについてはご容赦いただきたいといいますか、そもそもそういう性質を持って生まれてきている計画だということはご理解いただいた上で。","voiceIndex":109,"id":"exchange-051"},{"speaker":"武内委員","kind":"確認","question":"今後の予定のところの確認なんですけれども、１１月２８日に品川区防災会議で素案が承認されたとして、翌日の委員会で報告と、そこでまたそれを私たちが見ながらいろいろなご意見を言わせていただいて、場合によってはそれがまた少し修正される余地はあるのかどうかということと、それから風水害編のほうは、これとはまた少し遅れてというお話なんですけれども、最終的にはどこで一緒になるのか。","respondent":"高山防災計画担当課長","answer":"内容の大半を準用する関係で、風水害編についてのパブリックコメント等は特段予定してございませんでして、最終的に２月に震災ならびに風水害にかかわる全般的な計画としてご承認いただく、そのようなスケジュール感でおります。","voiceIndex":111,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"委託されているのであれば、どこのコンサルタントに委託をされて、委託費がどれくらいだったのかということを１つお聞かせいただきたいのと、それから庁内もあわせて、どういうメンバーで、どう検討されて今回の計画作成になったのか、そこら辺のところをお聞かせください。","respondent":"高山防災計画担当課長","answer":"それから検討の体制ですが、通常ですと、こういった大きな計画の修正にあたっては、係る部分を庁内的な文言修正を中心に進める形ではございましたが、今回、より多くの職員ないしは所属に当事者意識を持ってもらうという意味も込めまして、検討に当たってテーマを持たせまして。","voiceIndex":113,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回、福祉避難所とか、そういう災害時要援護者の部分に関しては障害者福祉課ですとか、高齢者福祉課とかで、この委員会にも来ていただいて、かなり充実をされる方向が出されてよかったなと思っているんですが、どんな分科会がどれくらいされてきたのか、どんな分科会があって。","respondent":"高山防災計画担当課長","answer":"分科会、庁内検討の進め方です。実は４つほど分科会を組織して、この間、検討作業を進めてまいりました。１つは、先ほどお話しいたしました災害時医療に関する分科会です。主に保健所でありますとか、健康福祉部門にかかわってもらうこととなりました。","voiceIndex":115,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう意味でも、今回、１２月にパブリックコメントということになっているわけですが、このパブリックコメントをとるに当たっては、区民への周知ということはどういうふうに考えられているのか、この素案について、多分、広報とかで概要を載せるというふうなことは１つあると思うんですけれども、それ以外のところでどういうふうに、どこにどう資料を置いて、説明会とかなんかはどういうふうにするとか。","respondent":"高山防災計画担当課長","answer":"したがいまして、この前後にも大きな計画が公表されておりますので、おおむねそういった計画のパブリックコメントの手法などをまねながらといいますか、踏襲しながらの形で進めてまいりたいと考えております。","voiceIndex":117,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、パブリックコメントも求めるわけですから、私はぜひ区民への説明会を開いていただきたいと思うんですけれども、私は少なくとも１３地域センターごとに説明会を開いていただきたい。","respondent":"高山防災計画担当課長","answer":"繰り返しになりますが、より防災施策という意味での浸透というものは当然、必要だと考えておりますので、来年度の施策の１つとして、そういった区民向けの講演会でありますとか、そういったものの充実などは必要性は感じておりますので。","voiceIndex":119,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ホームページでこの概要はすべて載るんでしょうか。たくさんページ数がありますけれども、それを見て、なかなか理解できるということは難しいと思いますし、私は少なくとも１３町会と言いましたけれども、１回も説明会をしないでパブリックコメントをしていくという今の区の考えでしょうか。広報とホームページとその冊子を各施設に置いておくというだけしか考えていないということでしょうか。","respondent":"高山防災計画担当課長","answer":"区民を代表される委員の皆様におかれましては、発言１つ１つがそうした意味での区民の方々の意見の代弁とも考えておりますので、そういった部分を十分に取り込むような形で計画に生かしてまいりたいと考えております。","voiceIndex":121,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、私は先ほど説明のあった防災ハンドブックをあわせて、今回のこの防災計画とを一緒にした形でもいいと思いますので、ぜひ区が区民の命と財産を守るという立場に立つというのであれば、ぜひ区民に知らせて、区民の意見を聞いて、そして実効性ある中身に変えていくということで、そういう説明会をしていただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":48019,"voices":127}},{"id":"h24-20121126-6","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"区民委員会","time":"午前１０時００分～午後２時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の区民集会所の利用状況","agenda":"の区民集会所の利用状況","exchanges":[{"speaker":"山内委員","kind":"意見","question":"つまり、例えば電気料だ何だというのがもちろん使えばかかってくるだろうけれども、今日の段階だと電気もついていなかったし、だからそういうことを考えると、ランニング的なものをどのように考えていて、それでそれをいろいろと考慮する中で、じゃあ、廃止になるのかというような対象にはならない場合、改めて見させてもらって感じたんですけれども、そのあたりというのはどうなんだろうか。","respondent":"久保田地域活動課長","answer":"こちらにつきましては、耐震診断のお話を前回もさせていただきましたけれども、こちらは構造上、ちょっと耐震補強がなかなか難しい施設ということもありますので、耐震改修促進計画、平成２６年度末までに区有施設の９０％以上がということの計画からしますと。","voiceIndex":7,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"今のつながりで、荏原西区民集会所のところなんですけれども、例えば、今、これは例の予約システムには入っていないですよね。基本的にこの間の質疑の中でも、これの利用率を高めるには周知をしなきゃいかんと。それでいろいろやっていますよというお話があったんですけれども、その根本のところで予約システムに組み入れていくというのが一番の周知になると思うんだけれども、そこは考えないんですか。","respondent":"久保田地域活動課長","answer":"こちらのほうは地元の方に優先して利用してもらうというような経過もございまして、予約システムということではなく、実際に使っているのも地元の高齢者クラブの方たちということになっていますけれども、そういったご利用をいただいているところですので。","voiceIndex":9,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"それは今までの経過はありますけれども、そこは利用者の方によくお話しして、例えばその方たちが今までの経緯があるわけですから、優先的に最初にこの曜日のこの時間帯は使っているとわかるわけですから、そこはとりますよと。その上で、それでやはり利用率が上がらない。そこをとってあげた上で、それ以外の枠をシステムに載せるというような検討はできないものなんですか。","respondent":"久保田地域活動課長","answer":"ただもう一点、先ほどもお話ししましたように耐震等の問題もありますので、そういったものと現在の利用率等を考えていきますと、そうした一定の方向性、廃止も含めた検討もしていかなければならないのかなということで、私どもは考えているところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"最初の利用率のところでもう一回確認ですが、例えば品川第一区民集会所ですと、第１、第２、第３と三つの集会室がありますけれども、ここの午前・午後・夜間と三つの時間枠があるとすると、１日利用可能のところは九つという見方で、それに対して昼使った、夜使ったとかという利用実績を分子にして、利用可能な枠というのは、今、言ったように、例えば品川第一区民集会所だったら三つお部屋があるので。","respondent":"久保田地域活動課長","answer":"そうしたものを引いたものを分母にいたしまして、実際の利用数をその分母で割って算出したのが、新たな今回お示しした資料でございまして、もともとは、今、委員がおっしゃったように。","voiceIndex":13,"id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"高齢者の方がその階段を上り、そして下るということを考えると、やはりこの区民施設の有効活用という点から考えても、このパーセンテージ、そして耐震に関してもという形で、私は地域活動課長が、今、答弁した中においていろいろ選択がある中の一つもあるのかなと感じていますが、やはり構造上の問題等であそこの利用率の低さというのが、それこそ本当に本日の視察において感じているんですけれども。","respondent":"久保田地域活動課長","answer":"今回、利用率、構造等からいろいろと見直しを考えているところでは、そういうふうに決まったわけではございませんので、いろいろな今後の活用という検討の中で、廃止というものも一つの手段としてあるのかなということで、先ほどご説明させていただいたところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"このままでいいやということはもちろん考えてはないとは思うんですけれども、だからと言って５０％、６０％に上がるという可能性もちょっと考えられないので、その辺についてはいかがでしょうか。","respondent":"久保田地域活動課長","answer":"これにつきましては、この施設に限ったことではなくて、全体として耐震化の促進をしていかなければならないという目標が区としてもありますので、それが今の時点では平成２６年度末までにということで、こちらも議会のほうにはご報告していますけれども。","voiceIndex":17,"id":"exchange-006"},{"speaker":"井上副委員長","kind":"質問・要望","question":"そのことについて、地域センターだけはこうしますよということではないと思うので、その辺、全庁的にちょっと見直すなら見直すということでしていただきたいと先ほどのお話を聞いて思ったのですが、その辺は何か問題があると思われているのか、地域センターだけできればいいかなということなのか、どうでしょうか。","respondent":"久保田地域活動課長","answer":"改修した結果、１クリックというか、条件さえ設定すれば集計が容易になったというところで、今回、こういったものも短時間で、ちょっと時間はかかっていますけれども、一定程度従前よりは簡単に算出できるようになったというところがありますので、今回これを契機に。","voiceIndex":19,"id":"exchange-007"},{"speaker":"井上副委員長","kind":"質問・要望","question":"それをできるようなシステムに、問われなくてもそういうふうにできるということで合計をしたとか、もう少し検討をして、わかりやすいところでできれば統一するということは基本だと思うんですけれども、その辺を検討していただきたいと思いました。これは要望でお願いしたいと思います。","respondent":"久保田地域活動課長","answer":"集計表のほうの１点目のご質問について、ちょっと私の説明が足りませんで、今回、平均でやっていたというのは地域センターの集会所のところだけですので、我々が確認しているやり方はですね。","voiceIndex":21,"id":"exchange-008"},{"speaker":"井上副委員長","kind":"質問・要望","question":"今回、そういうところで、そういうことがなければずっとそういう算出をされていたということのほうが、逆にちょっと問題なのかもしれないと思いました。やはりほかがどうかというのは、ここの縦割りではなくて、調べますということでしたけれども、企画とかそういったところも含めて、やはり問題提起をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"の品川区立創業支援センターの現状","agenda":"の品川区立創業支援センターの現状","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、品川区がやってきている創業支援センターの目的を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"創業支援ということによりまして、区内の地域産業の振興を図っていくというものになります。","voiceIndex":29,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"目的はそうで、利用率はこういうふうになって利用されているというのはわかるんですけれども、これも改めてですが、利用率を上げるためにつくっているわけではないですので、まさに、今、ものづくり・経営支援課長が答弁していただいた目的がありますよね。この各支援センターが目的をどういうふうに達成しているのかというのを、区としてはどのように捉えているのか、教えていただければ。","respondent":"福島ものづくり・経営支援課長","answer":"創業して大きくなった会社もあるんですけれども、西大井創業支援センターの小さいところから、何百人規模の会社になったという事例もありますけれども、まだ１０年たっていませんので、逆に言いますと平成２５年で１０年たちますので、その辺のところを総ざらえして。","voiceIndex":31,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"けれども、その中のどのくらいの割合がこうなったとかというのを具体的にある程度ちゃんと押さえておかないと、創業支援ですから創業させることも目的の一つかもしれませんけれども、それから創業したのが事業としてちゃんと存続して、雇用も含めたことでということを押さえておかなければ、利用率１００％でというものだけじゃないと思うので、そこは押さえていただきたいと思っています。","respondent":"福島ものづくり・経営支援課長","answer":"今後の課題ですが、そういった調査も含めまして、どのような成果が上がってきたのか、その辺のところを総括していく時期であろうと考えていますので、平成２５年はしっかりしたいと考えています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"ちょっと基本的なことを教えていただきたいんですが、西大井創業支援センターと武蔵小山創業支援センターについて、インキュベーションマネージャーという方が、配置されていると捉えていいんですか。それから、このインキュベーションマネージャーの勤務実態とか、あとどのくらい区がこの方に経費を払っているのかというのが大体わかれば、教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"金額ですけれども、インキュベーションマネージャーにというよりは、一括して施設運営という形で委託していますので、なかなか出てくるのは難しいんですけれども、委託したそのインキュベーションマネージャーに幾らということではなくて、施設運営ということで。","voiceIndex":35,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"プラス、オフィスの方も受けられるんでしょうか。そうすると天王洲創業支援センターとの違いというんですか、天王洲のほうもオフィススペースがあるんですけれども、そこはインキュベーションマネージャーというのはいらっしゃらないわけなんですけれども、そこのコンセプトとか考え方の違いを教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"賃料も少し高いので、なかなかすぐそのまま、小さい段階で入るというのはなかなか難しいかと思いますので、あまりそういういわゆるインキュベーション的な支援は必要とされない方が入っているというのが実態です。","voiceIndex":37,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"そうすると、何が言いたいかというと、西大井創業支援センターのオフィスに行ったときに、インキュベーションマネージャーの方が、ほかのところが下がっているという相対的な部分で、家賃がなかなか決して安いとは言えないというような言い方だったんですけれども、ただ、プラスアルファとしてはそのインキュベーションマネージャーの方がそこでいろいろなアドバイスをしてくれているという部分は。","respondent":"福島ものづくり・経営支援課長","answer":"こちらのＡ３の表にありますように、この利用実績をごらんいただきますと、西大井創業支援センターのほうの（１）創業支援スペースの場合は、今の段階でほぼ１００％ということで、募集をしますとすぐここは埋まるという状況が続いています。","voiceIndex":39,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、家賃・使用料の話があったんですけれども、近隣が下がってきているのでというその時点で、こちらも下げていく、同じようにしていくという考えはしなかったのかというのと、あと今後、周りの状況も見ながら、これが変わっていくということはあり得るんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"家賃につきましては上がり下がりが激しいので、それに区として対応していくというのはかなり難しいと思います。","voiceIndex":41,"id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問・要望","question":"そういったところをどういうふうに区は評価するのか、これからどういうふうにこれを考えていくのかということは、ちょっと教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"これが、費用対効果としてどうなのかということなんですが、当然区としましてはこれだけかけていますので、それだけの実績は得たいと考えていますし、下に平成２３年度に行いました創業塾、全１８回の塾でしたけれども、それにも二十数名の方が参加されまして。","voiceIndex":43,"id":"exchange-017"},{"speaker":"井上副委員長","kind":"意見","question":"武蔵小山創業支援センターのところで、おおむね３年以内の法人にチャレンジショップとか賃貸オフィスとかいうんですけれども、そこら辺のところというのは、当初の条例づくりのところにも関係するかもしれないんですけれども、これからつくっていこうというような人の支援とかではなくて、安定をさせる支援というところでこの辺は入られているのかということと、あと条例のほうにいろいろな定義がある中で。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、それだけですとやはりなかなか難しいということもあり、創業したということを「創業したか」というのも難しい、つまり創業はしたけれども実態がなくて、もう１年、２年たってしまったというような人の場合ですと、こういうところでおおむね３年以内にとか。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-03","title":"の行政サービスコーナーの利用状況","agenda":"の行政サービスコーナーの利用状況","exchanges":[{"speaker":"本多委員","kind":"質問","question":"駅前のサービス向上ということではすごく内容も目的もすばらしいと思うんですが、一つお聞きしたいのが、この人員配置で大井町行政サービスコーナーが人員１２名、武蔵小山行政サービスコーナーが人員９名ですけれども、それぞれ内訳が書かれているんですけれども、その募り方というのはどのようにしているんでしょうか。","respondent":"井浦戸籍住民課長","answer":"大井町行政サービスコーナーあるいは武蔵小山行政サービスコーナーにつきましては、これまでの勤務については、現員の配置としては平成１９年度以降を見ますと９名ずつ配置してございまして、図書のサービスを新たに増加したということがございまして。","voiceIndex":52,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"見させていただいて、利便性が非常にあるということと、利用もあるんだなということを実感させていただいたんですけれども、確かに近くにあれば、やはり区民の方は利用されるということなんですけれども、ただ今後の考え方という中で、これは例えば地域センターだとか、そういう図書館が近くにないところだからやるという考えよりも、どちらかというと駅に近くて。","respondent":"井浦戸籍住民課長","answer":"武内委員の今のご指摘のとおりでございまして、その２カ所につきましては、大井町行政サービスコーナーについては駅そのものだと、武蔵小山行政サービスコーナーについては駅の周辺の場所ということで。","voiceIndex":54,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今後、例えば、今、目黒駅のところも再開発をやっていますけれども、そういう形で駅に近いところで、区のほうも関係の中でその再開発が行われていく中で、例えば同じような利便性という面では当然声が出てくると思うんですけれども、ただ一方で、地域によってはすぐ近くに図書館があったりとか地域センターがあるよという、大井町行政サービスコーナーの場合は区役所。","respondent":"井浦戸籍住民課長","answer":"例えばご指摘にありました目黒駅ですとか、あるいは図書館が近くにあるところ、ないところもありますので、住民票等のいわゆる交付実績あるいは図書の貸し出しの実績等を区内全域でつぶさに見まして、その中でバランスを考えて。","voiceIndex":56,"id":"exchange-021"},{"speaker":"井上副委員長","kind":"質問","question":"一つだけ、嘱託非常勤職員と専門非常勤職員、先ほど少し説明いただいたんですけれども、もう一度その違いとどういう要件なのか、お願いします。","respondent":"井浦戸籍住民課長","answer":"専門非常勤につきましては、この６５歳のいわゆる再任用と嘱託非常勤の任期を満了した職員について、成績が優良あるいは職務知識や意欲があるという人について、専門非常勤ということで、こちらにつきましては住民基本台帳関係事業費の予算の中で。","voiceIndex":58,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":24185,"voices":64}},{"id":"h24-20121126-7","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"厚生委員会","time":"午前１０時００分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２４年請願第１４号、ウルトラ・オーファンドラッグ（患者数が特に少ない希少疾病用医薬品）開発促進・支援のための法整備等を求める意見書の提出に関する請願","agenda":"平成２４年請願第１４号、ウルトラ・オーファンドラッグ（患者数が特に少ない希少疾病用医薬品）開発促進・支援のための法整備等を求める意見書の提出に関する請願","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"現状、どういう仕組みになっているのか、そこを改めて伺いたい。当然、患者数が少なければ、採算性が取れないという関係になるわけですけれども、そこへの支援の現状を、改めて伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"現在のところ、先ほど、説明で申し上げましたように、平成５年に薬事法が改正されまして、その中で、オーファンドラッグ制度というのが決められたわけですけれども、現状としましては。","voiceIndex":6,"id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"難病と言われているもので、非常に患者数は少ないんだけれども、難病の種類としては結構な数があって、それぞれの病気にかかっている方は、全国で非常に少ないんだけれども、いろいろな全部を引っくるめた、いわゆる希少疾病ということで困っていらっしゃる方というのが、例えば品川区で、どれぐらいの数がいると、想定でもいいですけれども、もしわかれば教えていただきたいと思うんです。","respondent":"工藤品川区保健所生活衛生課長、福島品川区保健所荏原保健センター所長","answer":"ただ、いわゆる難病、特定疾病と言われるものは、区内ではございませんけれども、全国的には数千、５,０００前後あるといわれているところです。これは、認められた８１疾病に関しての医療費の公費負担ということです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"一日も早く、というご要望ですので、結論を出すということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"請願者の方を含めて、私ども自民党も、多分、初めて勉強させていただいたというか、不勉強なところもありまして、お話を伺ったというところであります。どのような形になるか、いまだにちょっとよくわからない部分もあるわけですけれども、請願自体は、意見書を提出してほしいということでありまして、我々としては、意見書提出を含めて、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-004"},{"speaker":"若林委員","kind":"質問・要望","question":"それが整った際には、医療費補助承認ということで、国のほうでしっかりと取り組んでいただきたいという、公明党は紹介会派としても載っておりますので、しっかりと正副委員長には文面を考えていただいて、公明党といたしましては、意見書を出すというこの請願の採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-005"},{"speaker":"向委員","kind":"質問・要望","question":"たまたま私と同級生の方がいらっしゃって、発症したのが２０歳前後が推定ということだったんですが、彼女の３２歳までの１０年ちょっとと、私のこの１０年ちょっとを考えると、やっぱり胸が詰まる思いが大変しました。そういった経緯もありますし、今後もさらに支援を続けさせていただきたいなと、会派としても考えておりますので、採択ということで、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"意見","question":"ウルトラ・オーファンドラッグの支援が確立していないことが明らかになりました。命に格差をつくることは許されない。とりわけ経済格差は直ちに正していかなければいけないと思います。市場の中で採算性が取れない、だからこそ、国の支援が必要だと思いますので、意見書を出すことも含めて採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-007"}]},{"id":"topic-02","title":"平成２４年請願第１５号、軽度外傷性脳損傷についての区民への啓発・周知と、国への意見書提出に関する請願","agenda":"平成２４年請願第１５号、軽度外傷性脳損傷についての区民への啓発・周知と、国への意見書提出に関する請願","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"周知につきましては、このＭＴＢＩが発症する原因としては、子育てのときに、高い高いで小さな赤ちゃんの頭を揺すったりするとときに、それでも、こういうものを引き起こすことがあるというふうに、ちょっと資料で読んだんですけれども、そういった意味を含めますと、小さい子どもを抱えた方々、保護者の方々への周知であるとか、また、医療診断がなかなか難しいというところもあるようなので。","respondent":"福島品川区保健所荏原保健センター所長","answer":"第一の、外傷性の脳損傷の発生頻度ですが、２００７年のＷＨＯの報告では、１０万人当り１５０人から３００人、全世界では１,０００万人の患者が発生していると考えられます。外傷性脳損症の全体の９割が、この軽度の外傷性脳損症ＭＴＢＩと考えられます。","voiceIndex":32,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２点ですけれども、まず周知のことですけれども、現状では取り組みはないけれども、今後、講演会の中で周知していきたいというお話が、冒頭にあったかと思うんですけれども、とりわけこの請願は、区内教育機関への周知を要望とありますけれども、学校だったり、いろいろと教育機関はありますけれども、どういうところへの周知や取り組みを、現状、考えていらっしゃるのか、その辺。","respondent":"永尾障害者福祉課長、福島品川区保健所荏原保健センター所長","answer":"教育関係への周知ですけれども、現状で言いますと、軽度外傷性脳損傷についてのきちんとした説明ができない状態でありますので、この状態のままで、教育委員会のほうでＰＲするということになりますと。ただ、これを専門的に研究なさっている先生方の話の中では、神経学的検査をちゃんとやれば、そういう外傷に基づくものであるという証明はできるはずだと主張していますが、現在のところでは。","voiceIndex":34,"id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問","question":"現状、まだなかなかわからないところがあるということなんだと思うんですけれども、ただ、こういう症状で苦しんでいる方々が実際にいらっしゃることは事実でありまして、そういう方の生活だったり、医療費の負担だったり、そういうところの支援というのは、現状の仕組みの中ではどういう形になっているのか、その点を伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"その相談の中身に応じては、高次脳機能障害の専門相談員も配置しておりますので、そちらに回しながら、ご家族が具体的にどういうような対応をしていったらいいのか、保健センターとどういうふうに連携していったらいいかとか。","voiceIndex":37,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ここには、働けない場合、経済的に追い込まれるケースも多々あるのが現状ですとありますけれども、病気や症状の原因そのものはまだはっきりしていないが、実際の生活に係わるところでの支援策が、現状、どうなっているのか、改めて伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"就労に関していえば、就労支援センターのほうに回して、実際の訓練と障害者のサービスにのっとったものを行っているところです。","voiceIndex":39,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"日本語で書くと、軽度外傷性脳損傷という、この軽度という意味が、いわゆる軽いと書くんですけれども、軽度ということは、中度、重度があるということだと思うんですが、そこら辺の軽度というところの内容の確認をさせていただきたい。軽度外傷性脳損傷と高次脳機能障害との関係というんですか、それをもう１回、ちょっと整理させてください。","respondent":"福島品川区保健所荏原保健センター所長","answer":"先ほども、私の説明で、いわゆるＷＨＯの診断基準の中でも申し上げましたように、頭部への外傷、圧力等を受けたのが軽い場合でも、極端な言い方をすると、症状はひどい場合があるということ。","voiceIndex":41,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、いわゆる外傷性脳損傷の中には、重度、中度、軽度があって、要するに区民への周知、教育機関への啓発というものもご要望されているので、全体の外傷性脳損傷のうち、資料を見ると、大体９割は軽度だと、事故とか、転倒とか、赤ちゃんの揺さぶりという話もありますけれども、そういう方の９割もの方々が、そのまま軽度に分類されるんだと。","respondent":"福島品川区保健所荏原保健センター所長","answer":"明確な数字は、今のところはないと思われます。これも大体、みんな推計でのお話でして、日本での患者数も、３０万人ぐらいではないかという専門の先生たちの推察ということで、実際的にどれだけかというはっきりとした数字は、今のところはないのではないかと思います。","voiceIndex":43,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一方では、これは国への意見書という形で、労災の障害認定のほうですけれども、先ほど、一定の答弁がありましたけれども、いずれにしても、いわゆるＭＲＩとか、そういうもので、現状の認定基準というのが、画像とかで見えるものしか認められないという大きな前提があって、その中で、画像では見えにくい、見えないような軽度脳損傷については、裁判では何例か認められたということもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと意見を言わせていただきながら、態度を言わせていただきます。我が会派も、高次脳機能障害を含めて、さまざまなところでいろいろ質問もさせていただいたり、提言もさせていただいている部分がある。先ほど来、軸索の話もあって、簡単に言うと、診断基準もわからなければ、どうなっちゃうのか、今、判断も非常に難しい、推測ばっかりで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほども、一定の意見みたいになりましたけれども、特に１点目の、区民への啓発・周知は、やっぱり軽度外傷性脳損傷に至る原因というのは、私たちの生活のあらゆる場面で、交通事故も含めてあるということは、わからないままになってしまうので、多くの区民の方々には、やっぱり理解をしていただいて、またそういう方向にご自身が自覚をするということは、大きな違いがあるので、国の取り組み。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"請願の趣旨はわかりますので、採択ということでお願いしたいんですが、とにかく行政には、適切に対応していただきたいということを、ちょっとつけ加えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"},{"speaker":"中塚副委員長","kind":"意見","question":"ＭＴＢＩの原因や仕組みについて、まだまだ不明な点はあるものの、症状によって、実際の生活に困難が生まれている、また悩みや苦しみが生まれている、そこをしっかり見て、理解を広げていく周知の取り組み、また支給の対象や支援の仕組みをつくっていく必要があると思いますので、意見書を出すことも含めて、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-018"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"ひとり暮らし高齢者、高齢者のみ世帯の定義なんですけれども、それぞれの事業で、ひとり暮らし高齢者、高齢者のみ世帯を対象にしておりますけれども、小さい米印で、居住地の周囲５００ｍ以内に云々とありますけれども、このひとり暮らし高齢者、高齢者のみ世帯の定義に合わなければ、全ての事業が対象にならないという関係にあるのか、どうか、そこの状況を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"民生委員のほうの調査ですけれども、本人が６３歳でも、民生委員にかかわってほしいという方がいれば、７０歳以上だから、あるいは６５歳以上だからということでやっているわけではなく、申し出があれば、それぞれ対応するという形にしています。","voiceIndex":66,"id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それぞれの事業内容のところで、緊急システムであったり、徘徊高齢者探索システムであったり、ひとり暮らし高齢者、または高齢者のみ世帯という対象になっておりますが、居住地の周囲５００ｍ以内に云々の規定は、対象にする、しないとはかかわらないということでよろしいのか、確認したいと思います。それからもう１点、具体的に日常生活用具等給付事業ですけれども、自動消火装置について、伺いたいんです。","respondent":"原高齢者福祉課長","answer":"自動消火装置のところで、認知症の方です。確かにいろいろな状況の中で、さまざまな形はあろうかと思いますけれども、こちらのほうは、昭和５５年から実施をしておる事業です。","voiceIndex":68,"id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"とりわけ、防災上の視点からも、今日的に充実が求められているときだから、対象を認知症高齢者のみにするのではなく、障害者や要介護認定の高齢者や、そうした生活実態に目を向けて、ここは対象を広げていくこと、その検討をいよいよ始めていくときではないかと思うんですけれども、そういった検討は、現在どういう状況なのか、改めて伺いたいと思います。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"そういった中で、区におきましても、これは認知症ということではなく、火災報知機を高齢者の中に積極的に設置をしてほしいということで、当時、制度的には終わったところを、延長をして。年齢とかに関係なく、身体障害者の手帳１から３級、愛の手帳１から３度、精神障害者保健福祉手帳が１、２級の方で、障害者のみの世帯ということで、同じような支給をしています。","voiceIndex":70,"id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"障害者のほうが対象になっていることはわかりました。高齢者のほうですけれども、火災警報器を義務化したことは知っています。そうではなくて、自動消火装置の対象を、認知症高齢者のみにするのではなく、要介護認定だったり、例えば、認定は出ていなくても、ひとり暮らしの方だったり、やはり対象拡大を検討すべきだと思うんですけれども、そこについてご説明いただきたいと思います。","respondent":"原高齢者福祉課長","answer":"平成２４年度の事務事業評価といったところでも、安否確認系等々についても継続して検討していくという取り組みになってありますので、トータルの中で捉えていきたいと思っているところです。","voiceIndex":73,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"緊急通報システムで、消防庁への通報で、協力員が駆けつけますというので、なかなか今、地域の協力員が見つからないというお話だったんですが、もうちょっと詳細に、どういう仕組みなのかお伺いしたいんです。消防庁に通報するのは誰なのかということと、協力員がそれに応じて駆けつけたところで、具体的にどのようなことを協力員に求めているのかということで、お伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"それでも、本人が認知症であったりしますと、成年後見のほうにつなげて、本人にかわっての対応をやってもらうということで、それぞれその人の状況に応じた取り組みを、民生委員をはじめ、在宅介護支援センター。","voiceIndex":75,"id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"今のご説明でいくと、消防庁型から民間型へどんどん移行していくというような考え方を持っていらっしゃるのかなということで、消防庁型の総数がだんだん減っていって、これは切り換えも行われているということでよろしいですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えてください。在宅支援を求めている方はどんどん増えていくということを考えると、考え方として、こういうものは、全部やっぱり補助金ありきというところで、国からもいろいろ在宅支援のメニューが出てきた、こういう形の中のものを、区としてもやっていくという考え方なのか。もちろん違うものもあるので、そこら辺の度合を、どう考えていらっしゃるのか教えてください。","respondent":"原高齢者福祉課長","answer":"高齢者施策を進めるうえでの今後の区の考え方ですけれども、補助金というのは、事務をやるうえで大変重要な要素ですし、そういった中で、補助金がなければやらない、あるからやるということではなくて、やはり目的があって、高齢者の地域の安全。","voiceIndex":78,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５００ｍというのは、区の基準なんですね。それから、考え方として、何分ぐらいというのがあるじゃないですか。今、ないということであれば、横串の部分を、ぜひそれもあるのか教えていただきたい。そういう場合のフォローというのは、どういうふうにされているのかなということを、もう一度改めて伺いたい。ここら辺の、具体的に動きをかけているものがあれば、ちょっと教えてほしいと思うんです。","respondent":"原高齢者福祉課長","answer":"これはさまざまその人の状況で変わってきますので、そういった中で、区民の皆様に影響がないように、個々に対応していくことが基本ということで捉えているところです。それから、補助金の関係ですけれども、委員ご指摘のとおり、大きく三つの考え方と、私どもも理解しております。","voiceIndex":80,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"多分、行政側は、国も必ずそういうふうに思っているわけじゃないですか、施設より在宅でお願いしますと。区が行政としてこれをやる部分も、もうちょっと整理をして、さっきの民間の通報システムじゃないけれども、民間でやっていただく部分、それでもちゃんとこういうふうにしていくという筋道ぐらいは、やっぱり立ててほしいというのが、私の思いで、何かお考えがあれば聞きたい。","respondent":"原高齢者福祉課長","answer":"一つの基準として、一人世帯というものをどういうふうに捉えるかと、民生委員が、どういうふうにかかわっていく対象者を見出すか、当然、先ほど来お話ししていただきましたように、ここらか外れても、例えば５００ｍ以内に親族がいても、私は心配だということであれば。","voiceIndex":82,"id":"exchange-027"},{"speaker":"渡辺委員長","kind":"質問","question":"私のほうから、今定例会の一般質問に係わる所管質問について、ご案内申し上げます。本件は、委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問に係わる当該委員会の所管質問を行うものです。質問をなさりたい委員がいらっしゃいましたら、この場で通告し、翌日、理事者に答弁していただくことになります。本会議での質問の繰り返しにならないようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":29745,"voices":88}},{"id":"h24-20121126-8","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"建設委員会","time":"午前１０時００分～午後４時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７５号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第７５号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"借上型区民住宅が契約が切れて廃止となるということなんですけれども、これからの区の方針として、借上型区民住宅、今、２９８戸あると思うんですけれども、２０年の契約期間が切れたら、これからどんどんすべて廃止という、そういう区の方針なのかということを１点お聞きしたいのと、契約が切れて廃止となるというのは今回が初めてなのか、その２点を初めに教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"最初の質問です。２０年の契約満了、これはオーナーの方とのお約束で２０年の契約ということで借上げをしています。したがいまして、この２０年の契約、これが順次来ましたときには、順次これはオーナーのもとに返還をしていくという方針で今後についても進めていく方向です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回廃止となるパレスガル以外のところの入居率というのは、全体の空室率というのは９月の委員会で３３.２％ということでご答弁いただいていますけれども、このパレスガル以外の入居率というのが、入居率の高い借上型区民住宅というのがあるのかどうなのか、そこら辺のところも教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"１点目です。先ほどご答弁しましたように、今後とも２０年の契約満了に伴って借上げ住宅についてはオーナーのもとに返還していくという方針に変わりはございません。それから、現在、パレスガルにつきましては、委員からもあったように、１８戸借り上げております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"家賃助成もあるということで、今回のパレスガルについては、利用率もずっと長い間、低い利用率でありますし、また、オーナーの方も今回で契約打ち切りということで、区ともそういうふうになっているということで、今回のパレスガルの廃止ということに対しては、それでいいというふうに思うんですけれども、今後については、私はこの利用率の高い区民に望まれる区民住宅というのは、ぜひとも。","respondent":"大串住宅担当課長","answer":"それから二十数年たちまして、今現在、そういう状況ではなくなっているといったところで、借上型区民住宅については、役割としては全うしたのかなというふうに考えているところですので、この２０年の満了とともに。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"若い人たちの雇用の条件というのも随分変わってきていますので、そういうところでは、区が果たす役割として、公的な住まいの提供というところで、これからの借上型住宅は、一律に期限が切れたら廃止ということではなくて、私はぜひとも若い人たちが定住できるような、そういうところで検討していただきたいということで要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"原副委員長","kind":"質問","question":"私のほうは、やはり今、須藤委員からもお話があったように、いろいろな決算特別委員会にしても、そういうときもやっぱり毎回出てくるような問題があって、どうも、これは最終的に契約解除すれば、今度は民間オーナーと入居者との間の関係になると思うんですけれども、ですから、今回、中途議決ということなんですけれども、多分それは契約の期間の問題なのかどうか、その辺についてちょっと教えてください。","respondent":"大串住宅担当課長","answer":"契約満了の期間といたしましては、平成２４年１１月３０日が契約満了日でございまして、こちらの契約にのっとった形で解除ということになりますので、１１月中の議決をお願いしたいというところで先ほどご説明させていただいたところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"原副委員長","kind":"質問","question":"これでスタートですので、あと、今後いろいろ続くと思いますので、区の立場としては、かっきりはっきりやっていくと、これが誤解のないようにすっきりやって、ですからもう、非常にこのやり方としては私は大賛成ですので、今後もよろしくお願い申し上げますということで、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"第７６号議案、品川区手数料条例の一部を改正する条例","agenda":"第７６号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"今回、このような手数料条例の一部を改正する条例ということで、この低炭素建築物の認定制度ですが、あまり私も認識していなかったんですが、既にこの制度を認定するという、そういう組織というんでしょうか、品川区としての体制、公布の日から施行になっていますけれども、計画があって対応できるようになっているのかどうか、この点について教えてください。","respondent":"中村建築課長、野呂瀬環境課長","answer":"そちらのほうの職員で対応するということで既に体制のほうは準備が整っております。品川区地球温暖化対策地域推進計画の中でも、５つの重点取り組みがあるんですけれども、低炭素型のまちづくりの実現に向けてと、こういう項目がありまして、区民、事業者の役割、区の役割、それぞれ決まっていまして。","voiceIndex":29,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"今、地域推進計画のお話をいただきましたけれども、これ、自治体によっては、低炭素まちづくり計画というんでしょうか、そういうものを策定してということで、今回の対応をしていくような文言もいろいろ調べると出てきたんですけれども、これは今、答弁いただいた地域推進計画の中にそういう計画はもう既に含まれているというような考え方でよろしいのかどうかお伺いします。","respondent":"野呂瀬環境課長","answer":"はい、委員おっしゃったとおりでございまして、低炭素まちづくり計画、こういう決まった計画はございませんけれども、地域推進計画の中で低炭素社会の構築を目指していく、このようにうたっているものです。","voiceIndex":32,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"そうしますと、例えば、今回の基本的項目ですとか、選択的項目とか、これ、パッと見ただけではなかなかわかる部分とわからない部分があるんですけれども、区民の皆様には、何か特別な形でこういう制度があるよということで、ある意味、積極的に低炭素化に取り組んでくださいよというようなアピールというんでしょうか、そういう広報は今後考えられているのかどうか教えてください。","respondent":"中村建築課長","answer":"そういった中で計画の段階で事前にお知らせするとともに、あとは、今、品川区内で建築士事務所協会、あるいは日本建築家協会等ありますので、そういった協会にも設計者に対してこういった法律があるというのはお知らせをしていきたいと思うんですけれども、ただ。","voiceIndex":34,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"手数料の金額があるんですけれども、これが適正かどうかということについては、なかなか私も理解できないところがあるんですけれども、例えば、ほかの自治体ですとか、「都市における」ですから都市に限っているのでしょうけれども、ほかの自治体の動向などで、この金額が妥当なレベルなのかどうかということについて調査した結果があれば教えてください。","respondent":"中村建築課長","answer":"ただ、この算定に際しましては、新しい法律の制度ということと、それから、具体的な認定の基準がこれから示されるということで、先が見えていないところもあるんですけれども、今まで国土交通省などの説明に基づいて想定した計算をすると。","voiceIndex":36,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この手続の仕方なんですけれども、これは設計の段階からこういうところで建てていきますよということで認定を取っていくという、そういうことになるんでしょうか。こういう家にもう既に住んでいるということで手続をしてこれが受けられるという、そういうことはないのか、そのことをお聞きします。","respondent":"中村建築課長","answer":"この認定の基準ですけれども、従来の一般的に建てられている建物に比べれば、かなり環境性能が高いものということになっておりまして、今の現行法、建築基準法に基づいて単に建てるだけでは、やはり認定の基準は満たさないということで、既存の建物につきましては。","voiceIndex":38,"id":"exchange-012"}]},{"id":"topic-03","title":"第７７号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第７７号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、目黒駅前のところなんですけれども、地権者が、これは平成２２年度のときの議事録を読んでいましたら、そのところでは１１人というふうなことで言われていたんですけれども、今年の７月に聞いたときには２４人ということで答弁があったんですけれども、ここがちょっと違っていたので、そのところが実際にどういうふうな状況なのか、地権者の中身も含めて教えていただきたいと思います。","respondent":"中村建築課長、溝口都市開発課長","answer":"ですので、この建築確認申請に先立ちまして、条例のほうを制定するものです。現在、組合が設立しておりまして、組合設立時の権利者の状況として７月にお答えしています。土地の所有者が２４人、借地権については５人ということです。権利者につきましては、現在のところ２４人というのが正しい数字です。","voiceIndex":51,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都市計画審議会が平成２２年に終わっていて、確認までこれだけの期間があるという、そこら辺の理由があったら教えていただきたいと思います。","respondent":"中村建築課長、溝口都市開発課長","answer":"確認申請を含めました建築のスケジュールにつきましては、区のほうでは全く把握していないということではなくて、常時把握していますので、その辺につきましては、スケジュールどおりというふうにお伺いいたしております。ただ、当開発につきましては、東京都の権利関係以外で、今回開発することによっての受益ということで、保育園ですとか、サービスコーナーですとか、そういった公共的なサービスを入れていくというふうに計画しておりますので。","voiceIndex":54,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと今の説明でよくわからないんですけれども、東京都が土地の権利を５３％持っているということで、その５３％の権利変換を東京都がしていくということなんですけれども、あれは民間がやる保育園ですよね、それから、東京都の何か施設をつくるとか、そういうところというのは、その中には今のところあるともあまり思えないんですけれども、その東京都が権利変換をしていくというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ただ、地区計画というのは、その建物が建てられるための計画を決めるというふうなところなので、その建物がどういう建物になっていくのかということがわからないと、ちょっとあれだなと思っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までそういう東京都がマンションをつくって、マンションを権利変換で持って、それを貸し出すみたいな、そういうふうなこともあり得るということですか。そういうふうなことが今まで例としてあったんでしょうか、そこら辺のところを教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"基本的には防風林をつくるとか、そういったもので対応していき、また、建物の形状等も主に外側、外壁等のことになるとは思いますが、風環境が悪くならないような対策をしていくというふうに考えているところです。","voiceIndex":63,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、改めて地域の方から、区長宛てにも要望書をずっと何度も出しているということでお聞きして、今年に入ってからも８月に要望書を出して、なかなかそういう風環境を改善するという対策がとられないということに対して、地域の方はかなり心配をされているわけなんですけれども、建物の形状も変わらないし、ひさしをつけるというふうなところも具体化されていないし、植栽というふうなところだけ。","respondent":"溝口都市開発課長","answer":"風対策につきましては、現在、詳細設計を進めていく中で十分検討しながら進めていきたいというふうに考えておりますので、それにつきましては、引き続き、周辺環境に風の悪影響を及ぼさないような対策を講じるように指導していきたいというふうに考えております。","voiceIndex":65,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"西品川一丁目地区のほうをお聞きしたいんですけれども、この計画のところでは、工場等で作業場の床面積が１５０平方メートルを超えるものというのは用途制限にかかっているわけなんですけれども、今回この西品川一丁目地区には、地域内で操業されている工場が１１社１７棟あるということで、このマンションのほうに工場が入るということでお聞きしていますけれども、この工場というのは。","respondent":"溝口都市開発課長","answer":"今回、条例で定めます用途制限の中身の中で、まずＡ地区につきましては、基本的に業務を考えているというお話をいただいています。Ｂ地区につきましては、共同住宅、工場、従前の権利者たちの再建を目的とした建物を考えているところです。","voiceIndex":67,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、１階と地下を工場にするというふうな方向で動いているというふうには聞いたんですけれども、そこら辺のところも、これから工場、今操業している１１社１７棟、そのところがここに残るかどうかというふうな話し合いの中で、そこのところは地下だけになるのか、１階も含むのか、そういうふうなところが決まっていくという、そういう考え方になるのでしょうか。","respondent":"溝口都市開発課長","answer":"今現在の建築計画ですと、主に地下と１階等の低層部に持っていくという形で考えておりますが、最終的には権利者の方たちがどのような形で残りたいのか、それに対応した形での建築計画を今後立てていくという形になります。","voiceIndex":69,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、そこに住まわれる方にとっては、下に工場があるというのは、ちょっとどうなのかという、そういう意見もあるということと、それから、工場に入る方にとっては、今までの操業というふうなところがそこのところでは十分にできないというふうなところで、なかなか理解が得られないというふうなところもお聞きしているんですけれども、そこら辺のところは。","respondent":"溝口都市開発課長","answer":"詳細につきましては、先ほど来述べておりますように、今後の権利変換計画等の中で決まっていくことになりますので、また低層部に工場を入れるに際して。","voiceIndex":71,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"目黒駅前地区のところでは、アセスメントがかかって、そのところに補助金と事業費というのが出ていたんですけれども、そういう点では、ここも目黒駅前地区よりもかなり大きなあれなので、アセスメントももちろんかかったと思うんですけれども、そういう点では、目黒駅前地区ではそういうふうに出ているのに、なぜここでは出ていないのか、もう計画がここまで来ているのに。","respondent":"溝口都市開発課長","answer":"事業費の考え方です。市街地再開発事業の中では、あくまでも組合設立時に初めて事業認可を取得するような形になりますので、そこで初めて全体事業費が出て、またその中には国庫補助金等をどのぐらい使うのか、どのぐらい充当するのかというのが初めて明らかになってくるものです。","voiceIndex":73,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はやっぱり、この計画を決定していく都市計画審議会のところでも、やっぱり税金をどれぐらい出してこの開発を進めていくのか、総事業費に対してどれぐらいなのかというふうなところは、当然私たちの税金が投入されていくわけですから、そういうのは全くわかりませんという中で決定するということは、私はあり得ないんじゃないかなと思うんです。","respondent":"溝口都市開発課長","answer":"事業費につきましては、ある程度、一定の手続を踏まえた中で、また都市計画が決まった中で、そういった制限等の中でどういったものが建てられるのか、そういったものを十分検討しながら初めて事業費が算出されるものと考えておりますので。","voiceIndex":75,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"反対です。しかも、地域の方からは、全く風環境が改善されていないということで何回にもわたる要望書、それから話し合いが進められているにもかかわらず改善されていない、こういう建物を建てるということになるための今回の条例ですので、賛成はできません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-024"}]},{"id":"topic-04","title":"第７８号議案、品川区対象区域における特定工場の緑地面積率等に関する条例","agenda":"第７８号議案、品川区対象区域における特定工場の緑地面積率等に関する条例","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"第１条に昭和３４年法律第２４号と出ているんですけれども、工場立地法というものができたときから、東京都だったと思うんですけれども、この緑地面積率等に関する条例というのは、そのときからもう存在していたのかどうか、その点をお伺いしたいのと、あと、そのまま今までの都の流れを継続するということになっていますけれども、例えば、工業地帯は１０％から２５％ということで。","respondent":"野呂瀬環境課長","answer":"それと２点目ですけれども、あえて東京都の考えを一歩進めてということですけれども、これにつきましては、今申し上げたとおり、昭和４９年以降、区内においてこの特定工場に適用されるようなものが存在しないというようなことも含めて、もう１つは。","voiceIndex":89,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"今ご答弁いただいた中で、１年間は都のルールを準用するということなんですけれども、そうすると、２年目以降については、例えば緑地をもっと増やそうということで、相手があることですから簡単にというわけにはいかないと思うんですけれども、そういうことは可能になるということなのか、可能だったらさらに進める気持ちとか、そういうものはあるのかどうか、この点について教えてください。","respondent":"野呂瀬環境課長","answer":"東京都が工場立地法の適用よりも基準を緩和させた理由なんですけれども、都心部において条件がいろいろ違ってきまして、ほかの県のように工場立地法を適用すると、やっぱり工場の流出を招くだとか、さまざまなそういう条件がありまして。","voiceIndex":91,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この工場立地法で、ここのところに緑地をどれぐらい設けなければいけないかというふうなところで定められる工場というのは、どれぐらいの広さが対象になるのか、そして品川区でこの条例の対象になっている工場は幾つぐらいあって、どういうところなのかというところを教えていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"２点目が、敷地面積が９,０００平方メートル以上、または建物の建築面積が３,０００平方メートル以上のものということで、いわゆる相当大きなところということです。２点目、どれぐらいあるのかというと、昭和４９年以降はこれぐらい大きなところはありません。","voiceIndex":93,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"工場立地法よりも東京都は緑地面積を緩和させているということなんですけれども、工場立地法よりもどれぐらい緩和させているのかということと、それから、今回、区の条例になることで、区独自に基準というのは緩和することも、これから引き上げることも可能だということになっていくのか、昭和４９年以降、こういう特定工場の対象はないということなので。","respondent":"野呂瀬環境課長","answer":"それと、今後こういうような工場が設置されるのかというお尋ねですけれども、昭和４９年以降ありませんということもありまして、多分可能性としてはないだろうというふうな考えでおります。","voiceIndex":95,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都のそのまま横引きということなので、可能性としては多分本当に低い、そんなに大きな工場が新たにできるということはあまりないかとは思うんですけれども、もしもそういうふうなことがあれば、ぜひ緑地を増やすということも視野に入れて検討を、品川区独自にその基準を変えていけるということであれば、そういうことも検討はしていただきたいなというふうには思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-029"}]},{"id":"topic-05","title":"第７９号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"第７９号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回、５年目の値上げという提案ですけれども、特に家庭ごみに関しては、その前、４年前も値上げしていないということであれば、９年目の値上げということになるんだと思うんですけれども、この３年目に見直しを検討して、４年ルール、４年ごとに値上げを検討するということで区長会で決定したということなんですけれども、この４年ごとというのは、なぜ４年ごとというふうなものが出てきたのか。","respondent":"太田品川区清掃事務所長","answer":"１点目ですけれども、４年という考え方ですけれども、先ほどご説明しましたように、東京都時代の平成６年７月に改定をして以来、平成２０年４月まで１４年近く改定がなされていなかった、こういうことです。","voiceIndex":109,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ごみは本当にどうやったらもっと減量できるかというふうなところは、取り組みを進めていくことが本当に大事だなというふうに思っているんですけれども、特に私、事業系のところが、４５リットルの袋で出している商店とかが多いんじゃないかなと思うんですけれども、ごみの収集前日にずっと商店街を回ったんですけれども、商店街の方々に聞いても、本当に今ぎりぎりで。","respondent":"太田品川区清掃事務所長","answer":"そういう意味でいけば、皆さんには、これから区のほうも十分周知をしていく予定ですけれども、あわせてごみの減量、これに取り組んでいただくこと、これがさらに必要ではないかというふうに考えているところです。","voiceIndex":111,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところの考え方と、それともう１つは、ここで事業系ごみを区が直接収集するのと、許可業者、それから事業系ごみの直接持込み分というのがありますけれども、ここら辺のこの３パターンの割合、ごみの量の割合がどれぐらいになっているのかというのがわかったら教えていただきたい。","respondent":"太田品川区清掃事務所長","answer":"６ページの事業系ごみの配分については、申しわけございませんけれども、私どものほうでは正確な数字としての把握はできておりません。","voiceIndex":113,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"１つお伺いしたいんですけれども、先ほどの見方を変えればごみを減らす、エコにもつながるというお話がありましたが、不法投棄に対するお考えを聞きしたいのと、それから、切り替えになったときの区民に対する詳しい周知の仕方と、現在持っているものは１０月中に使えというお話しなんですけれども、そうなると、期間的にちょっと短いんじゃないかと思いますが。","respondent":"太田品川区清掃事務所長","answer":"１１月以降についてですけれども、これは今、差額交換、旧券と新券の差額交換、差額を納付していただくことによって新券に換えていく、こういうことも考えているところです。","voiceIndex":115,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"よくわかりました。不法投棄に関して、ちょっと突っ込ませていただきたいんですけれども、これから先、値段が上がることによって、それは望ましくないんですけれども、増える可能性もあるのではないかなという懸念があるんですが、その辺のお考えも、いかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"しかしながら、私ども、資源の抜き取り防止のパトロール隊も早朝から出ていますし、それから、こまめにそういうご相談があったときに地域のほうへ出向いていって、周りの方のお話を聞きながら、できることと言えば、看板を設置するなりということで対応させていただいています。","voiceIndex":117,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。そういうところで、小さなところに大きな負担になっていくごみの値上げに対しては反対ということで態度表明をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-035"}]},{"id":"topic-06","title":"第８５号議案、専決処分の承認を求めること","agenda":"第８５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本人に損害金の支払を求めるというのは、１２６万円ということなんですけれども、この方の状況をちょっと教えていただきたいんですが、いつからこの区民住宅に住んでいるのかということと、いつから払えなくなったのか、そしてまた、なぜ払えなくなったのか、その理由についてもお聞かせいただきたいと思います。","respondent":"大串住宅担当課長","answer":"こちらに数字として挙げております１２６万円というのが滞納の使用料になります。こちらの方が居住になっているのは、先ほどご説明させていただきましたが、平成１６年５月から居住しております。支払が滞るようになったのが平成２３年１月ごろからです。","voiceIndex":130,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"東急コミュニティーが四、五回訪問したり、電話で督促をするということなんですけれども、こういう場合は、区としてはどういうふうにこの方に対してかかわっていくのか、そこら辺のところをお聞かせください。","respondent":"大串住宅担当課長","answer":"区のかかわりです。こちらにつきましては、東急コミュニティーが指定管理者として対応しておるところです。一義的にはこの方の滞納関係については、すべて東急コミュニティーのほうで対応を行っている。","voiceIndex":132,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが仕事の関係で収入が減ってしまったということでこういう状況になったということだと思うんですけれども、それに合わせた生活にどうやって切りかえていくかというところでの相談というか、そういうふうなものはすべて東急コミュニティーで、区のほうは最終的にこの方に対して裁判にどう訴えていくかというふうな話し合いのところまで応じない、かかわらないというのではなくて。","respondent":"大串住宅担当課長","answer":"ご本人のほうからご相談等々あれば、こちらのほうとしても対応はしますが、残念ながらこちらの方から区のほうに直接ご相談といったことは、この方に関してはございませんでした。","voiceIndex":134,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これはもう専決処分ということなので反対するものではないんですけれども、私はこういう場合も、もうちょっと区が相談に応じながらかかわっていけば、もっと早い段階でこの人の生活も何とかできていけるというようなところでの、相談に乗って進めていくということができないものかなというふうな思いでいますので、ぜひそこら辺のところは今後に向けてご検討いただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-039"},{"speaker":"須藤委員","kind":"質問","question":"このぐらい待っていないとこういう訴えをできないよとなってしまうのかな。東急コミュニティーと連携をとって、こんな事例があるんだ、じゃあ、それは次のステップに移ろうとかという仕組みがどういうふうになっているのか教えてください。","respondent":"大串住宅担当課長","answer":"以下その繰り返しという形になりますけれども、２カ月目以降、なかなか納付がないといった場合には、指定管理者の電話や訪問による直接的な納付催告、この段階から必要に応じて保証人も含めた対応をお願いしているという流れです。","voiceIndex":137,"id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"順序を踏んでいかなければなかなか難しいというのはわかるんだけれども、その順序の踏み方がもう少しスピードアップしてもいいんじゃないかなというような思いがちょっとしているので、払うほうも払えませんという状況になっているんだから、早めにその手順を進めてやったほうが、払うほうも、連帯保証人だって、あまり数字が大きくなってしまえば保証できないよという話になってきてしまうだろうし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-041"},{"speaker":"原副委員長","kind":"質問","question":"だけれども、実際には区としてはやっぱり皆さんからいただいている税金をこういうふうな形で、最終的に何年かたったときにとれませんでした、なかなかこういうケースはとれない。ですから、それであれば、しっかりと指定管理者に持たせると、区は実際には被害を被らないと、その辺まで考えていただければと思いますけれども、その辺、担当課長として、一言だけで結構なので。","respondent":"大串住宅担当課長","answer":"ただ、その中で滞納に対しての指定管理者のほうの負担というような流れになるかと思うんですけれども、なかなかその辺は難しい問題も含んでいるのかなというふうに考えているところです。ご指摘いただいたことにつきましては、今後検討していきたいというふうに考えております。","voiceIndex":140,"id":"exchange-042"},{"speaker":"原副委員長","kind":"質問・要望","question":"非常によくわかります。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-043"}]},{"id":"topic-07","title":"第８６号議案、指定管理者の指定","agenda":"第８６号議案、指定管理者の指定","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"先ほどの件に絡んでくるんだけれども、管理について、ここが管理したところがそういうような形になってしまったわけで、そういうことを今度、面接だなんだということできちんとお話が、先ほど言った前へ進むような仕組みづくりができているのか、それはまだ何もその辺の話は出ていないのか、今後こういうことが起きないような形をしっかりとっておかないと困ると思うので。","respondent":"大串住宅担当課長","answer":"そのことに関しましては、東急コミュニティーのほうとも、まずは滞納が少ない段階、先ほど申し上げました１カ月目に督促状というお話をさせていただきましたけれども、そういったまず少ない段階できめの細かい対応をしていただくといったところで。","voiceIndex":154,"id":"exchange-044"},{"speaker":"木村委員","kind":"質問","question":"今回この指定管理者の申請者は１社ということなんですけれども、どうして１社しか来ないのか、前回などはどのような状況であったのか教えてください。","respondent":"大串住宅担当課長","answer":"今回の指定管理です。こちら、先ほどご説明しましたが、７月２３日から公募を行いました。その時点では、東急コミュニティーを含めて５社の問い合わせはありました。","voiceIndex":156,"id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"５社あったということなんですけれども、本当に東急コミュニティー１社独占というか、そういうふうになりますけれども、しっかりと行政側としては、この指定管理者がちゃんとできているかどうかということ、この文章の中にも「豊富な住宅管理実績」とありますけれども、チェックをちゃんとしているのかどうか、それがもしあれば教えてください。","respondent":"大串住宅担当課長","answer":"そういった意味で、今年よりも来年、来年よりも再来年、年々よくなるような形で私どものほうでも指定管理者を指導していますし、また、指定管理者のほうもそういった形で区の期待にこたえていただけるよう努力をしていただいているというふうに我々としては考えているところです。","voiceIndex":158,"id":"exchange-046"},{"speaker":"木村委員","kind":"意見","question":"将来的にそういう考えがあるかどうか、競争させることを、そういうふうにして、確かにおりてしまった場合には仕方ないんですけれども、何かそのような形で、１社ではなく、競争させるような方法について何かお考えがあればお聞かせください。","respondent":"大串住宅担当課長","answer":"委員おっしゃるとおりでございまして、競争原理を働かせるというところで当方としても考えているところです。そうしたことを踏まえまして、こちらの区民住宅の指定管理者につきましては、常に公募という形で行っております。","voiceIndex":160,"id":"exchange-047"},{"speaker":"浅野委員","kind":"提案","question":"今回、東急コミュニティーに決定したということですけれども、継続という形になったわけですが、これまでのサービスに比べて、何かこういう向上をさせるよとか、そういう前向きの提案というのがあったのかどうかということと、あと、いろいろ論議をされた中に、退去してから入居するまでの平均日数ということで、前回の９月２５日のときにも報告があったんですけれども、少しずつは改善されていますけれども。","respondent":"大串住宅担当課長","answer":"２点ご質問をいただきました。東急コミュニティーのアピールポイントですが、先ほど、冒頭説明の中でもありましたように、コミュニティー形成支援、こちらを重点目標とするです。","voiceIndex":162,"id":"exchange-048"},{"speaker":"浅野委員","kind":"意見","question":"この退去から入居までの日数は、ほかに比べて長いという、そういうふうにも言われておりますので、さらに指定管理者のほうと打ち合わせをしながら、いい方法を見つけていっていただければと思います。先ほどの中で、一体化のメリットで２,０００万円から３,０００万円経費が削減されたということなんですが、金額としてはどのぐらいのレベルになったのかなというところでちょっと。","respondent":"大串住宅担当課長","answer":"維持管理、修繕の関係ですとか、そういったところでのコスト縮減、こういったものが一番大きいのかなというふうに考えておりますし、先ほど申し上げましたような一体的な管理ということ、東館、西館それぞれ。","voiceIndex":164,"id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"今の浅野委員の質問で気になったことがあったんですけれども、今、一体化して、２,０００万円ぐらい削減できたということは、今後また５年後というか、４年後に半分側の指定管理の終わるときが来ると思うんですけれども、そのときはまた指定管理の選定ということでするということがあるのかということと、そうなったら一体的にそのときにまとめてもう一度改めて指定管理ということを考えられるのか。","respondent":"大串住宅担当課長","answer":"こちらは先ほど申し上げましたように、東館と西館、どうしても１年間のずれが出てまいりますので、来年の東館の指定管理者、こちらの指定期間につきましては、１年短縮しまして４年、そうしますと。","voiceIndex":167,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は東急コミュニティーしか応募がなかったということなんですけれども、これは今までと応募期間ですとか、公募の周知とか、やり方というのは全く同じであるにもかかわらず、東急１社しか公募がなかったということなんでしょうか。その点、やり方の面で教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"５年前と全く同様の形で公募活動はやらせていただきました。","voiceIndex":169,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、この先もほかのところからの応募というのは出てこないということも可能性としてはあるということになってしまうのかなと思うんですけれども、そこら辺のところは、なぜそういうふうな公募というふうな形でとったにもかかわらず来ないのかというのは、区としてはどう、わからないというだけで、考えられていることというのはないのでしょうか。","respondent":"大串住宅担当課長","answer":"ただし、その条件を緩和するということは、入居者へのサービスの低下につながりますので、そういったことは考えてございません。次回公募の期間で何社来るかというのは非常に難しいところですが、基本的に今のやり方を変えるというふうには考えておりません。","voiceIndex":171,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどもありました退去から入居までの平均日数というのが、昨年に比べても多いんですけれども、退去してから約４カ月ぐらい入らないという、そういうのは本来であればどれくらいが望ましいというのがあるのか、そしてなぜこんなに４カ月も入らないという状況なのか、そこの点についてお聞かせいただきたい。","respondent":"大串住宅担当課長","answer":"先ほどの専決処分で承認いただいたような形で、なかなか退去に時間がかかるといったケースも出てまいりますので、そういったところで平均日数としてはこういった日数が出てまいりますけれども、その辺につきましても迅速にやっていただくよう。","voiceIndex":173,"id":"exchange-053"},{"speaker":"原副委員長","kind":"質問・要望","question":"先ほどの件と重なります。意見だけなので、これは聞いていただければと思います。さっきも言ったように、指定管理者ですから、インセンティブがついていますので、ですから、プラスもあればマイナスもあるということですので、まず裁判しても経済弱者ならぬ社会弱者であれば、これはなかなか区が訴えたとしても勝てる見込みは薄いですから、しっかりその辺のところを含めて、指定管理者を募集する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"やっぱり区民住宅というところでは、先ほど専決処分もありましたけれども、本当に収入から家庭の状況、仕事がなくなってどんなに大変なのか、そういうふうなところも、極めてプライバシーがすべてわかるというふうなところを株式会社に任せるということがいかがということと、やっぱりそういうふうなときに、区が親身になって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-055"}]},{"id":"topic-08","title":"第８７号議案、東京二十三区清掃協議会規約の変更","agenda":"第８７号議案、東京二十三区清掃協議会規約の変更","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"今度、逆行するように、各区独立でというのではなくて、今度は連携をとっていきましょうと、最初のスタートのときは各区独自で実施を出しましょうということの自治権拡充として清掃事業というのは各区に入ってきたという経緯があるんだけれども、そのあたりの経緯で、今聞いていると、品川区だけがこういう方向性を出しているけれども。","respondent":"太田品川区清掃事務所長","answer":"しかしながら、私どもは、平成１２年の経緯、平成１８年の経緯、これらの議会の意向、区民の意向、それからひるがえって言えば、もともと昭和４７年の準公選という、そういう品川区としての歴史的な経緯があることを承知していますので、やっぱり法の趣旨どおり。","voiceIndex":187,"id":"exchange-056"},{"speaker":"須藤委員","kind":"意見","question":"この清掃協議会で審査して許可を出しますよ、この６００幾つの業者があって、区の許可が出ているのは１６５社、この人たちは、当然、品川区に入っていない業者だって数あると思うんだけれども、その方々も品川区でも、今度、２３区の許可をとれるよというのが、清掃協議会へ１回行けばすぐとれちゃうよという話になってしまうのかなと思うんだけれども、そうすると。","respondent":"太田品川区清掃事務所長","answer":"そのうちのほとんど９８％が２年の更新許可、あるいは排出場所が増えたとか減ったとか、車を買い替えたとか、事細かくこの許可事務に当たっては変更をすることになっている、法律の規制が大変厳しいといいますか、きめ細かな要件になっていますので。","voiceIndex":189,"id":"exchange-057"},{"speaker":"須藤委員","kind":"意見","question":"よく議長が、前に議運にいたときなんかに議長会の報告で、清掃一部事務組合で産業廃棄物処理業者が、いわゆるお金を払わないでまだそのまま来てしまっているよというような、何とかという数字があって、それきりないんだとかという、今でさえそういう状況になっていて、また責任がどうのなんていくと、そういう数字がさっきのマンション、アパートの管理ではないけれども。","respondent":"太田品川区清掃事務所長","answer":"委員ご心配いただいている許可事務が形骸化というか、弱くなるんじゃないかですが、この点については、今、８名の増の見込みということになってありますが、これはおそらく各区のほうから職員を派遣して、そういう事務を担っていた職員がおそらく清掃協議会へ行って。","voiceIndex":191,"id":"exchange-058"},{"speaker":"浅野委員","kind":"質問","question":"今年の初めですが、１月とか２月に中間まとめがあって、そこで了承されなかったという説明が先ほどあったかと思いますが、それが６月に行われた臨時部長会で承認されたということに変わったというんでしょうか、そのように聞こえたんですけれども、ここでそのように変化した、何か大きなターニングポイントになったものが何かあるのかということをひとつお伺いしたいなと、そのように思います。","respondent":"太田品川区清掃事務所長","answer":"ところが、３月までで言われていなかった実施時期が急遽、平成２５年４月という形で出てきたことがございましたので、私のほうで強く平成２５年４月というのは一体どこでどういう形で決まったのかというような質問、あるいはやっぱりいくら考えても都区制度改革の趣旨と。","voiceIndex":193,"id":"exchange-059"},{"speaker":"浅野委員","kind":"質問","question":"品川区としては、そういう形で分権を主張されたということで非常に頼もしい限りだと思います。今、２３区中、品川区だけがそういう形で主張していたということで、例えば、１区だけとは言いませんけれども、２３区そろって議会のほうで了解されないということになった場合、何か影響とか弊害とか、そういうものはあるのかどうか、この点について伺いたいと思います。","respondent":"太田品川区清掃事務所長","answer":"今のご質問は、１区だけが議決を得られなかったという……。","voiceIndex":195,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことで変わるのは、許可事務は清掃協議会でやるようになるということと、それから、立入検査ですか、それも清掃協議会でやるということで、品川区がやるのは、法令違反に当たるときの行政処分をやるということだけというふうなことになるのかということが１つと、それから、この立入検査ですか、指導、そこのところは、品川区が希望すればできるともお聞きしたんですけれども。","respondent":"太田品川区清掃事務所長","answer":"法令違反についても同様です。これは区だけがやると。横並びの処分内容というのは、これはもうできませんから、各区で起きた法令違反ならば、各区が主体的に考えて処分をしていくということになる。","voiceIndex":199,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、各区約３名、２名から３名というふうな感じで配置されているのが、平成２５年４月になって、３８名で２６名削減されるということなんですけれども、品川区の職員としてはどうなってしまうのか、どういう体制になるのかという、向こうへの派遣も含めて、どれくらいの人数になるのかということを教えていただきたい。","respondent":"太田品川区清掃事務所長","answer":"この数字も今のところの見込みの数字ですので、平成２５年４月以降で各区でどうするかというのは、まだ正直言ってわからないところです。","voiceIndex":201,"id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"清掃事業の特別区への移管というのは、自治権の拡充ということでもずっと区が求めてきて、象徴的なそれをもって基礎的自治体ということになったかと思うんですけれども、そういう流れの中で、今回、今まであった区の権限を清掃協議会に戻すという形になるということは、自治権の拡充ということで、品川区がいろいろな独自の政策を行っていくという中でも、一歩とか二歩ぐらい。","respondent":"太田品川区清掃事務所長","answer":"そうすると、許可事務を今度はどうするかというのは、その時点で許可事務を今度どこの組織が担うかは別途検討する、こういう仕切りになっているものです。","voiceIndex":203,"id":"exchange-063"},{"speaker":"沢田委員","kind":"質問","question":"ということは、やっぱり品川区の思いというのは、本来、各区、２３区が共通で持っていなくてはいけなかったものが、先ほど、人事の関係もあるかもしれないですけれども、変わってきてしまうということで、所長が改めて各区にもそういった働きかけを今後も引き続きやっていかれるということでよろしいですか。","respondent":"太田品川区清掃事務所長","answer":"私のほうで当然部長会へ出ていますので、その中でこの点について、清掃一部事務組合のことも含めて分権の流れの中で、やはり基礎的自治体として特別区が直接執行していく必要があるということについては、継続的に訴えていきたいというふうに思います。","voiceIndex":205,"id":"exchange-064"},{"speaker":"須藤委員","kind":"質問・要望","question":"今、所長にずっと説明していただいたように、最初の自治権拡充の基本線というのは、やはりうちの会派が伝えていかなければしようがないだろうということで、ただ、うちだけどうのということはできないので、もちろん賛成はしたけれども、その思いというのはこういう思いがあるんだよというのは、その中に伝えさせていただきたいと思っていますので、そのあたりを、骨子についてはまたちょっと考えて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その附帯決議は、ぜひ文章で出していただいて、やっぱり会派でこの条例についての態度を話し合って決めていますので、会派で検討するという時間をぜひとらせていただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-066"},{"speaker":"須藤委員","kind":"意見","question":"もちろん今日の審査の状況で、これから案文を整理をしなければいけないので、その後、正副にお渡ししたいと思っているんですけれども、それが今言った会派に戻してというのが、今日すっきりできてしまえばいいけれども、ちょっとうちもまだ執行部のほうと相談していかなければいけないので、明日か今日の遅くになってしまうと思うので、それでよろしければ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":218,"id":"exchange-067"},{"speaker":"須藤委員","kind":"提案","question":"今お話ししたように、附帯決議を建設委員会の皆さんで、定例会最終日に提案をお願いしたいと。案文については、明日、正副のほうへ出しますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":221,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、その文章も含めて、文章を検討させていただいて、附帯決議をつけるかどうかというふうなところも検討させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-069"},{"speaker":"須藤委員","kind":"意見","question":"そうしたら、うちでこれから整理するので、やはりみんなで一致できるような文章にしておきたいなと思うので、どういうことが入ってしまうとまずいだろうということはありますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうことが入ってしまうとまずいというところは特にないんですけれども、私たちとしては、やっぱりそういうふうな形で清掃協議会がやるとしても、しっかりと議会でチェックできるような、そして区としても責任を持てるような、そういう体制というのをぜひ担保できるようなものにはしたいというふうな思いはあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":227,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その附帯決議を付すかどうかというのも、その案文を見せていただいて決定したいということなので、そういうふうなことというのは、今日までは問われていなかったじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日はとりあえず最終的な決定というのは明日も委員会が続けてありますので、附帯決議を付すかどうかということも含めて、その文章を見て決定をさせていただきたいと思うんです。今、附帯決議を付しますかどうしますかと言われても、その文章がないのに、それで結構です、附帯決議を付すということに賛成ですという態度を決められないということなんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-073"},{"speaker":"須藤委員","kind":"質問","question":"ですから、共産党が読まなければわからないよということではなくて、とりあえず今委員長が諮っていただいたように、保留なら保留で構わないと思うので、そこをしていかないと、これがまた明日になってというと、そうしないと僕らもつけますということでこれから会派で文章を整理しますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、私が今日、保留というふうな形にして、明日その文章はやっぱり会派で賛成していこうということになったら、賛成というふうにできるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-075"},{"speaker":"須藤委員","kind":"提案","question":"いいんだよ。だから、全部名前を書けばいいんだから。賛成なら、提案者なんだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":236,"id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、今の時点での保留？だから、それをとる意味というのがあるんですか。その附帯決議をそういう形で出していくということに対しても、会派の中では全然そういうふうなものは検討をしていないわけです。この条例に対してしかしていないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、今からそれそのものを決をとられるというふうに言われても、私一人では判断できないので、持ち帰らせていただきたい。そして、そのことも含めて、明日、決をとっていただければ、全然今日の段階できちっと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、事前に地域の方の意見をぜひとも聞いて、そこでさまざまな不安や疑問、心配の思いもあると思いますので、その声にこたえるような審議をぜひともしていきたいと思いますので、ぜひ審議の前に意見陳述をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ事前にやっていきたいという私の思いですので、意見ですので、そういうふうな思いを皆さんに諮っていただきたいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-080"},{"speaker":"浅野委員","kind":"質問","question":"今ご説明いただきまして、今回の平成２４年請願第１７号、平成２４年請願第１８号、平成２４年請願第２１号、共通しているということで一括して説明していただきましたけれども、２９号線と３１号線、都市計画道路ですが、事業計画の廃止、そして特定整備路線から外すとの、こういう請願の趣旨だったと思うんですけれども。","respondent":"藤田都市計画課長","answer":"その状況の中で、本来は東京都としてはそれがはっきりしないと説明会の予定も組めないんだと思うんですけれども、区のほうとしては、それを待ってから説明会を組んでいては、また遅くなるというふうに考えてありますので、現段階。","voiceIndex":259,"id":"exchange-081"},{"speaker":"浅野委員","kind":"質問・要望","question":"指定をされたということも、皆さんに、じゃあ、こういうふうになりましたということもされていないという状況ですけれども、例えば、そこまでの間で、説明できる内容というのは非常に少なくなりますけれども、やはり今現在の区民の皆さんのご意見を伺う意味でも、区のほうで単独ですよね、多分都のほうは交えることはできないと思うんですけれども、このような形だったらできると思うんですけれども、ただ。","respondent":"藤田都市計画課長","answer":"それに比べまして、今回の３１号線につきましては、区のほうとしては、長期基本計画であり、あるいはまちづくりマスタープランの素案であり、整備を進めていく、あるいは検討を進める、そのような記載をしていて。","voiceIndex":261,"id":"exchange-082"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうことがありまして、今回も数としては相当な署名が出ておりますけれども、私どもも区民の方から多くの意見をいただいておりまして、先日、濱野区長に対しまして、この特定整備路線候補の補助２９号線、また放射２号線、補助２８号線、都市計画道路３１号線、こちらについて区民の皆様にきっちりと説明をしてほしいという、こういう要望書を提出させていただきました。もう一度ご答弁お願いします。","respondent":"藤田都市計画課長","answer":"私どもも１日も早くやはりまちに出て説明ができるような形にはしていきたいというふうに思ってあります。そういった意味で、東京都のほうとも綿密にお話をしているところです。","voiceIndex":263,"id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"今ご答弁いただきましたけれども、実際、この説明会をするとなりますと、建設委員会でも、ほかのさまざまな観点から告知が不十分ではないかという、そういう意見も多々出ております。そういう中で、やはり漏れのないような、そういうような告知方法をぜひとも区のほうで精いっぱい考えて取り組んでいただきたい、このように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-084"},{"speaker":"須藤委員","kind":"質問","question":"質問じゃないんだけれども、この請願、今、浅野委員が言ったように、非常に課題が多いので、まちの人は非常に心配で、これは前からずっと私ども、理事者に、こういう話があるんだということだけでも説明しておいてくださいというお願いをしていたんだけれども、今、これをどうのという、やろうとしても、都側のどういう考えを経ているんだかというのが、我々もまるっきりわからないので、この審査自体が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、３１号線なんですが、これは具体的に区が進める道路なんですけれども、ずっと今まで２９号線の整備にあわせて３１号線も整備をしていくというのが区の答弁だったし、姿勢だったと思うんですけれども、具体的な事業計画はないということなんですが、そのスタンスは、区の姿勢は、２９号線と一緒に３１号線を整備していくという、それは終わったのかどうなのか、それから。","respondent":"藤田都市計画課長","answer":"東京都のほうとして今まで進めてきた木密地域の改善のためには、燃えないまちをつくるということで不燃化のさまざまな策を進めること、それから、燃え広がらないまちをつくるための特定整備路線としての事業が必要である、その２つの策を合わせることで。","voiceIndex":269,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３１号線は、今までの区の姿勢と変わらないと、２９号線が木密の関係でできたら、それに続けて３１号線も整備をしていきたいという、その区の姿勢は変わらないということで確認をさせていただきたいと思います。その考え方を１つ確認をしたいと思いますけれども、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"延焼遮断帯の考え方ですけれども、先ほど言った食いとめる範囲だとか、どういうブロックで考えているかというようなお話もありましたけれども、東京都が示している１つは、木密地域不燃化１０年プロジェクトの実施方針の中にも記載があります。","voiceIndex":271,"id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、１キロメッシュで延焼遮断帯で道路をつくったとしても、阪神・淡路大震災の神戸の火災ぐらいの火事はその中で燃えてしまうという、それが私は延焼遮断帯の考え方なんじゃないかなと思うんですけれども、そういう点の効果というふうなところについては、区としてはどう考えられているのでしょうか。","respondent":"藤田都市計画課長","answer":"これまでも何度もご説明差し上げていますが、今回の木密１０年プロジェクトは、延焼遮断帯をつくるためだけの事業ではございません。冒頭申し上げたとおり、燃えないまちをつくる、不燃化を進めるということで、もう１つの枠組みである不燃化特区の枠組みにもあります。","voiceIndex":273,"id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、道路でこっち側には燃え移らないかもしれないけれども、その中は燃えてしまうということになれば、それこそこの間のまちづくりマスタープランの講演会のときにも質問者から出されて、回答がありませんでしたけれども、こっちも燃えてしまう、こっちも燃えてしまう、こっちも燃えてしまう、こっちも燃えてしまう、その中で延焼遮断帯だけが残るというような、そういう状況になるのではないか。","respondent":"藤田都市計画課長","answer":"私どもは、延焼遮断帯、道路だけをつくってやればいいというふうに考えているわけではなく、あわせて不燃化の事業についても進めていく、そのことでまちを燃えないまちにしていこうというふうに考えております。","voiceIndex":275,"id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は一番何を優先しなければいけないかというふうなところで、延焼遮断帯、道路を今は最優先でつくるわけですよね。それで、出火件数４０件のところが２万１,６００棟まで燃え広がるという、そういう想定なわけです。そのために、それを防ぐために、そして区民の命と財産を守るために、一体何が一番最優先でやらなければならない課題なのか、そこら辺のところについてはいかがでしょうか。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"繰り返しになりますが、木密地域不燃化１０年プロジェクトの中で、もう１つの枠組みである不燃化特区、これについては先行実施地区で品川区内にも既に１カ所選ばれております。それについても具体的な制度の中身はこれからになります。そのために実際に土地をお持ちになっている方とか、そういう方に対しての生活再建とか、いろいろな課題がありますから、それをきちっと丁寧な説明と。","voiceIndex":277,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そんな中で同じ効果、しかも朝の５時台の阪神・淡路大震災のところで、同じ効果となんで言えるのかというのが、私はどうしても理解ができないんですね。根拠というのはこれしかないのでしょうか。道路を延焼遮断帯として効果があるという根拠というのは、私はこれで根拠と言えないのではないかなというふうに思うんですけれども、そのところはいかがでしょうか。","respondent":"片田都市環境事業部長","answer":"区としてできること、東京都としてできること、地域としてできること、それらがこういう状況の中で何をなすべきかと、逆にそれが一定の評価ができるというものであれば、当然それは十分検討する余地があると考えていますし、やはりそういう経過の中で東京都のほうとしても。","voiceIndex":280,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、３・１１のときに品川区の道路がどんな渋滞になったのか、震度５強でしたから、もちろん車両火災は起こっていないと思いますけれども、それが震度７とか、震度７強とか、そういうふうになったときに、車両火災が起こる、渋滞に対して車両火災になったら、もう本当に延焼遮断帯で安全なまちをつくると言いながら。","respondent":"藤田都市計画課長","answer":"委員がお話しするとおりに燃えてしまうという例も私も読みましたし、そうではなく、燃え広がらない、車が燃えてしまっても延焼遮断にきっちりなるんだと、そんなような事例もありますので、これは東京都なり国土交通省が。","voiceIndex":282,"id":"exchange-092"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、私、さっき言ったように、これ、東京都の話が来ないと、私たちのあれもどうなる、この請願自体もどういうふうにして見ていくんだということを、僕らは大局的にはそういう延焼遮断帯というのは必要だよ、品川区全体の防災というものに、そういう意味では、ただ、地域の方々からこういう問題もあるよというような話も聞いているので、そのことがどうやって改善できるか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、これだけたくさんの署名も添えられて３つの地域から請願が出されているわけですから、そして、請願を出された方も今日は傍聴に見えているわけですから、この請願を出された地域の区民の皆さんの請願の趣旨、それから要望、そういうものに対して、この委員会が真摯に審査をするというのは当然のことだし、今まで一般質問だったりとか、この委員会でやりとりがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":286,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"はい、わかりました。交通量予測とアセスメントについてなんですけれども、私が総括質問したときに、部長が、東京都が交通量について予測して検討されるものだと思いますということで答弁をされたんですけれども、この交通量予測というのは、この２９号線についてもされるのでしょうか。","respondent":"藤田都市計画課長","answer":"交通量の予測とアセスメントの関係、両方関連してきますけれども、交通量の予測のほうですけれども、この後、もちろん整備を検討する中で、どれぐらいの交通量があるから何車線必要なんだと、そういうような形の整理をしていくことになります。","voiceIndex":288,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて私は、その交通量にしても、アセスメントについても、２９号線や放射２号線はアセスメントの対象になる可能性が高いということになるのかと思うんですけれども、それも含めて、こういうふうなことだからということで、整備決定の前にぜひやっていただいて、地域の方にも説明をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":291,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最優先で。道路の前に。ここにこそ私は税金をつぎ込んでも力を入れていくことが、区民の命と財産を守る最も防災対策の要になると思うんですけれども、そこの考え方はいかがかというふうなことをお聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"その中で今回も木密地域不燃化１０年プロジェクトというぐらい、この事業も不燃化の事業ですので、そうしたさまざまな施策を重ね合わすことで、もちろん死傷者の数を少しでも減らしていく、こういうような形で進めるものかなというふうに考えてあります。","voiceIndex":292,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、私は、耐震化助成をぜひとも増やして、そうするところで命と財産を守る対策というところに最優先で取り組んでいただきたいということを強く要望しておきます。これでもなんでそのきずなが断ち切られないで、町会が３つに分かれてしまって、これでもそれは固いきずなで頑張ってくださいというふうに言われるのか、そこのところを改めてお聞かせいただきたいと思います。","respondent":"藤田都市計画課長","answer":"３１号線については、繰り返しになりますけれども、整備の検討をしていくとしているもの。ですから、まとめて一気にそこまでいくということではなく、例えば、１００年後とか見れば、そういうようなことになるのかなというふうに思います。それはちょっとスパンはわかりません。","voiceIndex":294,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを心配しているからこそ、この道路づくりはやめてほしいと言っているんだと思います。少なくとも３１号線は、課長が今、１００年先の計画かもしれないというふうなことで、でき上がるのはそうかもしれないというふうに言われましたけれども、それであれば、３１号線は、しばらく白紙に戻しますとぜひとも言っていただきたいと思うんですけれども、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"すみません、ちょっとはずみで１００年後とか言いましたけれども、あくまでも長期基本計画であり、マスタープランの中で整備の検討をするというような形でしている道路ですので、これについては整備の時期についてはしっかり見守りながら進めていく路線です。","voiceIndex":296,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都の考え方が出ていないというのは、支援策が出ていないだけであって、これを指定をして計画を進めていくという考え方ははっきりと出されているわけですから、その中でその計画に対して区民の方々が、本当に不安な、心配な、そしてやめてほしいという、そういう地域の方々の切実な声をぜひこの議会で声として聞いて、そしてそれを参考にして結論を出していくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-100"},{"speaker":"浅野委員","kind":"意見","question":"先ほどの質疑の中でも申し上げましたとおり、事業内容がまだ決まっていない、また、区民の皆様への支援策も決まっていないという状況の中で、一番大切だと私が考えていますのは、区民の皆様への説明だと思っています。そういう意味では、この件につきましては、継続ということにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":308,"id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"私たちは、道路も大事だと思っていますし、また、区民の皆さんの命や財産、そういうものも大変大事だと思っています。そういう意味で、軽々に結論を出すよりも、継続審議としたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":310,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、結論を出すべきだと思います。区民の皆さんの思いも本当に切実な状況で、早くに決定をして、議会としてこういう意思を東京都にも伝えていく、こういう行動に移っていくためにも、ぜひ結論を今日出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-103"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":88899,"voices":318}},{"id":"h24-20121126-9","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"文教委員会","time":"午前１０時００分～午後１時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"教えていただきたいんですが、移転にかかわるところは位置の変更ということ、それから事業ということですが、二葉すこやか園移転のほうの事業内容改正、この短時間就労型保育室の設置というのは、条例とはかかわらない事業内容ということですよね。これは根拠というのは、なしなんでしょうか、おさらいの話、これは。","respondent":"伊崎待機児童対策担当課長","answer":"短時間就労型保育室につきましては、事業の要綱で運営をしておりまして、こちらは長期基本計画、実施計画で５カ所まで設置するということを定めしています。こちらが５カ所目ということで、それで一応目標は達するということになります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その点について見解を一つ伺いたいと思います。それから二つ目は、騒音の問題です。そして、学校の子どもたちと０歳、１歳、２歳児室がずっとあるわけですけど、生活時間が全く違うのに、体育だとかいろんな授業でグラウンドに降りていくときに、ここの昇降口を通るわけですけども、そういうあたりの音の問題というのはどういうふうに解消できているのか、ちょっとその辺について伺いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"それぞれご質問がありますけれども、こちら、保育園といたしまして、この施設、豊葉の杜学園の中に併設をするということが決まりましてから、時間をかけて教育委員会、あと施設整備課のほうと保育課で検討を重ねてまいりました。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"全然具体的な説明ではないですよね。例えば、日照が確保できているというふうにおっしゃるけども、１日の生活時間として何時間確保できているんですか。あるいは、防音についても、どのぐらいの騒音が検査した結果、どうなんだとか、そういうことも検証したうえでのことなんだろうと私は思うんですけども、その辺はどうなんですか。具体的な数字を教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"防音につきましても、建築基準法にのっとりまして施設の開設をやっておりますので、防音を、今何デシベルまでという数字は持っておりませんが、通常の保育園が、保育園としての生活ができるというところは前提としてしっかり対応しております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"非常に残念です。それぞれの部署に任せているという、ここが一番の責任の部分ではないんですか。そこを担当課のところでそういう具体的な数字も示せない、そういうことで条例をつくって、それを信じていただきたいと、そういうことはちょっと改善をしっかり求めていきたいというふうに思います。全部示していただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"今までも荏原第三中学校には日常的な連携、それからイベント等については生徒にさまざまなボランティアとしてご支援をいただておりまして、今度はそういう複合施設、小学校もありますので、複合施設として、さらにそういった面等を活かして、強みとして。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"万全確保は難しい、従来と位置は変わらないという印象のところでの部長の答弁でしたけれども、私は新設をするんですから、今までと変わらないからいいというわけにはいかないではありませんか。新設をするんであれば、さらにいい条件をつくるというのがまず第一なのではないですか。そういう姿勢が非常に感じられない。同じなんですか、その辺の見解はどうなんでしょうか。伺いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"ですので、当然生活時間も異なりますので、そのあたりは、より一層子どもたちの生活の環境を整えていけるように検討すると、こういうふうに考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"答弁はされていますけれども、私の聞きたいことには答えていないというのがありますので、質問していますので、できるだけまとめていきたいとは思いますが、お伺いします。しかし、大事なことは、具体的なデータを示していただけていないので、防音対策をしていますというふうに言われても、ああそうですか、それで十分です、よかったです、賛成できますというふうにはならないということです。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、やはり一定の制約というのはやむを得ないところがあるだろうと思いますが、先ほども申し上げたとおり、従前以下にはしないような形できちんと設計等も詰めてきたものでありますし、また日々のさまざまな保育の運営あるいは幼稚園の事業の展開の中でも。","voiceIndex":17,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"最初に確認なんですけど、先ほど定員の訂正がありましたよね。二葉すこやか園の定員の訂正人数、そのことの数字をもう一回教えてください。お願いします。","respondent":"伊崎待機児童対策担当課長","answer":"大変失礼いたしました。二葉すこやか園の幼稚園の定員です。４歳児が、正しくは６０名、５歳児が６４名、合計１２４名で、二葉すこやか園としての合計が１９０名です。失礼いたしました。","voiceIndex":19,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"日照権、それから防音、採光等々の話がありましたけれども、もしその指摘が事実だとするならば、これは議会としても大きな問題になるわけでありますから、再度確認するのは、二葉すこやか園の建設等について、そういうことについて、おそらく担当課と十分調整をとった上で、ほかの保育園とも同じような、あるいは同水準以上のものをつくっていったと思うんだけれども。","respondent":"伊崎待機児童対策担当課長","answer":"日照権、防音等の施設の設備、建築関係につきましては、長い時間をかけまして、施設設備の担当課と、あと保育課、豊葉の杜学園を所管します教育委員会のほうと協議を重ねて、当然のことながら最善の対応で進めておりますので、子どもの生活環境としては。","voiceIndex":21,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"私たちは、当然品川区のこの二葉すこやか園だけが不十分な施設だと思っていないわけです。だから、そういうさまざまな建築基準法上、それから防音、採光といった中で、日照の問題、これ、日照ですね、例えば、保育園はこれだけ確保しなければいけない、例えば何時間とか、そういう規定があるんでしょうか。あれば、それを教えてほしいですが、私はないと記憶しているんですが、いかがですか。","respondent":"伊崎待機児童対策担当課長","answer":"保育園の日照時間につきましては、特に規定はございません。日照時間につきましては規定はございませんが、建築基準法の採光については規定があります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区は都会ですから、高層ビルがたくさん建ち並んでいる中で、日照を求めていくことはもちろん必要です。それは理解しています。ですから、繰り返しますけれど、今品川区のこういう都市的な環境の中で、子どもたちにとって最適な環境を現行の法律の基準の中で確保していくことさえ担保されていれば、これは議会として進めていくべきだと思います。","respondent":"金子子ども未来事業部長","answer":"もちろんそれには前提としては法令等の条件等々は遵守しながらということでやっておりますので、それに加えて先ほども申し上げたとおり、日々の運営というのは、そういった条件のもとの中でさまざまに工夫してやっている。","voiceIndex":25,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後に要望ですけど、待機児童対策というのは、対策を進めることによって、これは定員が増えるわけです。だから、これは私たちとしてはぜひ進めていっていただきたいし、繰り返しますと、さまざまな品川区を取り囲む社会的な、それから建設、建築の制限も当然あるわけだから、その中で最大の努力をしていっていただいて、待機児童対策を進めていっていただくようお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、品川区という限られた資源しか持たないところで、かつ待機児童の解消ということも早期に求められている中で、今限られた資源の中での最善という意味だと解釈しております。意見です。あまり新しいことをやっているという気負いではなくて、当たり前の保育をきちんとやっていく一つの施設という位置づけでやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"私、理事者より、むしろ委員のほうに伺いたいんですけども、先ほどもちょっと紹介したんですけど、４歳児、５歳児室は、北西に向いているんですね。そういう北向きの保育室になっているんですよ。だから問題なんだという指摘をしたんですけど、その辺も含めて、どんな見解を持っておられるのか、改めてちょっとさまざまな会派の皆さんに伺いたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"意見","question":"理想を言えばきりがない。それは、ご指摘は正しいと誰でも思います。それを限られた品川区というこの都市化の中で、どういうふうに合致していくかということを審査する。それについて、結果としては、先ほどから同じように、つくらないよりは、つくったほうがいいでしょう、そういうところで、私は議会として指摘すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"さっきも申し上げましたけど、賛成の気持ちは強いですけど、やはり待機児解消に、拡大したということは大きく評価したいと思うんです。預かり保育もさらにやるという点では評価したいというふうに思うんですけど、就学前の子どもの一番大事な成長、発達に欠かせない日照の問題が大きく欠落している、そういう点で賛成するわけにはいかないというふうに思います。いいんですか、そんなので。反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"すみません、ちょっと今メモしきれなかったんですけど、保護者補助金のほうの対象なんですけれども、平成２２年に所得制限を緩和し、対象を拡大して、それから３３万４,１００円にした、もう一度教えてください。それで、今ご紹介があったのだけで３段階あるんですけれども、それぞれ対象者が実際に私立幼稚園在籍者の何パーセントに当たっていたかというのをそれぞれ教えてください。","respondent":"立川保育課長","answer":"それで、約１０％の方に対象が広がりまして、総数で６０％ぐらいの方が対象になって、今年度から３３万円４,１００円までの方が対象になりまして、全体で６５％程度の方に交付するという形になりました。","voiceIndex":45,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"今年度は昨年度以外に数字はそこまでですか。それというのは、保護者補助金というのが幾ら出ていたかなというのと、これは全てが区の単費ではなくて、都から出ているお金が結構あったと思うんですが、補助金の額のうち、都はどれだけで、区はどのくらいあるのか、それをお知らせください。","respondent":"立川保育課長","answer":"ですから、次の階層で区民税の所得割額が今年度７万７,１００円以下の世帯につきましては、都の分が４,５００円、区の分が７,０００円、次の階層で、同じく２１万１,２００円までの方につきましては、都の分が３,５００円、区の分が７,０００円、次の階層で。","voiceIndex":47,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"いっときに比べて、大分平均に近づいてきたのかなという印象は持ったんですけれども、とはいえ、ここに書いてあるとおりで、非常に教育費が単純に大きくなっている。そういった意味では、やはり補助金の所得制限というのは、私は撤廃を含めて考えていいと思っているんですけれど、そういった方向でぜひ検討いただきたいなと思っているんですが、区としてのお考えはどのようなものでしょうか。","respondent":"立川保育課長","answer":"やはり撤廃しているところなんですけれども、そもそもこの制度につきましては、一定所得の低い方も等しく私立幼稚園の教育を受けさせたいという保護者の方の要望がありまして、それで区として補助してきましたけれども、平成２２年、平成２４年も所得制限に関しましては。","voiceIndex":51,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問・要望","question":"私立幼稚園に入れているというのは、幼稚園教育を、ある意味余裕があって選択しているというだけではなくて、保育園に入れなくて、仕事をやめざるを得なくて、しかも３歳から入れようと思ったら私立しかないとか、いろいろな選択肢の中で入っていらっしゃる方々がいて、幼稚園、私立幼稚園のお母さん方も共働きの家庭が非常に多いという現実から見ても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"区立幼稚園、平成２４年４月１日現在、６５０人が在籍しているという資料があるんですけれども、月謝、何ていうんですか、月謝というんですか、保育料か。区立幼稚園の保育料をまずお知らせください。さまざまだと思いますが、平均的なところで結構です。","respondent":"立川保育課長","answer":"区立幼稚園の保育料ですが、月額８,０００円です。","voiceIndex":54,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"でも、同じ子どもを養育している品川区の家庭ですから、やはりそこにおいては、何らかの対応があってしかるべきだろうという思いがあるわけですから、数字、わからないですか。わからなければ、あれですけど、その格差を是正するためには、私立幼稚園に対するさまざまな助成金を厚くしていったほうが、私としては効果があると思うんですけれども、お考えをお聞かせください。","respondent":"立川保育課長","answer":"現在、公立幼稚園につきましては、私立の補完ということでこの間説明させていただいているところなんですけれども、やはり現状、私立だけでは幼稚園教育を希望される方を全て受け入れることは前提として無理であると思いますので、公立保育園、私立と公立の費用比較ですけれども。","voiceIndex":56,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、すぐにはなかなか答えが難しいかもしれないけれども、要望になってしまいますけれども、そういう大きな区財政の見通し、それから子どもたちの人数の変化、そういうさまざまなことを精査すると同時に、格差是正に対する有効な施策の一環として、私たちとしては私立幼稚園の方々に対するさまざまな部分を、さまざまな負担をしながらというのが前提なんだけど、拡大すべきと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"もう少し広げる必要があるのではないかなと思います。それで、伺いたいのは、いろいろな、何年も前から、保護者負担への補助をしてきたとか、施設への補助金を出してきたとか、徐々に拡大してきていることは事実なんですけれども、これらの施策は子育て支援ということでやっているのか、ちょっとそのあたりの基本的な考え方、そこをちょっと伺いたいと思います。","respondent":"立川保育課長","answer":"いわゆる幼稚園、保育園、やはり子育て支援というか、乳幼児教育の充実というところで、品川区としましては、保護者に対する関係ですとか、幼稚園の質の高い教育に、保育園の質の高い保育につきまして、いろいろ施策を打ってきました。","voiceIndex":59,"id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"あまりよくわからなかったので、もう一回伺いたいんですけども、子育て支援というのは、いろいろな名目があると思うんですね。この補助金を増やしてほしいとか、補助金をいろいろと拡大してきている、そのことは経済的な支援だというふうに思うんだけども、大もとは、考え方は、子育て支援なんですか。","respondent":"立川保育課長","answer":"大もとといいますと、子育て支援というか、乳児、本人に対してよりよい環境を形成してもらうということで、私立幼稚園に対して補助し、ここに通うお子さんに対しましても経済的な支援です。","voiceIndex":61,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"子どもを健やかに育てるということ、幼稚園に通わせる方へ、安心して通園できるようにということでの経済的な支援をしながら子育てを支援していくと、こういうことでいいんですか。ちょっと、しつこくて悪いんですけど。","respondent":"立川保育課長","answer":"就学前の保護者の方が、自分のお子さんにどういう教育、保育をさせたいかというところで私立幼稚園の選択、公立幼稚園の選択、保育園の選択、さまざまな選択があろうかと思いますので、この辺につきましては、保護者への子育て支援という部分と、あとやはり。","voiceIndex":63,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"そうであるならば、やはり所得のあるなしに限らず選択できるようにするべきだというふうに思うんですね。それと、先ほど２３区の平均が紹介されましたけれども、その平均も全ての階層で下回っているという点について、やはり区としては、私は引き上げるべき、少なくとも平均額までは引き上げるべきだと思っているんですけども、その辺についての見解というのはどうなんでしょうか。","respondent":"立川保育課長","answer":"先ほどお話ししたところというのは、例えばですが、保護者に対する補助金につきましては、国制度を基準といたしまして、東京都より補助、区独自で入園料の補助金というのも出しておりまして、それで、入園料の補助金も含めますと。","voiceIndex":65,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"国の補助金を含めると平均額に近いというお話ですね。さっきの２３区との比較との関係では、それはどういうふうに評価したらいいんでしょうか。","respondent":"立川保育課長","answer":"月々の保育料と、あとは今お話ししたのは、入園当初の入園料というのが各幼稚園で定められていますので、その補助額に関しましては、品川区ではかなり高い水準で出している状況で、合計で考えますと、当然東京都の補助、補助制度、国の補助制度と含めまして。","voiceIndex":67,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"それと、先ほど２３区の平均というのは、国の部分は含まれていない。そこで聞いているのに、国のところを持ち込んで、しかも下回っているにもかかわらず、答弁をごちゃまぜにするというのは、私は適切ではないというふうに思うので、もう一回繰り返しますけども、園児保護者補助金、先ほど紹介した２３区との、都と区の平均額と、品川区の合計額の比較は、各階層で下回っている、そのことは事実ですか。","respondent":"立川保育課長","answer":"それで、各区で、品川区においては、保護者補助金につきましては、東京都の補助額と、それに対して区が上乗せしているという意味で、月々の保育料につきましては先ほどお話ししました、先ほど数字を挙げさせていただいたとおりです。","voiceIndex":69,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"聞いていることに答弁をしていただきたいというふうに思います。私は、２３区の平均と、品川区の補助額、東京都も含めて補助額の合計をすると、繰り返して言うけども、区民税非課税世帯から３３万４,１００円以下までの世帯、全ての階層で下回っているというふうな、最初の、ほかの委員からのご質疑の中で示されました。これは意見ですから、答弁は要らないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今日、結論を出していただきたいと思います。それから、請願は採択ということで、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"私も今日出していただきたいと思います。態度は賛成をしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"阿部委員","kind":"意見","question":"２番に関しましても、今ご説明があったとおり、専門的な知識を持つ職員というのは、人事異動があったにしても継続しているけれども、委託でも専門職が配置をされているということで、ここに書いてあることは、とりあえず満たしているだろうと考えています。やはり３０人学級というだけだといいように聞こえるんですけれども、実際にやろうとすると、幾つか大きな問題が出てきてしまうなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"それで、２年生の３５人に今年度なったその部分なんですけれども、何学級からどのぐらいの学級数が増えたのか、それを一つ教えていただきたいのと、それから来年度から５年間に全学年に３５人学級にしていくというところを、さっき財源の部分はあるけども、やっていくということになったときに、品川区としてはどういう方向でやろうというふうに考えているのか、ちょっとそのあたりをもし計画があれば。","respondent":"和氣学務課長、安井子育て支援課長、伊崎待機児童対策担当課長","answer":"先ほど申し上げましたように、さまざまな学習形態がありますから、例えば国語で５人ずつに分けて授業をやっているとか、算数が苦手ということもありますし。児童センターの指導員の委託の件ですけれども、有資格者だからいいということではなく、先ほどお話しましたように、経験年数をやはり持っている人でないと。品川区では、当然のことながら児童福祉法に基づき、区の実施責任のもとに保育行政を進めております。","voiceIndex":88,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、その少人数教育の効果は、どういうふうに教育委員会としては見ているのか、ちょっとその辺を改めて伺いたい。そういう事態に対して、どのような評価をされているのか、その辺を伺いたいなというふうに思っているんです。品川区の場合はそんなことはさせませんと、そういう具体的な考え方だとか、しばりだとか、そういうのがあれば、それはそれで紹介していただきたいというふうに思っております。","respondent":"太田指導課長、安井子育て支援課長、伊崎待機児童対策担当課長","answer":"高い子どもに対しても、人に教えたり、一緒に考えることによって学びのレベルが上がるというようなところで。これについては、委託館も必ず参加するようにという形で、同じようなレベルを確保するために。品川区におきましては、当然事業者を選定する場合に、その事業者の経営母体についての経営状況も確認しつつ、実際の運営につきましては。","voiceIndex":92,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそれは実践をし、広げていただきたいというふうに思っているわけです。そういう点で、１クラスの人数が少なければ少ないほど班の数も当然少なくなりますよね。だから、やはりきちんと最後の最後まで公的責任を貫けるような、そういうことを大事にしていただきたいということを要望として私は、意見としても述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"確認","question":"請願項目、何点か確認します。１点目の公的責任による保育行政の推進というのは、私たちからすると当たり前のことであって、わざわざ請願を出す必要はないと思うんだけれど、一応品川区は公的責任において保育行政を展開していますよねという答弁をもう一回だけ。","respondent":"伊崎待機児童対策担当課長","answer":"品川区では、児童福祉法に基づきまして公的責任のもと、保育行政を展開しております。","voiceIndex":97,"id":"exchange-036"},{"speaker":"伊藤委員","kind":"確認","question":"あのときだって、専門職からいわゆる非常勤にかわるときだって同じことを言われていた。だけれども、今の品川区の保育の現状はそうではないということであって、そうすると、いわゆる児童センターについても、しかも資格もあって、ある程度、実際勤務先以外のベテランを配置されているのであれば、ある意味質は担保されていると思うんだけれども、もう一回そのところの確認をお願いいたします。","respondent":"安井子育て支援課長","answer":"専門的な知識を持ち、経験を持った職員を配置しておりますので、そこら辺については問題のないような形になってあります。","voiceIndex":99,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"そうしたら、保育園の行財政改革を進めるときに、さんざん言われましたよね。専門職ではないから保育のサービスは低下するんだ。入れ替わり立ちかわりだから、こういう内容がなかなか相談しにくいんだ。となれば、この児童センターについて、万が一そういう状況が発生したとしても、そういう連携を十分とって、その筋から解決をしていくと思うんだけれども、その考え方について答弁をお願いいたします。","respondent":"安井子育て支援課長","answer":"品川区では、安心ネットワークというものがございまして、そこの席にも委託館の職員が入っておりまして、そういった連携は常にとれるような体制をとってありますので、他館の連携等も十分に問題なく行われているというふうに考えてあります。","voiceIndex":101,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"提案","question":"品川区で職員数を増やすと、その財務を議会に提案されたときに、答弁に対して賛成するかどうかはわからないけれども、そういうことまで考えて、この請願を出されているのか、私は非常に疑問を感じるんだけど、話をもとに戻して品川区が東京都に対して、うちが３０人学級をやるから、人を増やしてくれと言った場合に、果たして東京都はそれを受け入れてくれるかどうかの確認をまずお願いします。","respondent":"和氣学務課長","answer":"言った場合、一切ないと思います。今、大変厳しくて、もちろん都も国が出している部分とあわせてやりますので、お願いしたとしても、まず不可能だというふうに考えております。","voiceIndex":103,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、私たちのほうとしては、今の制度の中で最大限教育効果が出ることのほうに努力を形成すべきであって、３０人学級に絶対しなければいけないと私たちは思っていません。むしろ、今のそういう財政的な状況とか、それから人的な資源が入っている中で、目の前の課題をどう対処して、いかにいい環境にすべきかということのほうがはるかに大事だと思いますけども、品川区の考え方をお聞かせください。","respondent":"和氣学務課長","answer":"それを考えますと、教員確保自体が大変難しい問題ですし、先ほどもご答弁させていただきましたけれども、基本的に私どもは今の段階で教員の質を向上させるということが大変重要だろうと思いますので。","voiceIndex":105,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"意見","question":"今日、結論を出すということをお願いしたいと思います。それから、私たち自民党は不採択で意見を表明します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-041"},{"speaker":"阿部委員","kind":"質問・要望","question":"今日、結論を出すということでお願いしたいと思います。それで、内容としては、意見としては不採択です。ちょっとつけ足しますと、１番については非常にいいと申し上げました。やはり、相談しやすい体制、相談に行ったためではなくても、顔を合わせている中で、いろいろなことが、ちょっと話が出てくるような体制というのは、ぜひ児童センターの中でもより求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"今日採決を諮っていいと思います。理由です。１点目の公的責任、これは当たり前のことであります。その大きなハードルになって、ずっと生き続けていくということになるわけですから、そういう点でも、私は先生と子どもの関係がしっかりつくり出せるような、そういう教育環境を整えるという点で３０人学級というこの要望は、当然の要求だというふうに思います。以上が私の提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-043"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"いじめの報告ができて、この間１１月５日の文教委員会で説明後に質疑したんですけれども、あれで十分尽くされているというふうに私は思えないんですね。ぜひ正副委員長のところでそういう時間をやはりしっかり持っていただきたいなというふうに思っているので、受けとめていただいて、場を設けていただきたいなというふうに思っております。そのことについて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-044"},{"speaker":"金野委員長","kind":"提案","question":"今いただきました、私のほうから、前回の委員会の報告事項で、いじめ等の調査状況についての中で、阿部委員から正副委員長に今後に向けての議論をする場の機会を設けてほしいとう要望について、お答えいたします。準備が、時間が必要かと思いますので、準備ができる、大体の想定として２月、４月の委員会にご報告をいただくということで調整をさせていただきましたので、ご報告をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"諮っていただいて、そこまで報告いただいたのはよかったなというふうに思っております。ですから、教育委員会の準備ももちろんあると思うんですけれども、やはり区民の、区議会への注目だとか、そういうことを考えたりすると、１２月、１月、２月、３カ月先になってしまうので、もう少しその辺の日程的なところというのは、研究したほうがいいかなと私は思うので、その辺についてどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4776#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":39702,"voices":125}},{"id":"h24-20121126-5","meetingId":"h24-cm11","date":"2012年11月26日","dateIso":"2012-11-26","committee":"総務委員会","time":"午前１０時００分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)の「第８１号議案 東品川橋架替工事（下部工その１）請負契約の変更」","agenda":"はじめに(1)の「第８１号議案 東品川橋架替工事（下部工その１）請負契約の変更」","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"変更の概要の３番に記されている、コンクリートに木片がまざっていて、含まれた手法でやらなきゃいけなくなったと。これはそもそも以前工事をされた方があまりよくないコンクリートを使ってやられたからこういう結果になったのか、そのことを教えていただきたいと思います。","respondent":"稲田道路課長","answer":"それを持ちまして、ちょっと東京都第二建設事務所に行きまして、こういう状況であるのだがどうだというところにおきましては、建設後四十四、五年たっておりまして、なかなかもう追及もできないし、もう引き継ぎでじかに品川区がやってというところでございました。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"これは要望になってしまうんですが、やはりそういった初めの工事のときのそういった状況において、次の工事がこういうような結果が出てしまうと。これはあくまで東京都がそうことをやっていたということでありますが、しっかりとそういうところもしていただけると、そういう余分なことを次につながなくても済むので、そこは品川区としてもしっかり今後お取り組みいただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"ひとつわからなかったのが、橋脚のところが、これ、茶色とオレンジっぽいのと色違いになっていますよね。この違いを教えてほしいのと、工法が全部撤去しないで行うというあたりがどういうことなのか、その辺、ちょっと工法がわかる方がいたら教えてください。","respondent":"平澤経理課長、稲田道路課長","answer":"質問の第１点目、先般旧荏原平塚中学校跡地多目的広場整備工事につきまして、契約を辞退するということで。橋脚の下に、この絵ですと３本ほど杭がありますが、この杭をもともと港湾管理者から全部抜きなさいというような話もされておりまして、ただ。それで、この共同事業体を組んでいるということで、こちらの工事につきましては、きちんとした施工をしているということ。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"工事着工中ということと、きちんとした仕事をしているという意味では、今日説明の前の工事のところでいろいろ問題があったというところにおいては、安全な工事、あと正しい工事をしていただきたいという意味では、これからもきちんとチェックをよろしくお願いしたいのと、今回は大もとじゃなくて、いろいろな事態で増額というところなので、了解します。","respondent":"稲田道路課長","answer":"撤去する部分の絵は載せておりませんで、ちなみにもともとあった杭といいますのは、斜めに裾を広げるような形で杭が打たれているんですね。だからその範囲が広がることを極力抑えようという状況です。","voiceIndex":14,"id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問","question":"今の変更の概要の１番のところの、橋脚周辺の掘削土に油分が含まれていたという変更理由なんですけれども、先ほどの現場での経理課長のご説明だと、近くの仮設道路とかを工事したときに、近接のところを分析したらこういうことはなかったということで、素人目から見ると本当に近い場所にあって、そういうところの土壌がそんなに変わるものなのかという単純な疑問なんですけれども。","respondent":"稲田道路課長","answer":"ここは運河であり、まして以前工事をしたところということで、埋め戻しだとかそういう人工的なものの土がまざって、この部分での土質が急変したのではないかと私どもは分析しておりまして、落ちついた地層においては急変するようなことはあまりないんですけれども、こういう運河。","voiceIndex":16,"id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問","question":"今回、ちょっと変更内容が、こちらの側が予測できなかったことが非常に多いようなことがたくさん書いてあったので、ちょっとそこのところが気になったので質問させていただきました。よくある例ではないということがわかりましたので、運が悪かったのかということで、了解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"自民党、賛成します。これ、工期を延長するということがあるんですが、そこのところ、延長しても慌てることで事故が起こらないような形で、作業員たちの安全の確保と、延びたからといって、延びて契約も成立しているわけですから、あまり取り急ぎ工事を進めるようなことがないような形で、作業員の安全確保だけはしっかりしていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"共産党、賛成です。一言だけ。契約の業者は全国的なところで受けとめていくというところにおいては、本当に調査をきちんとして、不正が行われないように厳しくやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"}]},{"id":"topic-02","title":"の「第８２号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約」","agenda":"の「第８２号議案 旧荏原平塚中学校跡地多目的広場整備工事請負契約」","exchanges":[{"speaker":"石田（慎）委員","kind":"意見","question":"以前の契約と金額の差異があるのかどうかということと、工期についても、どのような方向が許されたのか、その２点をあわせてお知らせください。","respondent":"平澤経理課長","answer":"４００万円ほどの増加となっています。工期につきましては、前回では７月１７日までが工期だったところを、８月２０日までの工期です。議決の関係がございまして、こちらの工期につきましてはおおむね１カ月ほど短くなってあります。","voiceIndex":31,"id":"exchange-009"},{"speaker":"石田（慎）委員","kind":"質問","question":"その４００万円増加というのは、どのような理由で増額がされたのかを教えてください。","respondent":"平澤経理課長","answer":"一点目は、先ほどご説明申し上げましたとおり、工期が１カ月ほど短くなってしまったということがあります。二点目なんですけれども、こちらにつきましては、全体的な建設業者といったことではありますが、労務単価が非常に上がっているということがあります。","voiceIndex":33,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、前回制限付き一般競争入札の方法だったんですが、今回指名競争入札にしたという、ここの理由を一つお聞かせいただきたいのと、今、ご説明に労務単価が上がったということにおいては、今回、前回と同じく入札に参加をされているところ、どこも入札金額が上がっているということは、今、ご説明があった労務単価の件なんでしょうか。","respondent":"平澤経理課長","answer":"こちらにつきましては、制限付き一般競争入札の場合、公示期間が１０日は必ずかかります。こちらにつきまして制限付き一般競争入札をやるとすると、今回の第４回定例会に間に合わなくなってしまうということがございまして、したがって工期が大幅におくれてしまう。","voiceIndex":35,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"初めこの制限付き一般競争入札から指名競争入札に変わったところにおいては、本社でありながら不正の談合の問題で辞退ということで、より中身を厳しくチェックできる方法なのかなと思って受けとめたんですけれども、指名競争入札の選定の要綱には、適格性の判定というので結構いろいろ項目が挙がっていたりするんですけれども、前回契約のことをちょっと学ばせていただいたんですが。","respondent":"平澤経理課長","answer":"厳しく選定をしています。","voiceIndex":37,"id":"exchange-012"},{"speaker":"阿久津委員","kind":"確認","question":"一点だけ確認で、先ほど工期が約１カ月間おくれるということだったんですけれども、たしか地域の方からのお話で、その地域のイベントがそこで間に合うか、間に合わないかというようなお話があったと思うんですけれども、その辺がどういうふうになったのか、地域の方のご理解をいただいているのかどうかだけ、確認させてください。","respondent":"平澤経理課長","answer":"先ほどのことで１カ月おくれるですが、地域のイベントにつきましては９月を予定しているです。前回、議案を撤回させていただいたときに、すぐに町会等にご説明に参上いたしまして、１カ月ほどおくれる可能性が出てきたということでお話をさし上げました。","voiceIndex":39,"id":"exchange-013"}]},{"id":"topic-03","title":"の「第８３号議案 専決処分の承認を求めることについて」","agenda":"の「第８３号議案 専決処分の承認を求めることについて」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今回都知事の突然の辞職で行われる選挙なんですけれども、この選挙予算というのは、きちんと期間が決められているときと、こうやって突然早まっちゃったりするときで、いろいろ計算式があると思うんですが、予算的な枠で変化があるところがあるのかないのか、ちょっとその点を一点教えていただきたいのと、具体的に８ページの中身、職員給与費とか、職員がこの間にどのくらい確保されるのかというあたり。","respondent":"諸岡選挙管理委員会事務局長、本城企画財政課長","answer":"今回の都知事選挙につきましては、対応人員につきましては職員だけですと２８０名程度を予定していまして、ただ、これはその後、衆議院議員選挙が同時ダブルになってきましたので、大幅に変わってまいりますが、このときの見積もり。選挙に当たっての予算の組み方についてですが、先ほど委員のご指摘がございましたように、当然当初からスケジュールに入っているものについては当初予算で組むことになりまして。","voiceIndex":53,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"９ページの職員給与費というのは、選管の職員のためだということですね。すごく急に忙しくなってしまったと、残業続きかと思いますが、お体に気をつけていただきたいと思います。さっきのところで職員が２８０名というのは、これは職員ですか。臨時のところはどうなっているのかなというのは聞き漏らしたのかもしれません。臨時というのは急に募集する部分があるんですか。ちょっとその辺も含めて。","respondent":"諸岡選挙管理委員会事務局長","answer":"それで、人材派遣につきましては投票事務では使いませんで、開票事務のほうを人材派遣で、この時点では３０人ぐらい使う予定でおりましたけれども、実際にはまた追加をしております。","voiceIndex":56,"id":"exchange-015"}]},{"id":"topic-04","title":"の「第８４号議案 土地付建物の売払いについて」","agenda":"の「第８４号議案 土地付建物の売払いについて」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"二点お伺いします。一点目は落札金額のことなんですけれども、予定価格を大幅に上回る金額で売却ということなんですけれども、この辺の評価をどう考えているのか。売却ですから高く売れたほうがいいに越したことはないんですが、この辺の予定価格の算定の仕方は、結構駅に近くて商店街も近く、利便性の価値の高い土地ではあると思うんですが、その辺をどう判断したらいいのかということを教えてください。","respondent":"平澤経理課長","answer":"１点目、売却予定価格１億８,０００万円の根拠です。こちらにつきましては、あの辺の地価が大体平方メートル単価が５０万円くらいだと思います。６００平方メートルありますので、ほぼ３億円ということになるわけですが、ただ建物の取り壊し費用があります。","voiceIndex":71,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"ただ、これは行財政改革特別委員会でさんざん議論がされたところなので、私も議事録を全部読ませていただいたので、大事な土地なのでできたら本当に売り払いではなくて、すごくお金がかかっても、将来的に区民の福祉のために役立つ建物、共産党としては例えば介護職員の寮、今まで社会福祉法人に貸与していたという部分では住宅の確保とか災害時の活用とか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。この台帳のほうはどういう状況で見直しをするのか、そこだけ確認をさせてください。","respondent":"平澤経理課長","answer":"３年ごとに通常の路線価をもとに計算しています。","voiceIndex":76,"id":"exchange-018"}]},{"id":"topic-05","title":"の「第８８号議案 平成２４年度品川区一般会計補正予算について」","agenda":"の「第８８号議案 平成２４年度品川区一般会計補正予算について」","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"これは各選挙のときに、例えば２つの選挙を同時にやると、経費というものは削減ができるというような話が、常にこの選挙費に関しては言われているわけですが、今回、都知事選挙と衆議院議員選挙が同日の投票日ということで、これは例えば別々に選挙をやったときと、今回みたいにセットになると、これで行くとどれくらい変化というものがあるのだろうかというのが、もしわかれば教えていただきたいと思います。","respondent":"本城企画財政課長","answer":"今回の都知事選挙と衆議院議員選挙、２つのものを今回計上するに当たりましても、そのあたりも踏まえて効率的な観点から、今、ご説明させていただいたような重複部分とかを精査した上で、提案させていただいていることになります。","voiceIndex":92,"id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問","question":"都知事選挙と衆議院議員選挙を並べてみると、総額的には都知事選挙が多い金額で、ただ各項目の支出を見ていくと、基本的にはそこまでの変化、差がないですね。例えば投票の事務費も３,６００万円が都知事選挙で、衆議院議員選挙のほうは３,３００万円ですか。この経費は同日でも同日じゃなくても、もうあまり変化がないということでよろしいんでしょうか。","respondent":"諸岡選挙管理委員会事務局長","answer":"その一緒になった部分をどちらへ請求するかというのが、按分がまだ決まっていませんで、五分五分になるのか、七分三分になるのかというのがわかりませんでしたので、後から追加した衆議院議員選挙の補正予算のほうの選挙費につきましては、大体７割ぐらいを見ておりまして。","voiceIndex":94,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"先ほども都知事選挙のときの職員の数をお伺いしたんですが、あわせていろいろ加味してということなので、合計でいいので、ちょっと職員数がどのくらいか。この個人演説会費って具体的にどういうことなのか、少し教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"まだ集計的にはできておりませんが、選管のほうの見積もりといいますか、職員の必要数といたしましては、延べで１,１８５名という数です。したがいまして投票と開票とダブっている方もあります。実数で申しますと約８００人ぐらいになろうかと思います。","voiceIndex":96,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"一点、８ページの歳入の都の委託金のところの１１の衆議院議員選挙開票速報費というのはどういうことなんでしょうか、教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"これは速報ということで出しますが、その間のパソコンによりまして、それを迅速に速報を行ったり、あるいは東京都のほうへ送付したりというようなことで、そういった機器類等の経費が主な経費です。","voiceIndex":98,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、これの費用は東京都の委託金ということで、東京都の段階の集計のということですか。都の委託ということで、わかったら教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"両方とも東京都を経由して、東京都が取りまとめますので、衆議院議員選挙、それから都知事選挙、両方とも同じような流れで行っております。","voiceIndex":100,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一点だけ。都知事選挙は１９款諸収入で社会保険料が出ていますが、今度も当然人件費の中で社会保険料は出てこないのかなというのがちょっと気になったので、なぜこっちの会計には社会保険料が入ってないのかということ。","respondent":"本城企画財政課長","answer":"都知事選挙に従事する者が、主に選管本部に従事する臨時職員の分でございまして、社会保険料についてはそこの範囲の職員ということで、追加的には新たに衆議院議員選挙で独自に社会保険料負担が必要になる職員がプラスで入ってこない関係で。","voiceIndex":102,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":18882,"voices":115}},{"id":"h24-20121127-6","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"区民委員会","time":"午前９時５９分～午前１１時０６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、「報告事項」を聴取いたします。 はじめに、(1)の「第１３回中学生の主張大会について」","agenda":"の１、「報告事項」を聴取いたします。 はじめに、(1)の「第１３回中学生の主張大会について」","exchanges":[{"speaker":"武内委員","kind":"質問","question":"毎回、終わると冊子みたいなものが出されますよね。何か活用を検討と言ったらおかしいのですけれども、どのぐらいあるのでしょうか。","respondent":"久保田地域活動課長","answer":"今、委員がおっしゃったようなことは、今後もそういう受賞された方の励みになるような取り組みを進めていきたいと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"受賞の方の励みと同時に、多分すばらしい内容ですので、かと言って、中学生で非常に忙しい時期なので無理はできないのですけれども、何か逆に今度、同じ中学生なのか大人なのかわからないですが、そういうすばらしい子どもの優秀なところというか、そういうものを大人に感じてもらえるような場に、無理がない程度にうまく活用してもらえるといいかなと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"の「品川区施設予約システムバージョンアップについて」","agenda":"の「品川区施設予約システムバージョンアップについて」","exchanges":[{"speaker":"山内委員","kind":"質問","question":"それで、結局サービスセンターからサーバーを借りてということで、過去に戻るのではなく、これからの使い道の向上に努めていくことは大変いいことなのですが、費用がかかっていたということなのですけれども、この費用をまず具体的に伺いたいのですが、システム改修費用が発生していたということなのですけれども、もちろんトータルで出ていると思うのですが。","respondent":"安藤文化スポーツ振興課長","answer":"それが、大体それに対して８０％以下に抑えられるということで、１,１００万円程度の予算を見込んでおります。そんな形でイニシャルコストは３,７００万円余を計上させていただきまして、ランニングコストについては８０％以下に抑えていくです。","voiceIndex":15,"id":"exchange-003"},{"speaker":"山内委員","kind":"提案","question":"概算で年間４００万円くらい下がるということですよね。そうなると日立のほうからこういうものがありますという提案は多分されていると思うのです。やっぱり、効率性とか効果性をもっと早くに考えることが、区民に対して、一つの役所仕事のいい意味で出せる部分ではないのかなと思うのですが、そこでちゅうちょしてしまったというのは何か理由があると思うのですけれども、そのあたりを伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で１０年間引っ張ってきて、ここでバージョンアップをしてという引き継ぎになったところであります。","voiceIndex":17,"id":"exchange-004"},{"speaker":"山内委員","kind":"提案","question":"そうすると、５年契約でまずやるということなわけですか。契約のほうに入ってしまうのですが、５年たちましたといったときに、これを随意契約で日立が平成１５年から受けていることになるのか、それとも例えばこういうものはいろいろな形で各大手、大手に限らないと思うのですが、こういうサービスはどうですかという提案はあろうかと思うのですけれども、そのあたりを教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"日立を選んで、契約自体は１年契約で更新していきますけれども、このシステム自体が、はじめはスポーツ系がどんどん増えていったりだとか、どんどん集会場も増やしていく中で、このシステムの安定性というのですか、区民に周知する上での安定性、操作性と申しましょうか。","voiceIndex":19,"id":"exchange-005"},{"speaker":"山内委員","kind":"提案","question":"日進月歩、こういうコンピューター関係はどんどん技術が向上していく中で、やっぱりいろいろな提案があると思うのですが、今の課長の答弁ですと、今後も日立との契約を結んでいくという考えで私は捉えてしまったのですが、例えばもっといいサービスを提供されてくる業者があれば変更をしていくとかそういうことになっていくのか、そのあたりはどのようにお考えなのか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、今回、我々もこの提案を受けまして、これで自庁サービスから環境でやっていく中では、今考えられる現状では非常に効率的な方法だと我々も認識しました。そんな中で、ここを選んだわけです。","voiceIndex":21,"id":"exchange-006"},{"speaker":"武内委員","kind":"確認","question":"今の確認ですけれども、そうすると、今までずっと日立とのつながりの中で、継続性だとか、また今後の新しいものについても先を考えてもこれはいいだろうということで、基本的には随意契約でやられたということですよね。","respondent":"安藤文化スポーツ振興課長","answer":"そうです。","voiceIndex":23,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"私の質問としては、サーバーを自庁から移行したときに、セキュリティー対策というか、セキュリティーは今までと比べて危険度が増すとか、もしくはそれはあまり変わらない、もしくは日立という大きいところでやるから逆に安全になるのだとか、その辺の認識はどうでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"今、委員ご指摘のとおり、今まで自庁でセキュリティーの管理もしなくてはいけない。しかし、今回はそういう専門の環境で一括して管理できるということで、セキュリティーの部分についても非常に高いセキュリティーが実現されたと考えています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"武内委員","kind":"質問・要望","question":"それが外部の業者の中での管理になるわけですから、今、そうでなくても有名どころでセキュリティーが漏れただ何だとしょっちゅう週刊誌にも出ているわけですから、そういう面でも、普通に詳しい方からするとそういう専門的なところで管理したほうが安心なんだろうなという気はする反面、でも区からサーバーが離れたのだよということになると、そこはやっぱりそういう意識は持ちながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"井上副委員長","kind":"質問","question":"今も出ていたのですけれども、何で随意契約という判断をされたのかということと、もし、随意契約でなくて入札か何かでやったときには、継続した部分のデータみたいなものの、さらにこの３,７００万円ではいかないことがわかっていてそういうことなのか、その辺がよくわからないのですけれども、そこはどうですか。","respondent":"安藤文化スポーツ振興課長","answer":"それで今言ったレスポンスのよさだとか、画面の新しさから、メールのやり取りだったり、いろいろな機能をそこに組み込んでいくバージョンアップの機能ということで、従来行っていた日立を継続してシステムを使っていくと。","voiceIndex":28,"id":"exchange-010"},{"speaker":"井上副委員長","kind":"質問","question":"そういったところの経費削減みたいなところは、入札によって確実に上がるという判断があったのかどうかということはどうですか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、皆さん、ご案内のとおり、きゅりあんの予約システムの画面を見てもらうと、きゅりあんと出ます、きゅりあんの空き情報が見えるけれども、きゅりあんについてはまた別のシステムなので、予約システム画面から入れなくて、空き状況を見て、またきゅりあん登録団体として。","voiceIndex":30,"id":"exchange-011"},{"speaker":"井上副委員長","kind":"提案","question":"システムで変えられるという問題ではないかもしれないのですけれども、この予約システムをバージョンアップすることについて、利用者側から言うと運用の問題というので、改善提案があったとすれば、例えば今問題になっているのが、一度予約をしますよね、そのときにいろいろな諸般の事情でその日に使えないことが事前にわかっていたときに、何日後かに同じ施設、料金も変わらず、場所も変わらず。","respondent":"安藤文化スポーツ振興課長","answer":"今の部分については、大半が一つひとつの施設について条例を設置して、条例に基づいて何週間以内に入ってしまったら変更できませんだとか、施設の設備もそうなのですけれども、そういう部分は条例に基づいて、条例によって動いているというのがまず一つです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"今の話のつながりなのですが、課長はできるとおっしゃったのですが、日立で持っている全体のソフトをいろいろな面で、日立が全体としてやっていこうというときは、自動的に品川区のシステムにもそれが反映されるという、それはお金がかからないと認識しているのですけれども、今みたいな個別の比較的細かい要望を出したときに、日立がそれを無料で、必ずその都度応えてくれるという理解でいいのですか。","respondent":"安藤文化スポーツ振興課長","answer":"今回の仕様変更に経費がかからないというのは、先ほど言った施設が増えたり、一つの施設の中の運用で、例えば部屋がまた増えましただとか、時間が長くなりましたとか、従来のものが変わりましたという部分については一切かかりません。","voiceIndex":34,"id":"exchange-013"}]},{"id":"topic-03","title":"の「大井町再開発ビル駐輪場について」","agenda":"の「大井町再開発ビル駐輪場について」","exchanges":[{"speaker":"井上副委員長","kind":"質問","question":"駐輪可能台数なのですけれども、ラック数が７２台ということではないと思うのですが、ラック数が何台で、駐輪可能台数は何台なのか教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"今、ご案内のとおり、お子さんが乗る後ろのかごだとか、また、足のプロテクターにかなりの幅がとられているということで、１台ずつだと非常に危険なので、一つ置きに置かせて７２台となっているです。","voiceIndex":44,"id":"exchange-014"},{"speaker":"井上副委員長","kind":"質問・要望","question":"附置義務があるわけですから、建物の附置義務としてつくらなければいけなかった自転車台数を考慮すれば、きゅりあん利用者に同じように窓口でどこの施設を使いましたかということをちゃんと聞いた上で、利用券を渡すという対応ができると思いますので、こういうふうに何台といって使う団体と、ゼロの場合もあると思うので、そういう形での対策をぜひ要望していただきたいと思いますが、いかがですか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中でそれぞれ一律に割合数だとかそういうものは決められませんので、きゅりあんとしたら従来の経緯から、諸室について５台、それから大ホールとかそういうものについては１０台という形にさせていただいたところです。","voiceIndex":46,"id":"exchange-015"},{"speaker":"井上副委員長","kind":"提案","question":"だから、区としてそこは主張すればいいだけの話だと思いますので、平成２４年度の管理組合理事会と通常集会が終わったということであれば、次のときにここでどういう利用があるのか、やっぱり区民の方たちにも声を届けるように言っていかなければいけないと思うのですが、利用実績を見た上で、改善が必要であればそういった提案をぜひしていただきたいと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問","question":"区の要請を受けて、管理組合も西友も協力的にいろいろ措置をとってくれたというのがわかりました。お聞きしたいのは、自転車が通行の妨げやバス乗降客の通行の障害になっていたという課題が解決されたのか、その辺の成果を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"これは、私も所管の事業がきゅりあんでもありますので、常にチェックをしているところです。そうすると、全くありません。きれいになっています。専用のガードマンかわかりませんけれども、いて、チェックして、また、周りをコーンとチェーンで区別をしながらやっています。","voiceIndex":49,"id":"exchange-017"}]},{"id":"topic-04","title":"の「劇団四季新作ミュージカルおよび区との連携について」","agenda":"の「劇団四季新作ミュージカルおよび区との連携について」","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"劇団四季と区との連携では、商店街振興もあったと思うのですけれども、サンピアの通りをずらずら通られているのを結構見かけるようになったのですが、この辺の商店街の実績というか、どうだったのかなと思うのですけれども。","respondent":"米田商業・観光課長、安藤文化スポーツ振興課長","answer":"もちろん劇団四季との連携も定期的に図っていきますので、区も関与しながら進めていければと思っているところです。過去のバックナンバーから４本、５本コピーしましたけれども、その中で大井町を取り上げて商店街加盟店をご紹介させていただいたりとか、そういうところで劇団四季のほうも商店街をＰＲしていただいております。","voiceIndex":58,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"意見","question":"やっぱり大井町に来たというのがそういった月刊誌などでも知らされているのであれば、四季も一緒に大井町からいなくなるというのはあるのかなと。それで、やっぱり商店街、そういったまちの中でも、四季が来たということでいろいろな利用を広げ方もあると思うのですけれども、四季はどうなってしまうのかなと。","respondent":"安藤文化スポーツ振興課長","answer":"私の知る限りの情報では、一切そういうことはなくて、１月２７日まで最終公演をやって、それからその後も「リトルマーメイド」を春から上演をしていくと私は聞いています。","voiceIndex":61,"id":"exchange-019"},{"speaker":"武内委員","kind":"意見","question":"２番の2)の「美しい日本語の話し方教室」というところで、これは四季の単独でやっていただいているのか、文化庁とかいろいろな助成金が出ますよね、そういうのを活用されているのか、それとも単独なのか、わかれば。","respondent":"安藤文化スポーツ振興課長","answer":"これにつきましては、私の知る限りの情報では、劇団四季が全く独自に俳優が発音だとかそういうものを教えたというお話でして、単独でやられたと伺っています。","voiceIndex":63,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":19773,"voices":69}},{"id":"h24-20121127-7","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"厚生委員会","time":"午前１０時００分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ふれあい作業所の仮移転","agenda":"ふれあい作業所の仮移転","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お伺いをしたいことがあります。これはこれで非常にいい、それはしようがないことだと考えていますが、一つ教えていただきたいのは、シルバー人材センターがこみゅにてぃぷらざ八潮の４室を使っていたということでしたけど、どういう形で使っていたのかというのが一つ。","respondent":"永尾障害者福祉課長","answer":"あいている部分につきまして、現状では、畳やふすまなどの大物を予定して考えていたところでしたけれども、そこの面積を全部使うまでの需要はなかったと聞いております。そういうことで、いろいろ調整いたしまして、こういうようなご利用の仕方に決定したところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"ほかのところで、例えばこみゅにてぃぷらざ八潮なんかは、我が会派としても、非常にいろいろな考え方を持っているので、簡単に言うと、もともと、学習塾で、このぐらい簡単にあくのでは、という考え方もあったので、それはそれでほかでやりますけれども、我々もいろいろもう１回勉強させていただいて、今度、企画部と話せるところでやりたいと思っています。それだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"機能がどのように変わっていくのか、同じなのか、そこも伺いたいと思います。それからもう１点、平塚橋会館の建て替えによってということで、荏原分室が閉鎖されるというご説明ですけれども、複合施設ではありますので、荏原分室を残さなかった理由と伺えばよろしいのでしょうか、残せなかったと伺えばよろしいのでしょうか、その辺の事情がよくわからないので、そこの状況をご説明いただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"今後の規模ですけれども、西大井作業所のほうが３０人、西品川作業所が２０人ということで、合計５０人ということで、１０人プラスにする予定です。機能につきましては、現状が、西大井本部のほうは公園清掃と和紙の製品を作成しております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"全部を足すと、４０人から５０人に増えるということは歓迎したいと思うんですけれども、まだまだ利用状況や、今後のことを思うと、さらなる充実も必要だと思いますので、そこだけ述べておきたいと思います。それから、今後の話ですけれども、新しく西大井本部の改築が始まるわけですけれども、来年度予算に係わるのか、設計とか、完成とか、今後のスケジュールをご説明いただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"９月から１２月にかけて、西大井本部の解体の予定になっております。その後、建築の工事が平成２６年１２月ぐらいまで、今のところ、予定しているところです。その後、調整等を考えまして、平成２７年４月から西大井の本部を開所しようと予定しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"２点目なんですけれども、今、作業所の定員が１０名増えるということでお伺いいたしまして、これは、いわゆるＢ型と言われている作業の形態かと思いますけれども、この前、行政視察でも見に行った、例えばＡ型ですとか、あるいは一般就労の就労支援、こういったことも含めて、今回は作業所の再編みたいな中での定員増ということでしたけれども。","respondent":"永尾障害者福祉課長","answer":"まだ自立支援法内の施設になっておりませんので、これも一つの課題ではあったんですけれども、今回、広げることによって、就労継続支援Ｂ型のほうの事業所に移行する予定になっております。","voiceIndex":12,"id":"exchange-005"}]},{"id":"topic-02","title":"自殺予防・うつ病予防対策事業職員相談対応マニュアル","agenda":"自殺予防・うつ病予防対策事業職員相談対応マニュアル","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"それからもう１点、窓口の対応には専門性があるので一概には言えないんですけれども、区役所に相談にきて、話を聞いた方が後で僕ところにきて、よく伺うのは、制度上の仕組みであるとか、対象となるのかどうか、いろいろな話を聞く中で、やっぱり尋問されているようだという話を、どうしてもやっぱり、そういう受けとめをされる方も実際にいらっしゃるんですよね。","respondent":"福島品川区保健所荏原保健センター所長","answer":"その一つの教科書としても、この職員相談対応マニュアルというのをその中で使って、ゲートキーパー研修に成果を挙げたいと考えているというのが、今の現状です。","voiceIndex":19,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、これは引きこもりだったんですが、厚生委員会で行政視察に行ってきました。これは思いです。ほんとうに命をいろいろ考えている人からすれば、ゲートキーパーなんて言われたって、わけわからないわけで、それだったら命の門番といったほうが、よほど私はいいと思うので、そういうことも気をつかっていただきたいと、これはお願いだけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほどの委員の感想とダブるんですけれども、その質の担保というか、フィードバックで、ここがよかったとか、ここはもう少し改善しなくちゃいけないとかいう、その質の保証というか、具体的に効果がどうだったかという検証というのは、どういう形で入っているんでしょうか。そうでないと、やりましたということで終わっちゃうんじゃないかと思うんです。","respondent":"福島品川区保健所荏原保健センター所長","answer":"そういう意味もあって、連携すること、ネットワークづくりということが大切だと考えていますので、去年から、庁内の２４課の窓口職場の人たちに集まってもらって、どういう例があって、どういうことを連携しなければいけないかということをしています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"意見","question":"研修を受けて、実際にスタッフが実際にお困りの方といろいろお話をしたときに、研修を受けたことによって非常に質が上がったとか、ステップアップしたとか、そういうことがあるのかどうかということは、要するに自殺率が下がったとかではなくて、実際にそのときに悩んで相談にこられる方に、対応がこうやって上がったとか、こうやってよくなったとか、そういう質の面での何らかの評価というか。","respondent":"福島品川区保健所荏原保健センター所長","answer":"その中では、やっぱり人からものを聞くということが難しいということ、それから、相手の気持を推しはかって聞いてあげるということの難しさとか、そういうものを非常に実感している。","voiceIndex":24,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"大事な視点の質疑がありまして、私も、前の委員の質問と答弁の中はほんとうに大事だなと思っています。そういう中で、今のお話の中では、窓口職員がゲートキーパーの養成の研修を受けていらっしゃるということなんですが、いわゆる理事者、職場のリーダーは受けていらっしゃるのかなと思ったんですが。","respondent":"福島品川区保健所荏原保健センター所長","answer":"今のところは、どうしてもロールプレイとか、そういうものが中心になるので、１回にせいぜい５０名とか、６０名ぐらいしかできませんので、また回数を増やしたりして、極端な言い方をすると、全職員がその研修を受けてくれるまでずっと続けていきたいと考えております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほども、形骸化しないでほしいと言ったんだけれども、さっき、行政視察のお話もしたんだけれども、引きこもりは、そこの職員は１０年、その前に岡山に行ったときには３０年やっていると。我々が行政視察に行くということは、ある程度資料で、全国でそこが有名だから行こうとなるわけじゃないですか。多分、そんなところが、私はあるのではないかと思っているんで、考えていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-03","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"若林委員","kind":"質問","question":"３点あるうちの２点目は、下から３段目、「患者団体はこれまでに」とあり、「特定疾患への指定、及び」となっていますが、及びの前の点は、通常いらないのではないでしょうかという指摘をします。最後に、記書きの１、「患者が特に少ない希少疾病用医薬品（ウルトラ・オーファンドラッグ）」とありますが、本文中では、これが逆になっていますね。以上、３点ありますので、理事者も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":12839,"voices":51}}]);
